/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240312-3","meetingId":"r06-c-budget","date":"2024年3月12日","dateIso":"2024-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"そこでお伺いするのは、窓ガラスの飛散防止対策を行っている世帯はどのくらいあるのでしょうか。区として把握していらっしゃれば、推定でも構いませんのでお答えいただけますか尋ねました。","respondent":"平原防災課長","answer":"家具の固定等、家の中での措置を行っている方ということで、３５.９％という数字が出ております。この内数が窓ガラスまできちんと対応しているのではないかというふうに推定しています。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"３５.９％、思ったよりは多かったのですが、やはりそこまで高くはない数値なのかなと思いました。先ほど対策を行っている世帯の推定数は３５.９％とお伺いしましたが、もし目標数がありましたら説明を求めました。","respondent":"平原防災課長","answer":"在宅避難するための家具の転倒防止、ガラスの飛散、そういったところの危険性をお伝えさせていただいてきたところです。やはり窓ガラスの強化が必要ですので、どのぐらいの割合ということではなくて、全てやっていただくということが考え方にあるかと考えています。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"そうですね、１００％、皆さんやっていただくということがもちろん目標だと思うのですが、次年度どの程度というか、一気に全部１００％というのは難しいと思うので、段階的にはどのような感じか尋ねました。","respondent":"平原防災課長","answer":"段階的にといいましょうか、これは普及啓発ですので、やはり災害時の備えとしての必要性を強く訴え続けていくということが重要かというふうに考えてあります。","id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"１００％を目指す中で、窓ガラスの飛散防止フィルムが普及していない理由として考えられることとしては、区としてどのようにお考えか尋ねました。","respondent":"平原防災課長","answer":"浸透していないということでしたら、やはり防災の備えとしての窓ガラスの飛散防止の必要性が理解されていない、浸透していないということと、もう１つは、それが分かっていても、張る手間みたいなところを考えているのかなというふうには推測しています。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問","question":"４０万人を超える品川区民の多くが在宅避難することを考えますと、窓ガラスの飛散防止対策にも力を入れることは大切ではないかと思います。区としてはどのようにお考えか尋ねました。","respondent":"平原防災課長","answer":"区では、今回、２月に地域防災計画を大規模修正させていただきまして、その中で避難の基本として在宅避難を明確に打ち出させていただいたところです。区ではまず訴える…","id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"しかしながら、旧耐震建築の建物である場合は、倒壊や家具の転倒だけでなく、大地震により窓ガラスが割れてしまう危険性もあるとお聞きします。品川区の全世帯のうち、戸建てとマンションの割合、また、旧耐震の戸建ての現状などを説明を求めました。","respondent":"長尾建築課長","answer":"住宅全体としては５万棟ほどございまして、そのうち分譲マンションが１万棟強、そういった状況になっております。その中で窓ガラスの飛散に対しても、一定、対応できていると認識しております。","id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"より細かいところまで、自力で対策を行うことが難しい６５歳以上の高齢の方や障害のある方、対象を絞るような形で補助を行うことはいかがでしょうか。区としての考えを説明を求めました。","respondent":"平原防災課長","answer":"様々なところに防災も含んだような支援は各部署で行っているものもありますので、防災のところもいろいろなメニューがあります。各所管と連携して、どういう支援方策、どういう啓発方法があるのか研究してまいりたいと考えています。","id":"exchange-007"},{"speaker":"澤田委員","kind":"質問・要望","question":"続きまして、防災備蓄についてお伺いします。こちらの備蓄もあったほうがいいと思いますが、区としては、どうお考えか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"現状は、委員ご紹介いただいたとおり、おりものシートを来年度、備蓄してまいります。妊産婦についての備蓄に関しては、今後、検討してまいりたいと思います。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"昨年の第３回定例会での一般質問にて、日常生活用品や電化製品を準備した上でと要望させていただいた際に、区の見解として。日常生活用品や電化製品を常備するか、リース会社との提携等により早急に準備できる体制を求めますが、区の見解をお聞きできればと思います。","respondent":"伊藤災害対策担当課長","answer":"その１室に対しまして、まずもって暑さ寒さもあろうかと思いますので、エアコンをまず設置していくということで進めてあります。おおむね１か月程度ということで考えてはおるのですけも、そういった形で通常生活に戻れるような支援を進めてまいりたいと考えています。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"確認","question":"エアコンは検討され、毛布類は災害時に提供されるので、ほかの電子レンジ等を含めて考慮されることを確認させていただきました。現在の維持管理を公園課でされていますが、この２つの広場と公園の活用について、今後の計画と運用についてお聞きします。","respondent":"小川木密整備推進課長","answer":"区で今年度、隣の児童遊園と合わせて拡張整備を行っていく予定でございまして、その中で整備計画案を取りまとめているところです。今後の予定といたしましては、来年度、基本・実施設計を行いまして、令和７年度に工事を行う予定です。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ワークショップも開催されて、地域の要望に資する場にしていくということを確認させていただきました。この地域は、やはり防災に資する場としての要望を私もお聞きしています。","respondent":"高梨公園課長","answer":"区内に現在２７４ある公園、地域の一時集合場所等をはじめ、地域の皆様の防災活動区民組織の防災倉庫もあります。そういった意味で、幅広い防災拠点として使用されているという状況です。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"区内の公園が様々防災に資する機能として活用されていることを確認させていただきました。改めて豊町五丁目開放広場、今後のこの地域での安全の必要性から、防災に資する拠点としての可能性についてお伺いできればと思います。","respondent":"小川木密整備推進課長","answer":"現在、ワークショップを開催させていただいている段階で、その中で防災資機材倉庫等を設置すると聞いてあります。それともう１つの開放広場に関しましては、今後、周辺の皆様のご意見を聞きながら検討していきたいと考えています。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"私からは、３４９ページのＰａｒｋ－ＰＦＩの導入、３６１ページの防災訓練経費、３６３ページの携帯トイレ全戸配布経費について伺います。携帯トイレ全戸配布経費について伺います。","respondent":"平原防災課長","answer":"災害時に主に下水道の破断によりましてトイレの確保が課題となるということは以前から認識していたところです。１月１日に発生いたしました能登半島地震で、区民一人一人が平素から考えて家庭内備蓄が進むよう、この事業を立案したところです。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問","question":"他区の事例もあるということで理解いたしました。区は、災害発生時の在宅避難者をどのぐらいと想定していますでしょうか、お教えください。","respondent":"平原防災課長","answer":"令和４年度の東京都の被害想定では、避難者数がピークになる時点での在宅避難者数は、区内で約３０万人、具体的には２９万１,３６２人と想定されているところです。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問","question":"全体約４０万人に対して３０万人程度という、７０％強、多いですね。１人２０個ですが、何日分と想定しているのでしょうか、お教えください。","respondent":"平原防災課長","answer":"今回、全区民に配布する予定の２０個ですけれども、私ども、３日分と考えています。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"災害の備えは、最低３日分が基本だと思いますので、最低限はカバーできると考えます。１人当たり７日分を推奨しており、不足分はどのように考えておりますでしょうか、お教えください。","respondent":"平原防災課長","answer":"私どもも今回の３日分は、３日分の備蓄品を配るというよりは、区民一人一人に考えていただくきっかけとしてお渡しするというふうに考えてあります。それ以外のものを含めましても、区民一人一人がご準備いただく…","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"この配布の機会を通じて皆様に気づいてもらい、各自での購入を促すことをとてもよいと考えます。配布は、来年度のいつ頃を予定しているのでしょうか、お教えください。","respondent":"平原防災課長","answer":"令和６年度に入りまして契約手続を進めさせていただきまして、同封する予定の「しながわ防災ハンドブック」、１０月頃を目途に進めさせていただければと考えています。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"少し時間があるので、分かりやすいものに見直しということはいかがでしょうか。いかがか尋ねました。","respondent":"平原防災課長","answer":"あっ旋チラシは同封する予定はございませんが、ご家庭ではどういうような、例えば。こちらは内容については随時見直しを行っているところですけれども、よりよいものとなるように、今後も検討を進めてまいりたいと考えています。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問","question":"本件は、最終日の総括質疑のときにお伺いいたします。次に、防災訓練経費について伺います。","respondent":"伊藤災害対策担当課長","answer":"１３地区で行う９月から１１月まで開催されました各地区防災訓練につきましては、今回、１３地区中７地区の訓練実施がございました。基本的には、防災区民組織が主体となっておりますので、協力しながら実施を進めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"周知と参加のインセンティブについては、これも最終日の総括質疑の際にお伺いいたします。そして最後、Ｐａｒｋ－ＰＦＩの導入ですけれども、時間がもう少なくなりましたので、これはまたの機会でお伺いさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"３３９ページ、３４２ページ、都市開発費について伺います。伺いますけれども、区民避難所等と同様、銭湯も入れていただくよう東京都に働きかけてほしいと求めました。","respondent":"平原防災課長","answer":"発災直後に避難者が集まるようなところを重要施設というような形で、まず優先的に耐震化を進めていったというふうにお伺いしております。最終的に一義的には東京都が決定していくものと考えていますけれども、そういうお話…","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"毎年２,４００万円のランニングコストを区民のために使いたいと、でも、そのためにはどうすればいいか。伺いますけれども、２,４００万円余の財源は、国なのか、都なのか、区なのか、その財源について伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"航空機騒音測定委託の費用ですが、国も、東京都も、独自に航空機騒音測定を行っていますが、区としてもしっかり測定をして区民に提示するということで、これは区の単費で行っているものです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"２,４００万円余ですから、これはぜひ区長、まずは、止めるためには区長が国に中止を求める。ぜひ中止を求めていただきたいのですが、お願いします。","respondent":"鈴木都市計画課長","answer":"区民負担軽減につながる取組の早期の提示と実施を強く申し入れ、重く受け止めると、しっかり検討していきたいという回答をいただいたところです。区としても、しっかり今後もこうした区民負担軽減につながる取組を、国に継続して求めていきたいです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ区長自らが国に中止を正面から求めることを強く要望して、次の質問に移ります。それと、区としては、今度の第五次計画で、どの路線、どの道路の整備を希望する考えなのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"補助１６３号線、所管のほうで検討が継続して進められておりますが、具体的な道路着手にはまだ至っていないというような状況です。第四次が令和７年度までですので、市を含めて、検討を全体で進めていくということになろうかと思います。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、準備組合に入らないと資料を渡さないと準備組合の事務局が触れ歩いていることを区は把握していますか、伺いたいと思います。当該準備組合でこのようなことが行われているのですから、そのことを求めますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"ですので、区といたしましては、そうした組織に対して、情報の差がないように、丁寧な対応をしていただきたいというところは求めているところです。これにつきましては、引き続き求めてまいりたいと思います。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはおかしいと思うので、改めて伺いますけれども、これ、地権者にとっては生活、財産、未来を左右する計画なのです。それをやるべきだと思いますけれども、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"これについては、区は強制権がないのですけれども、そういったところは確認して進めているというものになります。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"それで、区民の方から、平日８時から１０時、通勤とか、お仕事で使う時間帯は、なるべく工事を避けていただきたいというようなご要望がありました。何とか８時から１０時の２時間を分散させて、取組をぜひ行っていただきたいと思うのですけれども、区の見解はいかがか尋ねました。","respondent":"森道路課長","answer":"周辺の歩行者の方の安全を第一に考えながら、迂回ルートといいましょうか、そういったものも含めて実施をしています。８時から１８時の間で、引き続き、通行される方の安全な利用を前提に進めていければと考えております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"続いて、防災普及教育費、マンション防災についてお伺いいたします。これは希望されるマンションということを伺ったのですけれども、例えば、周知方法についてお知らせください。","respondent":"平原防災課長","answer":"次年度、品川区ではマンション防災用のハンドブックにつきましても全面改定する予定で今進めております。それを配布いたしますので、そういったところと合わせながら周知に努めてまいりたいと考えています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"ということで、品川区がマンションと町会のつなぎ役を果たして防災訓練をやっていただくということはいかがでしょうか。この都の事業をいいきっかけとして、防災訓練に新しい人を集めるということにもつながりますので、いかがお考えか尋ねました。","respondent":"平原防災課長","answer":"先ほどご紹介させていただきました新しいマンション防災ハンドブックでは、やはり訓練というのは１つ重要なポイントになると思います。東京とどまるマンション普及促進事業、今回、制度活用して強いマンションづくりに資するように努めてまいりたいというふうに考えてあります。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。区に相談がありましたら、ぜひアドバイスなどをしていただけたらいいなと思うのですけれども、その点はいかがお考えか尋ねました。","respondent":"平原防災課長","answer":"私ども防災課には、マンション防災アドバイザーがおりますし、それ以外の職員も、町会とマンションのつながりというものは非常に重視していますので、何かお困りのことがありましたら、何なりとご相談いただければというふうに思ってあります。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"一般質問等々で、私およびほかの議員も、東八潮、その近接の東京国際クルーズターミナルとの連携ということを提言されております。１５８ページに記載をしていただきましたけれども、１５８ページに書いてあるのですけれども、この状況はどうなっておりますか尋ねました。","respondent":"鈴木都市計画課長","answer":"マスタープラン、東八潮の有効な活用方針ということで、東八潮地区につきましては、現在、都立潮風公園ですとか、船の科学館があります。基本的には、そうした動きを所管として常にアンテナを張って注視していきたいです。","id":"exchange-031"},{"speaker":"せらく委員","kind":"質問・要望","question":"反対意見も１０件ほどありますが、公園遊びが気になる住民にとっても、公園の利用に対する理解を得るための工夫が求められています。先日１１月の建設委員会の資料でも、公園の利用について、川崎市や足立区の事例を取り上げていることを確認いたしました。","respondent":"高梨公園課長","answer":"ホームページ等も含めて、その辺りの周知を図って、ボール遊びのできる部分の拡大というところで取組をしてまいりたいというふうに考えてあります。で、ほかの自治体の例等をこれからも研究しながら、よりよい公園利用の仕方について考えてまいりたいというふうに考えてあります。","id":"exchange-032"},{"speaker":"せらく委員","kind":"確認","question":"お問合せがあった際には、しっかりそういった詳しいところ、細かいところのご案内をされているというふうに確認をいたしました。議事録などでも確認をさせていただいたのですけれども、個別にご相談だとか、そういったことをさせていただけるのか尋ねました。","respondent":"高梨公園課長","answer":"周辺にお住まいの方からは、しっかりとそういった注意看板がないと、苦情等を言えないというような声もいただいているようなケースもあります。その公園に合わせて、これからよりよい看板の在り方については考えてまいりたいというふうに感じてあります。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問・要望","question":"オンラインで確認できるようにしてほしいという以外にも、予約のない時間に一般開放してほしいというようなご要望がありました。一般開放している運動施設と、していないところでは、どのような違いがありますか尋ねました。","respondent":"高梨公園課長","answer":"その他の公園、運動施設についても、利用の状況を見ながら判断してまいりたいと考えております。","id":"exchange-034"},{"speaker":"せらく委員","kind":"確認","question":"開放情報をオンラインで確認という部分なのですけれども、Ｘで一般開放情報を上げているのをたまに確認しています。各施設の情報を一覧でシームレスに見ることができたら、利用者は助かると思うのですけれども、この２点についてお願いします。","respondent":"高梨公園課長","answer":"ご案内いただきましたとおり、中央公園につきましては、委託業者のほうで、現在、Ｘで発信をさせていただいてあります。現在、今、委員からご提案のありました一覧で見られる形も含めて検討を進めてまいりたいというふうに考えております。","id":"exchange-035"},{"speaker":"せらく委員","kind":"提案","question":"団員の皆様へインフルエンザの予防接種の費用を助成するなど、感染症対策を提案しますが、いかがでしょうか。こちらはいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"消防団の皆様におかれましては、また、災害時には率先して災害活動に対応していただいている心強い存在であると我々も認識しております。我々にとっても非常にマイナスになってしまうということですので、引き続きなのですけれども、研究をさせていただきたいと考えております。","id":"exchange-036"},{"speaker":"横山委員","kind":"確認","question":"１点目に、しながわ水族館運営費についてお伺いいたします。２点目に、空港環境経費についてお伺いいたします。","respondent":"高梨公園課長、鈴木都市計画課長","answer":"そういったネットワーク等を活用して、全国からの支援等を受けながら、飼育している魚類、動物の生命確保に取り組んでまいりたいと考えています。拡大した内容について、現在、基本設計の中で検討を進めているところです。 環境影響に関する予算ですが、基本的には、空港環境経費です、騒音に関する委託経費と、その他の事務費です。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"近隣区としてリアルタイムで把握していただきたいというふうに要望いたしますが、他の近隣区などと、区のお考えをお聞かせください。３点目に、防災対策総合推進費についてお伺いいたします。","respondent":"平原防災課長","answer":"こちらで充足するというふうに考えてありますが、何とでも対応できるようにするため、協議も進めているところです。関係機関との連携ですけれども、令和４年度に実施いたしました東京都との合同総合防災訓練の中で、そういったところの協議を深めているところです。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"４点目に、樹木健全度診断事業についてお伺いいたします。区内の状況を説明を求めました。","respondent":"森道路課長","answer":"本事業につきましては、これは区内で２,３６５本ありますけれども、これを１０年間で樹木医による外観診断を順次行っていく。その中で、Ｃ判定として伐採をする必要があれば、都度、対応していくということにしております。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"最近、急に危険木が増えた理由について、世田谷区の事例なのですけれども、近年の猛暑で樹勢が弱まっていたところに病虫害が予想以上に進行したためというふうに指摘する声があるとのことですが、区内における樹木のナラ枯れの発生状況が分かりましたら、説明を求めました。","respondent":"森道路課長","answer":"ナラ枯れにつきましては、発生しておりません。区内で対象樹木が８本しかございませんので、引き続き経過観察を進めてまいります。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"樹木診断の結果や点検の結果で被害が確認された場合は、しっかり対処してほしいと求めましたので、お願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"えのした委員","kind":"質問・要望","question":"３６５ページ、３６３ページ、避難行動要支援者経費についてお伺いします。防災対策について様々要望させていただき、予算の目玉でもある約４０万人の全区民に携帯トイレを１人２０個ずつ、非常に歓迎しております。","respondent":"平原防災課長","answer":"自助、品川区ならではの内容ということでお作りさせていただきまして、必ずしも東京都のものとかぶらないようなことで考えてあります。例えば家族数に応じて郵送であったりとか、宅配を活用とか、そういったやり方で考えているところです。","id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"こちらもパンフレットの予算に入っておりますが、全面改訂とご答弁がございました。これ、ハンドブックとは別のものになると理解しておりますが、内容も含めてお知らせ願えますか尋ねました。","respondent":"平原防災課長","answer":"今ご質問にございましたとおり、マンションの住民向けと、マンションの管理組合向けの２種類を作成する予定です。少し言葉はあれですけれども、薄味になってしまうところもありますので、マンションに特化したものという形で作成することと考えています。","id":"exchange-043"},{"speaker":"えのした委員","kind":"質問","question":"先日も防災フェアに伺わせていただきましたが、消防車に試乗できるなど、楽しみながら防災を学べるよい事業だと評価しております。防災ハンドブックや携帯トイレを展示することによって周知啓発が広がると考えますが、区のご見解をお知らせください。","respondent":"平原防災課長","answer":"しっかりと普及啓発を進めてまいるところで考えてありますが、他自治体の事例なども見つつ、研究してまいりたいというふうに考えてあります。実際には、あるいは触っていただく等でご理解いただいて…","id":"exchange-044"},{"speaker":"えのした委員","kind":"質問","question":"先月、地元の小山小学校での避難所訓練に参加してきましたが、防災トイレ、自動排泄処理できるラップポンというのですか、拝見してまいりました。最新式で、いいトイレだとは思うのですが、こちらを採用された理由などがありましたら、お知らせください。","respondent":"羽鳥防災体制整備担当課長","answer":"地域の方から、設置や使用方法が難しいというお声もいただいております。そういった関係で、現在、各区民避難所に４台ずつ備蓄しています。","id":"exchange-045"},{"speaker":"えのした委員","kind":"質問・要望","question":"大震災が起きた日から１週間ですとか、これからも発災時のトイレ問題は、より一層の取組を考えていただけるよう要望いたします。こちらは何棟分の予定になりますか尋ねました。","respondent":"平原防災課長","answer":"令和６年度から実施予定ですマンションへの防災チェアの提供事業ですけれども、区内にあります３階建て以上かつ１５戸以上の住戸を有するマンションを対象といたしまして、全体で３,２００棟を対象として、こちらを３年計画で実施しようというふうに考えてあります。","id":"exchange-046"},{"speaker":"えのした委員","kind":"質問・要望","question":"より一層のマンション防災の拡充を要望いたします。続けて、中学生向け防災プロジェクトについてお伺いいたします。","respondent":"平原防災課長","answer":"中学生向け防災プロジェクトですが、令和６年度の事業といたしましてご提案させていただいているものです。それを３か年にわたって使っていただくということで、また、令和６年度は教材の作成を進めていくというふうに考えてあります。","id":"exchange-047"},{"speaker":"えのした委員","kind":"質問・要望","question":"企業と連携してということで、こちらは一般質問でも要望させていただきましたが、地域の方からのお声もすごく多かったです。そして、こちらは、品川区としては、都市型災害としての備蓄品の見直しなどはありますか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"多様な避難に対応して、皆様が安全に安心して避難生活を送ることができるよう、必要な物資を備蓄していく必要があるかと考えております。引き続き、避難所の生活環境改善に向けて、備蓄品の見直しも行ってまいりたいと思います。","id":"exchange-048"},{"speaker":"えのした委員","kind":"確認","question":"備蓄品の見直しの確認がとれました。こういったところにも持ち運びができるスターリンクは、情報収集する上で大変役に立つと考えますが、区のご見解をお知らせください。","respondent":"平原防災課長","answer":"衛星通信サービス、スターリンクにつきましては、東京都が新年度事業で全区市町村に１台ずつ配備という形で聞いてあります。都から提供いただきました機材をしっかりと検証してまいりたいというふうに考えてあります。","id":"exchange-049"},{"speaker":"えのした委員","kind":"意見","question":"最後、時間が少なくなりましたが、避難行動要支援者、こちらは先日も地区の避難誘導ワークショップを受講してまいりました。出席者は、まだかなり理解されていないなという実感がありますが、この予算、取組の内容をお知らせくださいとの意見を述べました。","respondent":"平原防災課長","answer":"こちらにつきましては、特に福祉との連携についての強化をしています。","id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"特に防災に特化したかまどベンチの設置や、トイレの設置もできるのではないかというご要望もあるようですので、区の見解を伺います。このスケジュールを伺いたいと思います。","respondent":"高梨公園課長","answer":"浜川北公園におきましては、現在、設計の中で検討している状況です。基本設計と実施設計、１年間かけて設計作業を行い、令和７年度から８年度にかけて工事を行うというようなことで考えてあります。","id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"浜川北公園に関しては、マンホールトイレを設置ということが具体的になっていると確認いたしました。自転車置場の設置とか、そこら辺の配慮もしてほしいと求めましたが、いかがか尋ねました。","respondent":"高梨公園課長","answer":"区も間にしっかりと入って、円滑に工事が進むよう、搬入車両等の調整を行うといった考えです。駐輪場につきましては、東大井公園の立地等を鑑みて、自転車置場についても設計の中でしっかりと考えてまいりたいというふうに考えてあります。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"３月中に配布ということで、東京都のホームページで確認させていただきましたところ、品川ナイズされた内容をぜひお願いしたいと思います。区の公式ＬＩＮＥにも日頃の防災というものがありますが、そこにもぜひ掲載をしていただくこともご検討ほしいと求めましたが、見解を伺います。","respondent":"平原防災課長","answer":"内容につきましては検討しておりますので、まだ詳細は固まっておりませんが、しっかりと対応させていただきたいと思います。全ての品川区の防災普及啓発の根本とするものにしていきたいと考えていますので、様々な場で表に出していきたいと考えています。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"設置型というのでしょうか、どういう内容がそこに備えられているのか、お聞かせください。どういう意図で品川区が送るのかということをしっかりと分かっていただくことが必要となりますので、町会・自治会、併せて見解を伺います。","respondent":"平原防災課長","answer":"施工が必要だということで、私どもは、エレベーターチェアを簡易的に置けるような形で考えたところです。備蓄の考え方が分かるようにすると同時に、委員ご指摘のとおり、区の意図が広まるように周知に努めてまいりたいと考えています。","id":"exchange-054","title":"町会・自治会支援"},{"speaker":"おぎの委員","kind":"質問","question":"区民の安全を守るため、様々なことを想定した結果が、来年度の予算に反映されていることが伺えます。首都直下地震や、区内の避難所がいっぱいになってしまった場合の区民の避難先の１つとして検討してみてはどうでしょうかというだけでは。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"住民同士の草の根交流の実績を踏まえ、ぜひこの縁を大切に、新しい防災相互協定先として検討してみることはいかがでしょうか。区の見解をお聞きします。","respondent":"平原防災課長","answer":"ご提案ありがとうあります。協議させていただいた上で、しっかりと協議を開始させていただきまして、双方の実情を合わせさせていただければというふうに思ってあります。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"続きまして、３６１ページ、地区総合防災訓練についてお聞きします。こういったマンションと地域の方との大規模な防災訓練などにもこちらの補助金は使えるのか尋ねました。","respondent":"平原防災課長","answer":"町会とマンション住民、こういったものの連携が進むということは防災にとって非常に重要ですので、様々な手段を使いながら私どももそういったところを働きかけてまいります。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"質問","question":"３６５ページ、３６７ページ、避難所運営について質問いたします。区は、具体的にどのようなものを検討しているのか尋ねました。","respondent":"森道路課長","answer":"もう１つは、ＱＲコードを点状ブロックに設置して、そこまでのルートを点状ブロックごとに案内してくれるというものです。こちらは先ほどとは少し違って、ルートで誘導に主眼を置いたような特徴のものなのかなというふうに考えています。","id":"exchange-058"},{"speaker":"ひがし委員","kind":"質問","question":"２種類検討しているということで、既に音声を使用した移動支援の機械もあるが値段が高いといった課題があるとのお話を聞いております。今回、品川区が検討しているものは、スマホがあれば、アプリを使用し無料で利用できるという認識でよろしいか尋ねました。","respondent":"森道路課長","answer":"こちらにつきましては無料のアプリで、先ほど言いましたＱＲコードにつきましては、ｉＰｈｏｎｅのみの対応と、今のところそうなっておりますけれども、無料のアプリをダウンロードするだけで対応可能というふうに聞いております。","id":"exchange-059"},{"speaker":"ひがし委員","kind":"質問・要望","question":"これまで地面に設置していた点字ブロックをＡ４の用紙に印刷、避難所生活の中でも自立した生活ができるようになったというような記事でした。ぜひ災害時にも活用できるといった視点も考えながら、この事業を進めていくよう求めますが、区の見解を説明を求めました。","respondent":"森道路課長","answer":"先ほど申し上げました幾つかの黒い輪を設置するというような技術に関しましては、例えば避難誘導みたいなことも考えたいというお話をされていました。今のお話を受けまして、所管ともお話をしながら協議していきたいと考えています。","id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そこで、障害者団体の方にもお話を伺いました。区としてアプリを選択するかについて、今後どのような段階を踏んで進めていくのかについても伺います。","respondent":"森道路課長","answer":"それから、道路課で実際に視覚障害者の方がしっかりと自分で歩いていけるということを考えまして、今回はこの２つの事業を確認したところです。今、そういったものも来年度しっかりと研究しながら、どういったものがいいのかということは総合的に考えていければなと思います。","id":"exchange-061"},{"speaker":"ひがし委員","kind":"確認","question":"最後に１点だけ確認をさせてください。この点について、区としてどのように考えているのか、最後に説明を求めました。","respondent":"森道路課長","answer":"こちらの点字ブロックの音声による誘導につきましては、音響式の信号機とは別の形で、区のほうでしっかりと進めていきたい、検証していきたいというふうに考えておりますので、それぞれの事業の中で考えていければと思っています。","id":"exchange-062"},{"speaker":"ひがし委員","kind":"質問","question":"次に、立会川・勝島地区まちづくりについて伺います。今回、設置に当たって、安全性についてどのように考え決定したのか、また、真ん中、このルート２にした理由、人道橋の目的について伺います。","respondent":"森道路課長","answer":"２回、地域の方に説明会をさせていただきまして、都市計画の決定を行ったものです。安全対策につきましては、令和５年７月の説明会の中でも、地域の方から安全性に対する意見が出ました。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私も区民の方々からお話を伺いまして、防犯の観点から、安全性を確保してほしいというようなご要望をいただきました。現在の対応状況については確認させていただきましたので、今後、区民の方々の声を聞く機会があるのかという点について確認をさせてください。","respondent":"森道路課長","answer":"そういったものについて、来年度、デザイン募集を考えているところです。委員からお話がありました安全性だとか、防災性だとか、そういった部分の意見を聞いて反映していければというふうに考えています。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ区民の方々、不安の声があるということを受け止めていただきながら、この声に対して丁寧に説明をしていただくように求めて、次の質問に移ります。次は、女性視点での備蓄、避難所運営について伺います。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"私からは、女性視点での避難所運営についてお答えします。５２か所全ての区民避難所におきまして、授乳室など、女性に配慮したスペースを用意させていただいているような状況です。 来年度以降、おりものシート、そういったものを備蓄してまいります。今後とも必要なものに関して検討してまいりたいと思います。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問","question":"今回、女性視点での備蓄、避難所の見直しに向けて、女性視点の取り入れ方は、どのように進めていく予定なのかを伺います。区として課題があれば、併せて説明を求めました。","respondent":"平原防災課長","answer":"私どもは入らずに、女性だけで考えていただいて、その中で出てきた意見を今後の施策に生かすというような形で考えさせていただいているところです。そういったところに課題があるというふうに考えてありますので、今後、しっかりと見直しを進めてまいりたいと考えています。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひその方々を中心にしながらも、区民の声を拾い、女性視点での防災避難所に対する意見を取り入れていくよう求めます。そのような方々にアンケートをとりながら、備蓄、そして避難所運営についても考えていく必要があるかと思いますが、いかがか尋ねました。","respondent":"平原防災課長","answer":"様々なところから広くとっていく必要があるというふうに考えてありますので、今後新しい形でどのようにできるかも考えながら、様々な方法を通じて女性のお声を聞いていきたいというふうに思ってあります。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"私は、ぜひ災害協定を目指してほしいと求めましたが、いかがでしょうか。併せて、災害時について、キッチンカーにどのような役割を期待しているのか、区の基本的な考えを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"そういったもので対応していただくようになりますけれど、そういったところに民間の力を借りたいというふうに考えています。災害時の協力協定などを活用して、キッチンカーも含めて、民間の飲食業界の方々と連携をしていきたいというふうに考えてあります。","id":"exchange-068"},{"speaker":"中塚委員","kind":"提案","question":"温かい食事の提供は、思い切って外からの支援策を強化する必要があると思って、キッチンカーの活用を提案させていただきました。品川区が被災地となったときの対応など、支援策の具体化を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"羽鳥防災体制整備担当課長","answer":"ただ、災害時は被災者同士での支援ということで、やはり民間の力を有効に活用していくというのは必要なことになってくるかと思います。今後とも、民間の力を活用できるように、協定も含めて検討してまいりたいと思います。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"協力いただけるキッチンカーに対しては、日常的に公園での営業に対して許可を出すなどの対応はできないのか、検討できないのか伺いたいと思います。そこで得た様々な連携を災害時に発揮していただく、こうした仕組みづくりができないものかと思いますけれども、いかがか尋ねました。","respondent":"高梨公園課長","answer":"今、地域との連携であったり、戸越公園におけるエコルとごし等の連携でキッチンカーを出しているというような限定的な場面での活用があります。災害時におけるキッチンカーとの連携、防災部門とも連携の上、今後の可能性について検討してまいりたいと考えています。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"事前の災害協定や防災訓練や、そうした仕組みをつくることと同時に、日常的にも協力関係を積み上げていくことが必要だと考えています。キッチンカーの業界も今大きく広がっており、ぜひ協力関係を築いてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"せお委員","kind":"提案","question":"私が議員１年目のときに、障害があってもなくても、みんな一緒に遊べるインクルーシブ公園を要望いたしました。この３公園は、どういった形で子どもたちや地域の皆さんのご意見、ご要望を反映していくのか尋ねました。","respondent":"高梨公園課長","answer":"予算書に記載しています３公園についてですが、目玉焼きのトランポリンということで、設置を進めているところです。インクルーシブ公園として設計を進めてまいりますが、こちらにつきましては、インクルーシブ公園として整備をしたいというふうに考えてあります。","id":"exchange-072"},{"speaker":"せお委員","kind":"質問・要望","question":"いつも苦情が多い公園のほうにも対象を広げることを要望させていただいたり、町会・自治会のほうに周知をということも要望しています。現状と課題だったりとか、今後の展望をお聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"令和４年度から、公園の通報システムを開始いたしまして、道路と比べると絶対数がまだまだ少ないというところが課題だというふうに考えてあります。これから周知、通報していただく方を増やして…","id":"exchange-073","title":"町会・自治会支援"},{"speaker":"せお委員","kind":"質問・要望","question":"負担のないように、負担が減らせるようにするための何かそういった利用も考えられたらなと思って、そこは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"つる委員","kind":"質問","question":"３５２ページ、３４７ページ、公園・児童遊園費について伺っていきたいと思います。これを教えていただくことと、桜の本数、現在において何本あるか説明を求めました。","respondent":"森道路課長","answer":"今後とも、そういったところがあれば、しっかりと適用を考えていきたいというふうに思っております。桜につきましては、３,８６１本のうち１,４６７本、３８％です。","id":"exchange-075"},{"speaker":"つる委員","kind":"質問・要望","question":"これは毎度確認していますが、１本でも多くつくっていただきたい、これは引き続きお願いしておきたいと思います。２０２４年度でやる、そしてアピールについては、どのように展開していくのか説明を求めました。","respondent":"高梨公園課長","answer":"このような状況下、区としても、かねてから力を入れて取り組んでまいりました緑化や雨水流出抑制といった取組に加えまして。今後、こういったグリーンインフラについて、区民に広く知っていただくように、広報に力を入れてまいりたいと考えています。","id":"exchange-076"},{"speaker":"つる委員","kind":"質問・要望","question":"２万本ですか、そういう取組もやっていて、これは第１回のグリーンインフラ大賞を受賞されたというところであります。マンホールカードについて伺っていきたいと思いますが、いろいろ確認ができるわけでありますが、事項別明細書を確認すると。","respondent":"森道路課長","answer":"マンホールカードにつきましては、今ある２つの種類を追加で印刷していく予定です。","id":"exchange-077"},{"speaker":"つる委員","kind":"質問","question":"もう一方、併せて伺ってしまうと、３月３１日で１６のキャラクターが最後です。この辺りについての新たなキャッチを使ったときの考え方とか、新たなデザイン化とか、カードの作成について説明を求めました。","respondent":"森道路課長","answer":"それから、マンホールにつきまして、「わ！更新のタイミングで変更していく、数も少ないので、それは所管としっかりと調整していければというふうに考えております。","id":"exchange-078"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ権利関係だとか、いろいろな観点で確認いただきたいというところと、「わ！限定でありますけれども、そういった取組をやっているところがありますので、いろいろな展開をぜひ引き続きご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問","question":"３５１ページ、３４９ページの勝島人道橋工事、いければいきます。会社法上、株式会社の所有権は株主にあるという認識でよろしいか尋ねました。","respondent":"高梨公園課長","answer":"Ｐａｒｋ－ＰＦＩの制度で、公園の中で収益施設を出していただく会社につきましては、区と所有権関係を結ぶわけではございませんので、引き続き、その会社の所有、株主の所有ということで間違いありません。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。再民営化とか、公共化が進んでいるという個人的な理解なのですけれども、その辺の受け止めはいかがか尋ねました。","respondent":"高梨公園課長","answer":"やはり民間としっかりと連携して、しっかりと連携して、そのような時代になってきているのではないかというふうに思います。","id":"exchange-081","title":"町会・自治会支援"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ＰＦＩでの入札価格は４０％割高で、透明性も悪化、問題点が改善するまでＰＰＰを広い分野で集中的に使うべきではない。そういったことをぜひ考慮していただきたいのですけれども、今、どのような進め方をされていますか尋ねました。","respondent":"高梨公園課長","answer":"やはり地域の皆様のご同意、同じ方向を向いてつくっていかないと、公園の中で皆さんに楽しんでいただく施設はできないというふうに考えてあります。区もＰａｒｋ－ＰＦＩで選定された事業者がやる事業について…","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望です。理由をお聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"プール等が必要となるため、次世代のしながわ水族館の開発においては、その規模から適切ではないと考えられた点。それと３つ目は、昨今のイルカをはじめとした海洋哺乳類にまつわる情勢の変化といったところの３点を挙げさせていただいているところです。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"提案","question":"これから目玉をつくっていかなくてはいけないと思うのですけれども、そこで私が提案したいのは、カワウソです。ショーとかではなく、見ていて楽しめる展示になると思うのですけれども、そういった提案はいかがか尋ねました。","respondent":"高梨公園課長","answer":"どういった展示にしたらよいかといったところを考えているところですが、そういった展示の見せ方で、多くの方に来ていただく施設を目指しています。現在も２頭のカワウソがしながわ水族館におりまして、ご提案いただいた内容等についても…","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"提案","question":"２匹ぐらいだったらどこでもいると思うのですけれども、もし何か提案できることがあればとか、ぜひその点もお考えほしいと求めました。最後に何かご答弁があればとの意見を述べました。","respondent":"高梨公園課長","answer":"様々な声を聞きながら頑張って検討してまいりたいと思います。","id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３４３ページの市街地整備事業費に関わって再開発について、３４９ページ、（仮称）勝島人道橋整備工事の中止を求めて質問します。安藤委員の質疑の続きですが、準備組合に入っていなくても、関係権利者には情報提供すべきだと思いますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"やはり準備組合などに入りたくないとかといった形、または、それぞれ様々な諸事情でご不安を抱えている方がいらっしゃるかと思います。区のほうにお問合せいただけましたら、組合と調整等はあるかと思いますけれども、そういった不安は取り除いていきたいと考えております。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"今後の自分の身の振りを考えることもできないということになりますので、区として組合に注意すべきだと思いますけれども、いかがでしょうか。これはやめさせるべきだと思いますが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"準備組合に入らないと情報が手に入らないですが、準備組合は権利者に対して一般的な説明会も開催しています。ですので、情報が手に入らないということはないというふうな区の認識です。","id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"組合が情報提供しないということであれば、区が資料を届けるべきだというふうに思いますけれども、いかがでしょうか。同じ権利者で、組合に入っているか入っていないかで情報量が違う、差別されていいのかと思いますので、伺いたいと思います。","respondent":"中道都市開発課長","answer":"先日、武蔵小山でも、説明会、中間報告会等がございました。そうした中で、区としては、調整してお届けできるものを進めていきたいというふうに考えております。","id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、行われてきた地区ではどうかということで伺いたいのですけれども、１つの資料として、再開発本組合設立時の同意率を伺います。戸越五丁目１９番地区、区役所近くの大井一丁目南第１地区、同意率を伺います。","respondent":"中道都市開発課長、大石まちづくり立体化担当課長","answer":"私たちもそういった説明会等も参加していますが、様々なご質問をして、詳細な部分も組合のほうに問合せをしております。ですので、区民の方も、自分の今後の生活について、きちんと向き合って進めているものというような認識です。 戸越五丁目１９番地区についてお答えいたします。当該地域は、所有権者が１３名、借地権者が８名、同意者といたしましては、所有権者が１１名、借地権者が８名となっております。","id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"先日行われた第２地区の説明会でも、再開発に反対だという発言が公然と行われたと聞いています。武蔵小山第２地区も予算化するのはなぜか、第１地区が予算化されていないのはなぜか、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"市街地再開発事業は、地域の方が主体で進めているまちづくりというところで、区としては、その動向を注視しながら支援をしています。小山三丁目第１地区につきましては、現在まだそのような補助金を支給するような状況になっていないと聞いていますので…","id":"exchange-090"},{"speaker":"こしば委員","kind":"質問","question":"私からは、３６７ページ、自衛官等募集事務費について、３４７ページ、ドッグラン設置検証についてお伺いいたします。今日は、土木費の中で、法定受託事務の自衛官募集事務についてお伺いいたします。","respondent":"伊藤災害対策担当課長","answer":"五反田にあります自衛官の募集案内所と連携をしてございまして、募集パンフレット等を受領しています。一方、なかなか恒常的にパンフレットを置く場所がないので、今、なるべく庁舎内に置けるように調整をしているような状況です。","id":"exchange-091"},{"speaker":"こしば委員","kind":"質問","question":"庁舎の中でも広報のものとなるパンフレットを置かれているとお伺いいたしました。そういったものも通しまして、近年の区内在住者の自衛隊への入隊状況について、その推移について説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"区内の自衛官の合格者、入隊者という内容ですが、遡りまして、令和３年につきましては１７名、令和４年につきましては１５名、今年が、今のところ５名と聞いておりますが、この人数については、また入隊、入校時に変わってくると読んです。","id":"exchange-092"},{"speaker":"こしば委員","kind":"質問","question":"例えば、自衛官の募集時期に合わせて、その前に宣伝をすることも法定受託事務に入るのではないでしょうか。先ほど、区の施設や町会・自治会の掲示板も含めて、こういった案内を張り出していくということを検討してみてはいかがか尋ねました。","respondent":"伊藤災害対策担当課長","answer":"先ほど漏れてございましたが、例えば、広報しながわで、来年度は年に５回、本年度につきましては３回の募集広報をさせていただいたような状況です。募集のタイミングで何かしらの打ち出しのようなものができればと考えてございまして、現在考えているものとしまして…","id":"exchange-093","title":"町会・自治会支援"},{"speaker":"こしば委員","kind":"質問","question":"先日、五反田にあります自衛隊の募集案内所に伺いまして、所長といろいろと意見交換等をさせていただきました。その法的な根拠をぜひお示しほしいと求めましたが、お考えを教えていただけばと思います。","respondent":"伊藤災害対策担当課長","answer":"ですので、今のやり方がよろしいのではないかというふうに考えております。一方で、ホームページに品川区の名簿の提供の方法について記載することについては、関係課と共有しまして、今後検討していきたいと考えております。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、３３２ページの河川費について、そして３６０ページ以降の防災費についてお伺いしてまいります。新庁舎建設に向けて、今、様々取り組まれていますが、新庁舎は、いわゆる品川区の防災拠点としての認識でよろしいのか尋ねました。","respondent":"平原防災課長","answer":"防災拠点という認識でおります。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"提案","question":"先日、シェルターについて質問をさせていただき、緊急一時避難施設としてシェルター的な役割をするのが９９か所あるというご答弁をいただきました。今回は少し踏み込んで提案をしますが、核シェルターについて、区として整備の考えがあるのか、今後について説明を求めました。","respondent":"伊藤災害対策担当課長","answer":"区内には核シェルターはないということで答弁をさせていただいたと記憶しています。今後もやはり地下シェルターの在り方については、併せて検討させていただきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。そこで、品川区として、水質改善は、これ、ずっとやられていますが、今後どうしていくのか尋ねました。","respondent":"北原河川下水道課長","answer":"目黒区が、さらに上流で水質浄化施設をつくって来年度から稼働するということで、そういったものも含めて複合的に対応していく必要があると思います。区としても取り組んでいって、また…","id":"exchange-097"},{"speaker":"石田（し）委員","kind":"意見","question":"どうしてもそこにある壁は、やはり東京都が大きな壁になって、なかなか品川区が単独で何ができるかということは難しいのかなと思います。これまでどのような取組を都議会でされてきたのか、また、その経験をどうやって品川区に持ってくるのかお知らせくださいとの意見を述べました。","respondent":"北原河川下水道課長","answer":"東京都に対しては、区としてもきちんと要望していくことが大事だと思いますし、区長とも、我々としても、現状を報告しながら、きちんと区として何ができるのかということは取り組んでいきたいと考えています。","id":"exchange-098"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"東京都とも、どんどん東京都に発信していただいて連携していただいて、その実現に向けて取り組んでいただきたいという思いで質問をしました。改めて何か考えがあれば、説明を求めました。","respondent":"北原河川下水道課長","answer":"現状について、まず区民の皆さんにもきちんともっと発信していかなければいけないと思いますし、私も東京都から来ている身でもありますので、知っている情報もありますので、きちんと実現できるように真摯に取り組んでいきたいと考えております。","id":"exchange-099"},{"speaker":"木村委員","kind":"質問・要望","question":"ページ数が３２５ページ、上から４行目、交通安全啓発事業の中から、交通安全運動についてお聞きいたします。車、バイク、自転車、歩行者と、それぞれの立場で運転ルールを守り、事故に遭わないように、起こさないことが求められています。","respondent":"工藤交通安全担当課長","answer":"区民に向けた言葉ということで、交通事故防止の観点から言いますと、やはり交通事故ゼロを目指すという力強い言葉を区民に向けて訴えかけていきたいと考えています。","id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"交通安全運動は、交通事故を防止する運動だと認識していますが、その効果のほどはいかがでしょうか。説明を求めました。","respondent":"工藤交通安全担当課長","answer":"春秋の年２回、全国一斉にやっている運動でもあります。品川区は前年比マイナス０.３ポイントということで、こういった交通安全運動の機会を捉えながら、引き続き取組を進めてまいりたいと考えています。","id":"exchange-101"},{"speaker":"木村委員","kind":"意見","question":"若干そういう意味では件数が減っているということでありますけれども、それはどういうことが作用しているのか。何かお気づきの点があれば説明を求めました。","respondent":"工藤交通安全担当課長","answer":"品川区では、自転車が関与する交通事故が多いということで、令和４年度から自転車安全利用指導員という制度を実施しています。こういった活動が功を奏して、自転車の関与率の抑制が図れているというふうに思ってあります。","id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"ことわざで、ほとんどの方々に当てはまることでしょうけれども、私自身も気をつけていきたいと思っています。全ての人々で完璧にルールや規則を守っている人々は、どれぐらい存在しているのでしょうか、これも分かれば説明を求めました。","respondent":"工藤交通安全担当課長","answer":"ルールを理解している方ですけれども、なかなか難しい質問だと思います。そこら辺は何とも答えられませんが、引き続き、交通ルールの周知についてはやってまいりたいと考えています。","id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"次に、交通安全教室でありますけれども、お伺いいたします。交通安全の機運を高めるには、区民の方々の協力なくして成り立たないと思いますが、どのような連携の形があるのかお聞きしたいと考えています。","respondent":"工藤交通安全担当課長","answer":"交通安全運動時の地域との連携ということでお答えさせていただきたいと思います。様々な形で町会の方々、皆様にご協力をいただいているという状況です。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"３５３ページ、３６１ページ、そして３５７ページの住宅改善工事助成について伺っていきたいと思います。これについて、何が効率性を妨げているのか、お聞かせほしいと求めました。","respondent":"長尾建築課長","answer":"一人の方が持っている私道はなかなか少ない状況があります。そういったところが、効率性といいますか、申請に至るまでの期間が長くなっている原因の１つになっていると考えております。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"道幅２.５ｍ以上が全額助成、それ未満で１.２ｍ以上が９０％助成ですか、されないというところの難しさが一方であると思うのです。もちろん要望に応じて全て対応するということになると、これは際限ないことにもなりますので、あくまで私道という前提があるので。","respondent":"長尾建築課長","answer":"老朽化が進んでいる状況があれば、そちらは気になられている部分的な補修も含めて、助成制度を使っていただいて整備しているところです。１回整備して、やはり劣化が進んでいるようでしたら、改めて制度を使ってきれいにするというところも実際に対応しております。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問","question":"そこはでも、やはり行政の１つの腕の見せどころではないですけれども、より一層拡充していくという部分があるのではないかなとも思っています。その点については、いかがお考えか尋ねました。","respondent":"長尾建築課長","answer":"２.５ｍ以上であれば自己負担なしというところで対応できているところが多いのかなとは感じておりますが、駅周辺なのだけれども１.２ｍを切っていてというようなところがございましたら、対応できるところをしっかりと確認していきたいと考えております。","id":"exchange-107"},{"speaker":"塚本委員","kind":"質問・要望","question":"様々、拡充についての適用条件といいますか、そういうことについての検討をお願いしたいと思います。これについて、なぜこの違いがあるのかということについてお聞かせほしいと求めました。","respondent":"羽鳥防災体制整備担当課長","answer":"現場の状況に応じて適切な操法を選択できると認識していますが、またスタンドパイプ、いずれも二重巻きということで配備しています。上位団体の消防団、やはりふだんからやられている活動の延長に災害時の対応があることが望ましいのかなというふうに考えてあります。","id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"今ご答弁いただいた中で、そこの疑問を持たれている消火隊の方々、キャスターつきのバッグに折り島田で入れて運ぶということを独自でやられています。こういったことについての評価というか、区としての考え方、最後にこの質問の答弁をお願いしたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"折り島田を導入したいということで、必要なキャリーケースも導入されるということは、それぞれのご判断になるのかなです。そういったときには、防災資機材整備助成金をご用意しておりますので、そういったものをご活用いただければというふうに考えてあります。","id":"exchange-109"},{"speaker":"塚本委員","kind":"意見","question":"この中で、いろいろな対象工事がありますけれども、その他耐震化を高める工事という項目もあります。もう１つ、このその他耐震化を高める工事の拡充というところについての周知です、その強化ということについて説明を求めました。","respondent":"竹田住宅課長","answer":"住宅まつりでのチラシの配布や相談コーナーの設置、それから、毎月第３水曜日に庁舎で開催しております住宅相談会などで周知を行ってきたところです。チラシも作成していきたいと考えております。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"３４９ページ、３６７ページ、帰宅困難者対策についてお伺いします。まちづくり協議会もしっかりとした形でできておりますので、ぜひそういった視点での取組をお願いしたいと思いますが、そのことについてお伺いします。","respondent":"大石まちづくり立体化担当課長、森道路課長、羽鳥防災体制整備担当課長","answer":"補助２９号線沿道につきましては、今、東京都が主体となりまして、沿道まちづくりを区も一緒に連携して進めているところです。… Ｂ／Ｃとして、費用対効果も当然検討しておりまして、１を優に超えることは確認をしています。これから進めていく中で… 委員おっしゃるとおり、東京都としっかり連携して事業は進めているところです。都と連携して、区もしっかり対応を進めてまいりたいというふうに考えており…","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれありがとうございました。それぞれが住民本位の視点で取組事業を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"西村委員","kind":"質問","question":"３５１ページから３５３ページ、３４１ページ、密集住宅市街地整備促進事業について伺いたいと思います。気温低減効果等を活用したみどりのインフラとして緑地整備を実施している取組には、どのようなものがあるのか伺います。","respondent":"高梨公園課長","answer":"道路区域も現在検討していますけれども、取組を進めてまいりたいというふうに考えてあります。そことうまく連携させて、従前より取り組んできた内容も含めて、グリーンインフラとして打ち出しをさせていただいたところです。","id":"exchange-113"},{"speaker":"西村委員","kind":"質問・要望","question":"防災や都市環境の改善、美しい景観ですとか安らぎといった多面的な効果が期待されると考えています。ぜひとも可視化してほしいと求めましたし、そのような事例があったのであれば、お聞かせほしいと求めました。","respondent":"高梨公園課長","answer":"こういった緑化やそういったところを進めることで、インフラ整備の効率化、予算の効率化というところもうたわれているところです。今回、そういったところをしっかりと醸成させていくような取組ということで進めてまいりたいというふうに考えてあります。","id":"exchange-114"},{"speaker":"西村委員","kind":"質問","question":"品川区管轄で１５か所、ＵＲと連携しているところで３０か所と伺っております。様々な活用はできないか、ご検討いただけないかと考えていますが、お伺いいたします。","respondent":"小川木密整備推進課長","answer":"特に二葉、豊町を中心に、事業用地の確保に努めているところです。そういった別の用途につきましては、またこれからいろいろと研究して、また東京都とも確認を行いながら進めてまいりたいと思います。","id":"exchange-115"},{"speaker":"西村委員","kind":"質問・要望","question":"２０２１年東京オリンピック・パラリンピックの際に、これを機に社会が変わったと言える社会にしたいと要望させていただきました。音響信号機や点字ブロックの優先順位、社会生活のインフラとしての考え方について、区のお考えをお聞かせほしいと求めました。","respondent":"森道路課長","answer":"それを１日でも、半日でも早く対応していけるように、職員と事業者と一緒に頑張っているところです。これからも引き続き努めてまいりたいと考えています。","id":"exchange-116"},{"speaker":"西村委員","kind":"意見","question":"点字ブロックを含めて、陳情がとても多い要件でして、それだけの本数のお声が届いているということを改めて驚いています。素早いご対応に感謝申し上げますが、引き続き、お願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"３日間を乗り越えるには、地域として何をやったらいいですかということを、自助と共助です。こういうことをやってほしいというのは、発生時のところにポイントを当ててやってほしいと思うのですが、そこら辺の見解をお願いします。","respondent":"平原防災課長","answer":"委員ご指摘のとおり、大きな災害になればなるほど公助が届かないということは、これまでの災害でも教訓として示されてきているところです。令和６年度の新規事業という形で訓練を幅広くやっていく、様々…","id":"exchange-118"},{"speaker":"石田（秀）委員","kind":"質問","question":"答弁は多分無理だと思うので、これは一般質問でもやりましたけれども、大井火力発電所、私も１９万m2、海からですけれども一周して見てきました。必ず地域の自治体と話をしますという話をしているわけですから、総合レジャーランドでもいいですから、お願いだけをしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-119"},{"speaker":"松永委員","kind":"質問","question":"そして３３９ページの羽田空港アクセス線新駅可能性地域まちづくり検討経費、続きまして、３４７ページのドッグラン設置検証について伺います。初めに、３２５ページの地域公共交通機能の充実整備について伺います。","respondent":"鈴木都市計画課長","answer":"実証実験に向けて検討を進める、１２人乗り、カート式をレンタルという形で行っていくというような予定です。この新たな交通手段の特性も踏まえながら、合理的根拠をしっかり区民の方に示しながら、検討を進めていきたいというような予定です。","id":"exchange-120"},{"speaker":"松永委員","kind":"質問・要望","question":"どういった形で決めていかれるのかということと、検討課題の中に入れていただきたいと思うのですが、そうしたアンケート調査はとられるのか尋ねました。","respondent":"鈴木都市計画課長","answer":"課題等を抽出しながら、次年度以降の導入に向けて、しっかり検討していきたいです。区内全域のビッグデータに基づいて検討していきますので、裏を返せば、区民の移動の要望というところをしっかり検証しながら検討を進めていきたいと。","id":"exchange-121"},{"speaker":"松永委員","kind":"意見","question":"実は、南大井から大井町へのバスがまた減便されました。そこの途中で下ろされるとか、そういったこともあるかと思うのですけれども、そうした場合は可能なのかどうかをお知らせくださいとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"例えば、大井町から臨海斎場までの代替手段としてなじむかというのは、少しどうかなです。","id":"exchange-122"},{"speaker":"松永委員","kind":"質問","question":"次に、３２５ページの鉄道駅可動式ホーム柵整備助成について伺います。移動柵について、例えば関西のようにロープ式になるのか、少しその実態をお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"よりホーム上の安全対策が図れたタイプに整備をされるというところで、進めていただいているところです。それに対応できるように、２つのタイプが入ってきた場合は、そういった安全性にも配慮されたホームドアが整備されるという予定です。","id":"exchange-123"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、３３９ページの羽田空港アクセス線の新駅についてですが、現在どこまでお話し合いがされているのでしょうか。新駅をつくるのかどうかということについて、挙げていないのか、お知らせほしいと求めました。","respondent":"鈴木都市計画課長","answer":"１点、しっかり検討していくですので、検討を進めているものではございません。さらに、まちづくりの方向性的なところをしっかり検討していくための準備を進めながら、関係機関としっかり協議をしていきたいです。","id":"exchange-124"},{"speaker":"松永委員","kind":"質問","question":"２０３１年に開業する予定となっており、その前に手を挙げないと駅がつくれないのではないかという心配で質問させていただきました。ぜひそのことについても伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"令和４年度、補正で予算もつけていただいて検討を進めてきていると。当然ながら、適時適切に議会等にもしっかりご説明、ご報告しながら進めていきたいというふうに考えてあります。","id":"exchange-125"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、我が会派からの要望もありました３４７ページのドッグランの設置検証について伺いたいと思います。例えば、広さ、柵の高さ、また大型犬も可能なのか、利用時間、あとは会員制としてやられるのかなど、そのところについて伺いたいと思います。","respondent":"高梨公園課長","answer":"年間で１６回ほどマナー講習会を実施する予定ですが、その講習会の際に仮設ドッグランを設置し、利用者であったり。戸越公園の３公園で実施をしたところなのですが、一定、犬が走り回れる広さは確保して設置をしています。","id":"exchange-126"},{"speaker":"松永委員","kind":"質問","question":"ぜひ今後もよろしくお願いします。今後、公園内にある喫煙スペースについて、どのような感じで進められていくのか尋ねました。","respondent":"高梨公園課長","answer":"公園内の喫煙所については、コロナ禍以降、閉鎖をしています。開放については考えるですので、キャンプ場についても、これから利用者や周辺の方々にご意見を伺って決めてまいりたいというふうに考えてあります。","id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"耐震を図りたいというご要望が結構あって、いろいろ考えられてはどうかなというふうに思いますので、ご意見をお聞きします。協力できるものは協力していくという形で、広域的な開発もそろそろ考えるべきではないかと思いますが、いかがか尋ねました。","respondent":"高梨公園課長、長尾建築課長、羽鳥防災体制整備担当課長、平原防災課長、大石まちづくり立体化担当課長","answer":"品川区でも、気がついたところを投稿できる道路公園の通報システム「My City Report」という取組を行ってあります。今… 委員お話しいただいたベッド型のシェルターにつきましては、品川区のほうでも一時期助成はしていたのですけれども、現在は助成しておりません。… 来年度以降、感震ブレーカーに関しましては、対象エリアを全域に広げて、また、補助率、補助額も見直しをしていこうというふうに考えています。… 創設以降１５億円ということで予算要求させていただいているところですけれども…","id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"そして、いろいろな事業が出てくると思いますので、それに対応できるように積み上げをしていただきたいと要望しておきたいと思います。そして品川区としてどうするのだということをしっかり考えていただきながら、開発に関わっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-129"},{"speaker":"若林委員","kind":"確認","question":"３６０ページ、第１回定例会の本会議で、区のほうでは導入の検討を確認させていただきました。区民が利用できるようにしなくてはいけないと思いますけれども、区の取組をお聞きします。","respondent":"北原河川下水道課長、平原防災課長","answer":"平成２９年度より、目黒区界から谷山橋間の最上流部で実施予定であったところ、最下流部の荏川橋から河口区間までにおいて実施したものです。来年度予算がない理由ですが、令和７年度以降に… なかなか地図情報を視覚障害者の方にお示しすることが難しい中で、非常に分かりやすいような内容であるというふうに考えているところです。内部で検討していますけれども、私ども初めてということもありますので…","id":"exchange-130"},{"speaker":"若林委員","kind":"質問・要望","question":"お尋ねですけれども、令和５年度の予算を組むに当たって、都が同じ区間を工事をするということが分かったということなのでしょうか。工事の形態が違うので、区は実施できると理解するのですけれども、この３点についてお答えをほしいと求めました。","respondent":"北原河川下水道課長","answer":"品川区の工事側としても、不調のリスクもありますので、こういった形で実施したものになります。都が不調になったのが区の工事が契約した後でございまして、その後に対応することが難しかったという状況があります。","id":"exchange-131"},{"speaker":"若林委員","kind":"質問・要望","question":"これは明確にそういうことだと思います、予算を両方組んでいるわけですから。それは都のほうの話ですから関係ありませんけれども、今年度、令和７年度という話ではないか尋ねました。","respondent":"北原河川下水道課長","answer":"目黒川の水質改善については、委員もおっしゃいますように、東京都、目黒区等と連携して検討会を行うなど密に実施してきているところであります。目黒川で工事がたくさんあるということで、そういったところを活用して…","id":"exchange-132"},{"speaker":"せりざわ委員","kind":"提案","question":"さらにというところで提案になりますが、駐車場の車椅子マークについてご提案したいと思います。赤ちゃんの、もしくは子育て世帯の防災グッズの支援も１つ載せていただいてもいいのかなと思うので、ご見解をお聞かせほしいと求めました。","respondent":"高梨公園課長、平原防災課長","answer":"駐車場における車椅子マークについてですが、公園の中には、公園駐車場として時間貸し駐車場等を運用しているところがあります。今、そういった誤解を生むことがないような広報であったりとかというところについて検討してまいりたいと… 令和６年度以降、様々な場でそれを強化していこうというふうに考えている中で、様々な事例を研究してまいりたいと考えています。それに特化したようなものはないのですけれども、そういったものの位置づけ等も含めまして…","id":"exchange-133"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"ご見解をお聞かせください。例えば指差しとか、いろいろできるようになっていますけれども、この代読・代筆の支援の品川区の体制について説明を求めました。","respondent":"平原防災課長","answer":"しながわ防災学校での取組などもありますので、防災グッズの在り方について、所管と連携しつつ検討してまいりたいと考えています。特に支援の段階になって必要になってくるものですので、今、そういった中で位置づけてまいりたいというふうに考えてあります。","id":"exchange-134"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"区の道路、例えば区役所通りとか、いろいろ愛称があると思います。道路のほうからお伺いしたいのですが、愛称道路のルール、どういうふうにつくっていくのかをお聞かせほしいと求めました。","respondent":"森道路課長","answer":"道路の愛称につきましては、一部、ホームページ等でも公開をしていますけれども、地域の方が、日頃から、今まで、昔から呼んでいるものを、道路に親しみを持っていただくということで、区としても愛称として設定しています。","id":"exchange-135"},{"speaker":"せりざわ委員","kind":"提案","question":"私の提案としては、目黒川の名前、品川区内に入ったときの目黒川の名称を品川に変えませんかというような提案です。愛称として変えていくということを１つ見解として、我がまちとしてぜひつくっていただきたいと思うのですが、ご見解を説明を求めました。","respondent":"北原河川下水道課長","answer":"河川の愛称は全国的には多数あると聞いていますので、まずはそちらを研究してまいりたいと思います。","id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"こちらも大きな２つのポイントを伴った公園ですので、これは大変期待していますということで、今後、よろしくお願いしますという要望だけです。その原因は地域の方々にご説明いただいたと伺っていますが、今後のというか、現在の浸水防止の区としての対応をお尋ねします。","respondent":"高梨公園課長","answer":"区民公園の、昨年６月の大雨の際の溢水についてですが、町会や区政協の場等々、地域の方々には原因についてご説明をさせていただいたところです。区民公園から外の宅地のほうに水が出ないような対策工事を、現在、この３月末完成の予定で進めているところです。","id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"手すりについては、ぜひ東京都の交渉の中で要望をお願いいたします。この違いについてご説明ください。","respondent":"中道都市開発課長","answer":"補助金につきましては、組合が設立して事業認可が下りたものに対して補助金が入るということになっております。","id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということですと、８事業は、都市計画決定したり事業認可が下りていて、それで都市計画交付金が充当されているという理解でよろしいでしょうか。ということは、充当されていない様々なこちらに幾つか出ている事業も、いずれその対象となっていくというふうに考えてよろしいか尋ねました。","respondent":"中道都市開発課長","answer":"市街地再開発事業につきましては、事業が認可した際に都市計画交付金等々、そういったものを活用して進めていくというものになります。","id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望なのですけれども、その４０万円が、正確に表示してほしいと求めました。特別区の実態に合わせた都市計画税の配分についても、東京都に強く見直しを求めています。","respondent":"遠藤財政課長","answer":"７％に対して３０％というところで、この間ずっと説明をといいますか、抗議をしています。その辺と、そういう部分につきまして、分かりやすいような形でホームページ等で周知を図っていければと思っているところです。","id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"事業が３対７ですが、実際の交付金は７％に過ぎないというところで、そういう形だったと思います。分かりやすい形で、区長の見解をホームページにアップしていただきたいのですが、もう一度その点を確認します。","respondent":"遠藤財政課長","answer":"不合理な税制の部分とかは載せている部分はあるのですが、すみません、都市計画金を載せていたかどうか確認できておりません。載っていない場合には、速やかにこちらのほうも丁寧に説明していきたいというふうに考えております。","id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"歳入のときに、この都市計画税についても、しっかりと特別区長会の中で特別区協議会が一体となって東京都に主張してほしいと求めました。その辺のご決意を伺いたいと思います。","respondent":"遠藤財政課長","answer":"いわゆる財調協議の中でこの都市計画金についても必ず説明といいますか、都市計画金は別の話だという形でかわされているようなところがあります。今後、特別区長会を通じまして、こちらは粘り強く交渉していきたいと考えているところです。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、粘り強く交渉していただけるということですので、ぜひ３対７のその分に近づけるように、区長会一丸となって東京都と交渉してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"私からは、３４９ページ、Ｐａｒｋ－ＰＦＩの導入、３５９ページ、住宅運営費について伺います。これはどういった内容なのか、最初に伺いたいと思います。","respondent":"高梨公園課長","answer":"事業者を決定したいというふうに考えてありますが、収益施設と一緒に区が整備するべきものも考えられるということで、その区が整備する部分の設計委託費を計上するものです。","id":"exchange-144"},{"speaker":"松本委員","kind":"質問","question":"制度のほう、これからの品川区のＰａｒｋ－ＰＦＩの在り方のお話で伺いたいのですけれども、４月以降に計画が発表と伺っています。そうすると、計画策定後は、原則的にＰＰＰ／ＰＦＩ手法を優先的に検討するというふうなことになるかというところをお伺いいたします。","respondent":"高梨公園課長","answer":"内閣府から出ていますＰＰＰ／ＰＦＩ手法導入優先的検討規程策定の手引き等でもご案内がありますけれども、１０億円以上の整備の際には検討を要するということで、１０億円以上の整備の際にはこの検討をしないと国費の要件に当たらないというような状況になってあります。","id":"exchange-145"},{"speaker":"松本委員","kind":"確認","question":"策定を目指されている規程の内容を確認すると、この優先的検討の中でＰａｒｋ－ＰＦＩが検討対象から外れてしまうのではないかというふうな不安があるのですけれども、ここはどうか尋ねました。","respondent":"高梨公園課長","answer":"ここの検討するべきＰＦＩ手法でいうところのＰＦＩというのは、もともとありました設置管理制度を公募型にして行うということで、今回この公共施設の総合計画の中では区分けをして考えているというふうに理解しています。","id":"exchange-146"},{"speaker":"松本委員","kind":"質問・要望","question":"ここは答弁を求めないので、平成２８年につくられているので、そもそもＰａｒｋ－ＰＦＩの制度が始まる前につくられたものではないかと思います。こちらで遺品の引き取り手がいないというふうな状況があるのか、あるとしたら、どの程度あるのか伺いたいと思います。","respondent":"竹田住宅課長","answer":"孤独死を独り暮らしの方がご自宅で亡くなったケースと定義した場合、令和５年度、令和４年度においては、２件程度です。ご存命中の対応記録や入居書類、あるいは戸籍調査等を行いまして、相続人が見つからなかったというケースはございません。","id":"exchange-147"},{"speaker":"松本委員","kind":"質問・要望","question":"相続財産管理人を申し立てるということなので、ここは費用が１００万円ぐらい、予納金も含めてかかるというふうなことがあります。当区で、今後こういうふうな方向性があるのか、要望も含めてお願いしたいと思います。","respondent":"竹田住宅課長","answer":"極力相続人の方を見つける方向で進めていきますが、万が一見つからなかった場合は、裁判所による相続財産管理制度の法的手段を検討してまいります。","id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"３２５ページ、交通安全について、まずお伺いします。課長は、この品川区に、どのような思いやりの心を残していってくれるのか尋ねました。","respondent":"工藤交通安全担当課長","answer":"それぞれ対応した１つ１つが交通安全に寄与したものであったと期待をしています。次のところでも生かして頑張ってまいりたいと、精進してまいりたいと考えています。","id":"exchange-149"},{"speaker":"藤原委員","kind":"質問・要望","question":"西大井駅、今年の８月、ニコン本社が稼働すると思うのですけれども、西口の改札口、何回も要望していますが、これはどうなっているでしょうか。西大井のことを伺ったのですけれども、そうですよねという確認だけでいい。","respondent":"平原防災課長、櫻木土木管理課長、北原河川下水道課長、鈴木都市計画課長、工藤交通安全担当課長、小川木密整備推進課長、中道都市開発課長、大石まちづくり立体化担当課長、高梨公園課長、長尾建築課長、竹田住宅課長、森道路課長、佐藤企画課長、崎村人事課長","answer":"東京都では、令和５年１２月に大規模噴火降灰対応指針を取りまとめました。この対応指針で示されました対策など、都が具体化する対応策を踏まえまし… 西大井周辺につきましては、おおむね近隣に５か所程度シェアサイクルポートがありますが、駅前にはない状況です。… 現在、下流部のシールド工事については、２月１４日にシールドが到達いたしまして、事業を進めているところです。… 十分改札は対応しているですが、プラス３,０００人膨らむというところもありますので、しっかり働きかけていきたいです。…","id":"exchange-150"},{"speaker":"藤原委員","kind":"質問","question":"私がこういうふうに何回も西大井のことを思って質問してはいけませんか。その辺、答弁してください。","respondent":"鈴木都市計画課長","answer":"それから東京方面、非常に好立地、ポテンシャルが高い駅周辺です。非常にありがたい、重要なことだと思いますので、引き続きしっかり検討に取り組んでいきたいです。","id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問","question":"３日から１週間は、１か月後に、ほぼ全域で上下水道が使えるようになるのは１か月後ということで考えておいたほうがいいのか伺いたいと思います。これはどういう数字なのか、９０数％は下水道が使えてトイレが使えるという、この６.４％の意味についても説明を求めました。","respondent":"平原防災課長","answer":"破断したときの影響も変わってまいりますので、先ほどお話のございました被害想定の考え方ですが、逆算していただければといったところもあります。２万６,０００人が影響を受ける、そういうようなことになってまいりますので…","id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところでは、区のほうからもこれは求めていただきたいというふうに思っているのですけれども、いかがでしょうか。私は、区としてもそれを求めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"北原河川下水道課長","answer":"耐震継手化がなされていけば耐震性能を持つものと考えられますが、非常に数も多いということで、計画的に順次進めていると認識しております。水道局の公費を入れるかどうかというところですが、水道事業は独立採算制ということで…","id":"exchange-153"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に被害の地域の大変な事態をずっと私たち目にしているわけですから、私は、区のほうからも求めていただきたい。そうすると、ぜひ上水道の耐震化というところでは、区のほうからも求めていただきたいということを強く要望しておきたいと思います。","respondent":"北原河川下水道課長、羽鳥防災体制整備担当課長","answer":"下水道の耐震化につきましては、避難所や災害復旧拠点等を対象に、順次、進めてきておりました。技術的には耐震化が図れるものと認識しておりますが、非常に量が多いということで、重点化して進めているものというふうに認識しています。 トイレの備蓄につきましてですけれど、トイレにつきましては、様々な形のトイレを備蓄するという対応をとっているところです。簡易トイレ、仮設トイレ…","id":"exchange-154"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１回説明したものと全く違う状況になっているわけですから、区のほうからも要望していただきたいと思うのですけれども、その点を伺いたいと思います。それから今、大工事がされていますけれども、そこの教訓をしっかりとやはり生かしてほしいということも求めてほしいと求めました。","respondent":"羽鳥防災体制整備担当課長、大石まちづくり立体化担当課長","answer":"トイレの備蓄につきましては、区民全体ということではなくて、避難所避難者用です。携帯トイレに関しましては、３日間分の量を備蓄しています。 説明会を求めることにつきましては、調査掘進終了後にＪＲ東海は説明する機会を設けると聞いておりますので、そちらで説明されると聞いております。教訓を生かすということですが、教訓を生かして作業を進めていると感じております。","id":"exchange-155"},{"speaker":"大倉委員","kind":"質問・要望","question":"１回１００枚程度と書いてあるのですが、費用と併せて教えていただきたいのと、最近の傾向を教えてほしいと求めました。３４７ページ、西五反田公園について伺えればと思うのですが、残したことについて教えてほしいと求めました。","respondent":"櫻木土木管理課長、高梨公園課長、森道路課長","answer":"大体５万６,０００枚程度、特に不動産の広告等が非常に設置されることが多いものですから、その辺りを重点地区として回っているところです。現在… 安全性が担保された同様な遊具に変えるということで、現在、進めているところです。新しくインクルーシブ遊具として目玉焼き遊具を設置するところの横にパ… 令和５年度の３期区間ということで、残念なのですけれども、伐採をさせていただいたところです。非常に愛着のあるところだと思いますので…","id":"exchange-156"},{"speaker":"大倉委員","kind":"質問","question":"少し有償でもいいので、何か一緒にやりませんかというところができないかなということを今少し思っているので、その点について伺いたいと思います。夏場はすごく暑くなるというところで、そういったところへの屋根の設置も対策としてはいいのではないかと思うので、お願いします。","respondent":"櫻木土木管理課長、高梨公園課長","answer":"どのような形で広めていったらいいかということで、有償の面も含めて、何かインセンティブがあったほうがいいのではないかというお尋ねかと思います。草の根的に広がるようなことがあるといいのかなと考えていますので… 熱中症対策による屋根の設置ですが、安全領域の関係上、全てにつけることができません。今、新しい製品等も出てまいりますので、ミストの設置等も含めて複合的に考えてまいりたいと考えているところです。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問","question":"能登半島地震におきましては、石川県内だけで７万棟を超える住宅の被害が発生しているとのことです。能登半島地震の被災地へ区職員を派遣されたと伺っておりますが、どのような職務に従事をされたのか、説明を求めました。","respondent":"平原防災課長","answer":"１名は本日出発です。内容の説明、その次の手続の説明等々を伴いますので、そういういわゆる窓口業務といったところが主になります。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひ地域への貢献をしたいとの意向を伺っておりまして、支部内でしっかり準備体制をとっておきたいという要望を、そういったご要望を伺いました。協議を詰めてほしいと求めましたが、いかがか尋ねました。","respondent":"平原防災課長","answer":"罹災証明が出ましたとき、それは支援のために出すということになりますので、様々な申請書類が必要となる場合があります。それともう１つは、漏れのない支援を行っていくために、そういったところ等で行政書士会の皆様にご活躍いただきたい場面が多々あると思います。","id":"exchange-159"},{"speaker":"あくつ委員","kind":"提案","question":"定例会の一般質問で、現在居住支援を行っている社会福祉協議会への助成などを提案されており、私もそれは非常に有効かなと思いました。この法改正によって、人感センサーなどで安否確認できるようにし…","respondent":"竹田住宅課長","answer":"ちなみに、本年度、そこはやはり都の居住支援法人であります６５歳以上の方を専門に不動産をご案内する方のご講演をいただきました。居住支援法人も活用しながら、高齢者を入れることの様々なメリットもご紹介しながら、高齢者の居住支援に努めてまいりたいと考えております。","id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も直接お話を伺ったことがありますが、住宅要配慮者を対象とした社会共有資源として空き家を活用するビジネスモデルを実践されている。安否確認や見守り、適切な社会サービスへのつなぎを行う住宅のことを指しまして、この供給を行う制度が新しく創設されます。","respondent":"竹田住宅課長","answer":"１棟丸ごと借り上げて、サブリースした居住支援法人の意向で入居できるできないを判断できるという、非常にメリットのある制度だと思います。そういったものを実現させていきたいと思いますので、居住支援法人と連携をとりながら、高齢者の支援を進めていきたいと考えております。","id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"高齢者の住まいに関する総合的、包括的な支援を、パッケージとして区民へ発信していただきたい。質問させていただきましたけれども、ぜひそういったメッセージを掲げてほしいと求めましたが、最後にご答弁をお願いいたします。","respondent":"竹田住宅課長","answer":"これは正に委員おっしゃるとおり、高齢者、障害者、ひとり親、それから低所得者を対象とした事業です。こういった事業を通じて、住宅確保要配慮者という方々の支援をして、どなたにも住みやすい品川区をつくってまいりたいと考えております。","id":"exchange-162"},{"speaker":"高橋（伸）委員","kind":"質問","question":"最初に、３３１ページの無電柱化推進事業についてお伺いします。昨年６月に改定された品川区無電柱化推進計画において、特に重要で整備効果の高い６路線のうち、その理由を説明を求めました。","respondent":"森道路課長","answer":"先ほどご紹介いただきました無電柱化推進計画の中で６路線ありますけれども、もう１つ、まだ事業化まで進めていないところです。しっかりと連携しながら進めて、現在のところは、今行っております２路線をしっかりと進めていきたいというふうに考えています。","id":"exchange-163"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"東口通り商店街の商店街長、町会長からも、今、課長のご答弁のとおり、話を伺っております。私の発言のとおりでいいのかどうか、ほかに何かあれば、教えてほしいと求めました。","respondent":"森道路課長","answer":"基本的には、委員ご紹介いただいた懸念材料が大きいかなというふうに思います。それにしても、商店街の方々に大分ご迷惑をかけるところもありますので、慎重に協力を得ながら考えていきたいと思ってあります。","id":"exchange-164","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後の事業化に向けて、スケジュールは、これからどのようにお考えになって、完成の見込みは、まだ当然分からないと思うのですけれども、もし私が聞き取りをされたとき、見込みとして、どういうふうに区としてお考えになっているのか、教えてほしいと求めました。","respondent":"森道路課長","answer":"今行っております２路線に加えまして、拡幅が行われています林試の森公園につきましても、来年度から検討を進めるところです。はそれを進めさせていただいて、地域の方、どういった中で事業が進められるかということを研究してまいりたいと考えております。","id":"exchange-165"},{"speaker":"高橋（伸）委員","kind":"質問","question":"あそこは昔からハーモニカ通りといって、本当に長い一軒長屋が、恐らく今、４７戸とか４８戸ぐらいあると思います。権利者も７０名ぐらいいると思うのですが、判断できないと思うのですけれども、この事業完成までのスケジュール感を説明を求めました。","respondent":"小川木密整備推進課長","answer":"老朽木造住宅で、一部はもう損傷しているようなところも見受けられますので、事業のスピードが非常に求められているところです。来年度は、意向調査等を行いながら事業計画をしっかりと立案して、来年度末ぐらいには、事業の方針等を示していきたいというふうに考えてあります。","id":"exchange-166"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次は、３４７ページ、公園・児童遊園整備費について、これは立会川の児童遊園と旗の台北公園についてお尋ねをします。どうなったか確認をしたいのですけれども、恐らく３体目だと認識しているのですけれども、どうなったのか確認させてほしいと求めました。","respondent":"高梨公園課長","answer":"カエル公園のカエルの彫像につきましてですが、結論から申しますと、今あるカエルの彫像を生かして再生できたらと考えています。施設自体は新しくということで、現在、設計を進めているところです。","id":"exchange-167"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうしても根上がりがあると思うのだけれども、これが設計での調査の結果、どのようなものであったかということを教えてほしいと求めました。それで、その結果を踏まえて、どのような改修が行われるのかお伺いしたいと思います。","respondent":"高梨公園課長","answer":"その関係もございまして、大きく植栽帯の位置を変えると、樹木も動かさなければいけない。現状、既存木として、できるだけ生かすというところで設計を進めているところです。","id":"exchange-168"},{"speaker":"高橋（伸）委員","kind":"質問","question":"地域の方、利用者から、どのような意見が寄せられたのかお聞きしたいと思います。","respondent":"高梨公園課長","answer":"その３も、その４もそうなのですが、そこをしっかり確保してほしいというようなご意見がございました。人気ということが分かりましたので、改修に際しましては、砂場もしっかりと残して改修するということで計画しています。","id":"exchange-169"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひそういった意見を反映して、今後につなげていきたいと思いますので、どうぞよろしくお願いいたします。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6695#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":135959,"voices":409}},{"id":"r06-20240315-3","meetingId":"r06-c-budget","date":"2024年3月15日","dateIso":"2024-03-15","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を180件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"せりざわ委員","kind":"質問","question":"３７５ページ、生徒指導対策費から、子どもたちの犯罪の防止という観点で、様々お伺いをしたいと思います。初めに、子どもたちの犯罪の被害防止のところからお伺いをしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういった犯罪に巻き込まれないような使い方、例えば今ご紹介のあったダイレクトメッセージですとか、そういったことも含めて指導をしています。小学生であれば、そういったところで声かけ事案でありますとか…","id":"exchange-001"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"１０年前に比べると、２０１３年の調査から５倍の被害件数になっていると、警察からも発表されています。見知らぬ方にどういうふうにされて、周知をしていくとともに強化をしていただきたいと思うのですが、ご見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"困ったときの窓口ということでありますけれども、例えば本区であれば、ＨＥＡＲＴＳに連絡を入れるということも考えられます。東京都が、相談窓口の一覧を長期休業前に例年配布しておりまして、そういったところで子どもたちには周知をしています。","id":"exchange-002"},{"speaker":"せりざわ委員","kind":"質問","question":"もう１点、加害防止のところでもお話をお伺いしたいと思います。残念ながらまだまだ、そういった子どもたちに対して、学校側が再犯防止というところでどういった取組ができるのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"そもそもその小学生、中学生の段階でそういった犯罪に手を染めないという指導は継続しておりまして、薬物乱用防止教室でも行っているところです。そういった地道な積み重ねを今後とも取り組んでまいりたいと考えております。","id":"exchange-003"},{"speaker":"せりざわ委員","kind":"質問","question":"様々、ＳＮＳを通じた、初めて手を染めてしまうケースというのをいろいろ講習されているというふうに伺っていて。品川区として、子どもたちの段階で止めていくというのが教育としてぜひ必要なのかなと思うので、再度ご意見を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"今、社会的に問題になっている、受け子の問題ですとか、そういったことにつきましてもしっかり子どもたちには指導を行っているところです。例えば弁護士を呼んでの授業ということも大変有効かと考えておりますので…","id":"exchange-004"},{"speaker":"ゆきた委員","kind":"質問","question":"私からは、３７７ページの市民科・各教科充実経費に関連して、防災教育についてお伺いしてまいります。そこで、まず、小・中・高校生に対する区の防災教育についての現状、取組についてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"区立学校、小学校、中学校、義務教育学校におきましては、各学校で年１１回、８月を除く月１回、避難訓練を実施しております。地震や火災、またＪアラートや不審者対応など、学校が年間通して計画を立てて実施しています。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"年間１１回の避難訓練、Ｊアラートも含めて行われているということ、各学校で訓練を行っていることを確認させていただきました。紹介するなど、後押しを進めてほしいと求めましたが、区のお考えをお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"台場小学校で令和３年に行われました、防災サイコロの授業ですけれども、防災課からの紹介で実現できたということで確認をしております。実施する事業者等ありますので、ご紹介いただきながら、有益なものは学校教育にも取り入れていけるように後押ししていきたいと考えておりま…","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問","question":"令和４年には、東京都教育委員会で作成の紙媒体の防災ノートが、デジタル教材として刷新されました。解説動画がつけ加えられ、より活用されやすくなり、この防災ノートの各学校での活用状況等についてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"こちらの防災ノートのデジタル版に直接アクセスできるような仕組みを整えております。各学校が実施しております避難訓練等の、そういった時期に合わせまして、活用を進めているところです。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"社会科とか、それぞれの教科で効果的に防災ノートも活用して、防災教育を行っているということを確認させていただきました。毎月行っている避難訓練の後を活用して網羅できるように進めてほしいと求めましたが、この辺について、区の見解をお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"各教科におきましても防災教育を進めておりまして、年間計画を立てながら、各学校では実施しています。こちらの防災ノートも併せて活用することで、より一層充実した防災教育の実現に向けて、学校へは周知徹底してまいりたいと考えております。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"防災教育時に教員が利用できるように、教員用指導の案と、児童・生徒用のワークシートが補助教材としても活用できるように制作されています。活用してほしいと求めましたが、この辺のことについて、区の見解があればお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"中学生向けの教材を区でも作成するということで、関係課とも連携をしながら、中学生への防災教育の充実というのは努めていきたいと考えております。様々そういった有効な教材、教具出ておりますので、そういったものも注視しながら検討を進めていきたいと考えております。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ前向きにさらに進めてほしいと求めました。この点をどのように把握して、どう解消していくのか、最後にこの１点だけお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"そこには、それを基に年間計画を立てておりますので、各学校とも最低基準というものは確実にクリアしているというふうに捉えております。その中で、各校の工夫で、子どもたちへの指導の充実を図っているところです。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"最低基準の全体計画を基に把握されているということ、確認させていただきました。格差のある点については、周知での後押し等により改善して、さらなる全体的な防災教育の向上を図ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"私からは、３７５ページの学校支援費、いじめ防止対策費について伺います。区内の公立小・中学校で、現在把握している学級崩壊は何件あるのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"学級崩壊に具体的な基準がないため、件数としてお示しすることはできませんが、複数の学校で学級崩壊の状態にあるという報告は受けております。その中で教育委員会が介入しているケースもあります。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"学級崩壊が起こると、学校と教育委員会ではどう対応することとなっているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"学校としては、可能な限り複数の教員で授業のサポートに入り、正常な学級運営ができるように努めているところです。相談に応じて、指導主事やＨＥＡＲＴＳの派遣を行っており、学級や学年をどのように立て直していくかということを学校と協議をしています。","id":"exchange-013"},{"speaker":"山本委員","kind":"提案","question":"７月に校長先生が教育委員会に相談をし、学校に状況を確認したり、提案をしてきたとのことでした。ＨＥＡＲＴＳや警察ＯＢの方々、地域ボランティアの方々に、発生後速やかに、連日サポートに入ってもらう仕組みはできないのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"地域の方にもご協力いただけるのであれば、大変ありがたいことだと考えております。そうした仕組みづくりにつきましては、学校のほうに提案することは可能だというふうに捉えております。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"それから、真面目に授業を受けたいと思っている生徒保護者の方々から、対象生徒を別室指導とすることの要望がありました。区のお考えを伺います。","respondent":"丸谷教育総合支援センター長","answer":"授業妨害があった際には、一時的に別室で指導を行うことはありますが、常に別室で指導を行うということは適切ではないと考えております。当該の児童・生徒から気持ちをしっかりと聞き取ることで、その後の支援につなげていくことが適切だと考えております。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"区のお考えも理解できます。区のお考えを伺います。","respondent":"丸谷教育総合支援センター長","answer":"指導者や周辺の子どもたちの訴えではっきり分かると考えており、常にモニタリングされるという環境はよい影響を与えるとは考えておりません。カメラがついているから、おとなしく真面目にしているということでは、本当の意味での子どもの成長にはつながらないと考えております。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"このように事実関係の確認を要する事態に限ってのモニタリングカメラの設置ルールの制定を要望いたします。区のご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"前もって対応方針を決めておくことは必要だと考えておりまして、学校が虐待を把握したとき、方針をあらかじめ保護者に示すように伝達したところです。実際に事案が起きた際には、基本的な方針の下、各事案の実態に応じた対応が求められると考えております。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"迅速に解決できるようにするため、学校現場の負担を軽減するため、有効な仕組みづくりを要望し、次の質問に進みます。個々のいじめ案件に対して、必要に応じて第三者が相談に乗れる仕組みが必要ではないかと感じましたが、区のお考えを伺います。","respondent":"丸谷教育総合支援センター長","answer":"本来は、教育委員会がその役割を担っており、学校と保護者本人との仲介を担うものだというふうに考えているところです。そういった第三者の立場であるということから、今後も保護者の理解を得るように努めていきたいと考えております。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"この問題でも、一番に考えないといけないことは、その子どもたちにとってその学校での時間が１度きりで戻ってないことです。問題が長期化しないよう、速やかにいじめ問題が解決できるよう、第三者の相談に乗れる仕組みの検討を要望し、私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"１月の文教委員会で審査された陳情でも要望もされていたものでもありますし、不登校児童・生徒の学びの選択肢を用意するという点で評価するものです。それと、活動や学習の支援を行うとありますけれど、具体的にはどのような業務を行うのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"配置の想定としては、各学校に週５日配置の予定です。支援員は、子どもたちのそういった悩み相談を受けたりですとか、学習支援というものを行うということで考えているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"だとしたら、支援員にとっての必要な資質やスキルというのは何だとお考えなのでしょうか。どのような研修を行う必要があると考えているのかというものも併せて伺います。","respondent":"丸谷教育総合支援センター長","answer":"子ども相手かつ不登校の状態の子ども相手になりますので、そういった心理面のサポートができる資質が必要だと考えております。各学校には不登校担当の教員配置も進めるよう今、そういった学校の担当者や管理職を通した形で支援員には研修を進めていきたいと考えております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、それではないと、その中身というのが本当に子どもにとっていい環境かどうかになるかというのは本当に大事だと思っているのです。質問ですけれど、指導員の専門性の構築、その担保についてもう一つ、もう少し伺いたいなと思うのですが、。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒の相手をするということで、専門性が必要ではないかというお尋ねかと思います。学生に向けては、そうした学校、現在の管理職からの指導ですとかそういったもので担保はしていきたいというふうに考えております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"この意味というのを教えてもらいたいのですけれど、あと代表質問でも指摘し求めてきたのですが、記載がないのです。教育振興基本計画には、盛り込みしっかり続けていきたいと思いますけれども、いかがか尋ねました。","respondent":"宮尾庶務課長","answer":"これを受けて、この教育基本法に定める行政計画としてこのたび、策定を予定しています。それから２点目の、当然に、この計画の策定に当たってはこの考え方に基づいて策定をしていくというふうに考えてあります。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"区教育委員会としては実際に、どんなふうに公開しているのだろうかということを確認する作業というのはしたのでしょうか、伺いたいと思います。工夫、改善が必要なのではないかと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"区教育委員会として各校それぞれ、全学校が校則をホームページ上に公開しているということは、ページとともに確認をしています。保護者や地域の方がご覧いただけるような工夫、改善を学校に求めるということで、引き続き次年度に向けて周知してまいりたいと考えております。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"代表質問では、実際に校則を見直している学校数も伺ったのですが、数を把握しないということなのですか。実施数も含めて、校則見直しの、主に中学でもいいですけれど現状について改めて伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"子どもの意見を聞いて校則を見直した学校の件数ということですけれども、中学校、義務教育学校それぞれ９校、６校ありますが、全ての学校において、子どもたちの意見を聞いて校則の見直しを図っているということで確認ができております。","id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"伺いたいのですが、提要が示すこの校則見直しへの児童・生徒の参画の教育的意義について、区教委ではどう考えているのか。こうした教育効果あるわけですから、いかがでしょうか、伺いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"そこに書かれているとおりの効果があるというふうに考えておりまして、大崎中学校の取組はこの趣旨に沿った取組であるというふうに捉えております。その中で、その中で子どもの権利条約という考え方につきましても…","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"毎年見直しというのを定式化したらどうかという質問に対してはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"失礼いたしました。毎年必ずということですけれども、そういった機会を捉えて進めていくように働きかけてまいります。","id":"exchange-027"},{"speaker":"筒井委員","kind":"提案","question":"３７２ページ、３７５ページ、ＳＮＳによるいじめ対策についてお伺いをいたします。ぜひ教育にも民謡の活用ということをぜひ、提案していきたいのですが、区のお考えはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"歌であったりですとか、鑑賞といったところで、学習指導要領や教科書でも示されているところで学習をしております。その民謡の歴史的な背景でありますとか、地域の状況も含めまして、合わせて行っているところです。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問・要望","question":"教員をやられている区民の方からご要望を受けまして、もっと質の高い教員が欲しいことや、副担任などを配置してほしいというご要望を受けました。まずお伺いをしたいのは、区としては評価をされているのでしょうか、説明を求めました。","respondent":"中谷指導課長","answer":"主には、その教材準備というようなところをメインとして、このスクール・サポート・スタッフの方に担っていただくというようなことをやっております。非常に教員の負担が減ったということは全校から寄せられておりまして、こちらについては継続してやっていきたいと考えています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"意見","question":"分かりました。今後、小学校１年から３年という範囲が限定されているのですけれども、小学校１年から３年となっていることに対する評価について説明を求めました。","respondent":"中谷指導課長","answer":"来年度、まず小学校の２校を指定させていただきまして、試行実施という形で取り組んでまいりたいと考えています。次年度はその２校でやっていた中での成果と課題を明らかにいたしまして、広げていくというような見込みで進めてまいりたいと考えています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"いいところをどんどん広げていっていただいて、教員の負担軽減にしっかりと努めていっていただきたいと考えております。やはりもう一度教員になりたいという方、世の中にいらっしゃるのかなと考えておりますが、区のお考えというのはいかがか尋ねました。","respondent":"中谷指導課長","answer":"年度末４４歳未満の経験者選考ですとか、昭和３８年４月２日以降に生まれた方、年齢制限をできるだけなくしてという形でやっております。引き続き、このような形で社会人の方も多く取り込めるようにやってまいりたいと考えています。","id":"exchange-031"},{"speaker":"せらく委員","kind":"提案","question":"事前に伺ったところの確認になりますが、全員に配付するものではないというふうに想定しているとお聞きしたのですけれど、確認させてください。その後、ご検討のほうをされたことがあれば教えていただけますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"ホームページ上でも公開をいたしますので、いつでも閲覧ができるようなことを考えているところです。登校支援だけではなくて例えば、仮想空間を利用したものですとか、何かいい名称というのは今後考えていきたいと考えております。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問・要望","question":"３６.９％の保護者が、９９.５％の保護者が、不登校をきっかけに支出があったと回答したそうです。当区ではそういった保護者の集まりなどは開催していますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"本区におきましては、マイスクールが主催となって、ファミリークラブ品川を実施しております。今年度は１１月に３日間行いまして、進路説明会や、その後の懇談の場ということで設けているところです。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"１１月に３日間開催しているということなのですけれども、マイスクール利用者以外も不登校でお悩みの方が参加できるということで、学年だとかそういうところの制限はありますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"特に学年の制限は設けてはございません。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問・要望","question":"こちらは要望です。こちらについてはどのように認識していらっしゃいますか。","respondent":"丸谷教育総合支援センター長","answer":"体育のときの着替えについてですけれども、小学校義務教育学校３７校中２３校が、１年生から男女別に着替えをしております。７校が３年生から、６校が４年生からということで、今の生命の安全教育と関連性を持った形での着替えというものを実施するよう周知したところです。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"着替えという場面も学校の生活の中で大事な時間であるというふうに思いますので、引き続き１年生から全校でできるようにお願いしたいと思います。すてきな笑顔の写真とともに掲載されておりまして、こちら「教育のひろば」の内容については誰がどのように決めているか伺いたいと思います。","respondent":"宮尾庶務課長","answer":"「教育のひろば」、広報紙に関するお尋ねです。保護者の方にお配りするという前提で記事を募りまして、最終的に、教育長ともご相談をして事務局内で決めさせていただいているです。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"年２回の発行なので、毎号どなたか委員の方の思いが聞けたらいいなというふうに思いまして、今回質問させていただきました。引き続き。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"そして３点目は、品川教育推進事業についてお伺いいたします。は学力定着度調査の状況を確認させてください。","respondent":"丸谷教育総合支援センター長、柏木学務課長、中谷指導課長","answer":"中学校、義務教育学校の８年生が自身のタブレット端末を活用して、オンラインで家計についてのシミュレーションを行っている取組になってあります。適宜… こちらは品川区が平成１８年度から、１年生からの英語科を実施するという、品川区の教育の特色として英語教育に力を入れてあります。… 区で実施しております学力定着度調査についてです。学年が上がる中で、理科や社会で目標を下回る結果などがありまして…","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"現在、将来的にはぜひ検討していただきたいというふうに思いますので、将来的な部分はぜひ要望させていただきたいというふうに思います。さらに子どもの遊びと学びの関係、フロー体験が子どもたちのウエルビーイングを向上する可能性について、区教育委員会の考えをお伺いいたします。","respondent":"中谷指導課長","answer":"７年生以降になりますと、筋道を立てて考えたり、人との関わりの中で自分の思いや考えを広げたり深めたりすることができるようになります。９年間の一貫教育を通じて、社会にある様々な課題解決にも、他者と協働しながら参画できる子どもたちを育ててまいりたいと考えています。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもの遊びと学びの関係とフロー体験のところもちょっとお聞きしたいところがあったのですけれども、フロー体験というのが子どもにとってすごく幼児教育等の文脈でも可能性を少し感じているところがありますので、ぜひ研究していただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"澤田委員","kind":"質問","question":"３８７ページ、ＩＣＴ支援員経費について、時間があれば３７５ページ、いじめ等防止プログラム経費について質問いたします。ＩＣＴ支援員の方の支援の内容を具体的に説明を求めました。","respondent":"柏木学務課長","answer":"ＩＣＴ支援員の支援の内容ですけれども、児童・生徒に対する操作の支援、教員によるオンライン授業を行うための支援ですとか。","id":"exchange-041"},{"speaker":"澤田委員","kind":"質問","question":"先生方から、それらのサポートについて定期的にヒアリング等はされているのでしょうか。区として把握されていることがあればお聞かせほしいと求めました。","respondent":"柏木学務課長","answer":"直接、教員のほうからの意見聴取というのは特に何か行っているものではございませんけれども、支援員の定例会がございまして、そちらのほうで各学校の状況等はその中で報告をされているものになります。","id":"exchange-042"},{"speaker":"澤田委員","kind":"質問","question":"その定例会などから上がってきた意見の中で、実際に変わったことなどは何かあったりするのか尋ねました。","respondent":"柏木学務課長","answer":"その支援の方法について、支援員の中でうまくいったこと、あとうまくいかなかったもの、そういうものの共有がされますので、そういう部分で、支援員全体で意識の共有と改善点が見えてきている、それに基づいてまた改善していくという状況です。","id":"exchange-043"},{"speaker":"澤田委員","kind":"質問","question":"今、その中でもやはりどうしてもＩＣＴ機器の操作等が苦手で、週１回以上の支援を必要とされている先生がいらっしゃるというお話もお聞きしています。全校一律週１回の巡回を基本としながらも、より先生方が、区としてはその辺りについてどのようにお考えか尋ねました。","respondent":"柏木学務課長","answer":"ＩＣＴ支援員の振り分けというご質問です。今後進めていく上で、少なくてもいいよという学校がもしありましたら、そういうことを振り分けていくというのも検討されるものと考えています。","id":"exchange-044"},{"speaker":"澤田委員","kind":"質問","question":"ＩＣＴに関連することで、先生しか行えない、支援員の方は行えないというようなサポートもあるのでしょうか。もしあるような場合は、どのような業務内容なのかということも教えていただけますか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"例えば教員でしかできない業務として、成績の処理ですとか、授業そのものについては教員でしか行えないというふうに考えております。例えば行事ですとか、授業中に操作が必要な場合のアシスト、こういったものは支援員の方にもお願いできる業務かなというふうに捉えております。","id":"exchange-045"},{"speaker":"澤田委員","kind":"質問","question":"以前、ＩＣＴ支援員の方たちから、先生の負担を減らすためにできることがあれば力になりたいというようなことを伺ったことがあります。ＩＣＴ教育を進めていく上でそれも大事なのではないかと思いますが、区としての見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"学校、先生方がＩＣＴ支援員にどんな業務を任せることができるのかというのを、それぞれの教員が把握するということが大切だと思っています。この業務は任せよう、お願いしようということが進んでいくと思いますので…","id":"exchange-046"},{"speaker":"澤田委員","kind":"質問","question":"ぜひ、教員の先生方にも、どこが任せられるかどうかというのも、例えばヒアリングなどして進めていってほしいと求めました。そのような場合、その修理代金は、区が負担する場合と保護者が負担する場合があるのでしょうか、教えていただけますか尋ねました。","respondent":"柏木学務課長","answer":"タブレットの故障時の対応ですけれども、こちらのタブレットはリース契約をしていまして、その中では保守契約というのも結んでおりますので、基本、故障等につきましては保守の中で行われるということで保護者の負担は基本は求めないこととなります。","id":"exchange-047"},{"speaker":"澤田委員","kind":"質問・要望","question":"保守契約があって保護者には求めないということなのですけれども、それは区の財源も使っていないというか、最初に申し込むときに契約に入っているという形なのですか、お願いします。","respondent":"柏木学務課長","answer":"区のほうで保守のお金も払っているということになります。先ほどの件で、消耗品という扱いでありますので、そこら辺についてはもしかすると保護者に代替を買ってもらうという場合があるかもしれません。","id":"exchange-048"},{"speaker":"澤田委員","kind":"質問","question":"度々壊してしまうような児童などについては、改めてしっかり指導したりアドバイスをするなどしていただけたらなと思うのですが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"当然授業で活用するツールの一つになりますので、年度当初等にその部分は、大切に使うことは学校を通じて周知していきたいと思います。","id":"exchange-049"},{"speaker":"澤田委員","kind":"質問","question":"これらの効果測定は行われるのでしょうか。もし行われる予定であれば、その方法やスケジュール感など何かお決まりのことやお考えがあれば説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"不登校にも効果があるということで考えておりまして、その出現率の低下ということも考えております。今後また、事業者とも詰めていきながら、どのような形で効果検証ができるかということも考えていきたいと考えています。","id":"exchange-050"},{"speaker":"新妻委員","kind":"確認","question":"私からは３７１ページ、３８１ページ、不登校全般についてお伺いをいたします。そこで、２０２４年度の学校選択制の希望申請数と今後の動向予測を伺います。","respondent":"柏木学務課長","answer":"２０２４年度入学予定の学校選択の状況ですが、希望申請数が５１９件、希望申請の率で言いますと１５.９％となっています。ここ数年、大体申請率としては減ってきているという状況ですので、この傾向はしばらくは続くのかなというふうに考えてあります。","id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"兄弟は同じ学校に通わせてほしいと、この議会でも要望してまいりましたが、兄弟枠を申請された方の状況を伺います。兄弟枠はどれぐらいいらっしゃって、その方がこの結果どのようになったのか、説明を求めました。","respondent":"柏木学務課長","answer":"２０２４年度入学予定者は、小学校と義務教育学校の前期課程につきましては、兄弟枠で申請された方は１５３人となっています。来年度入学につきましては、兄弟枠の方、小学校も中学校も全員繰上げとなっています。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"こういうガイドブックが作られるということ、しっかりと周知をお願いしたいと思いますが、まず見解を伺います。今しっかりこの支援員が３０名プラス学校での募集ということになっておりますが、今現状、確認をさせてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"支援員の募集についてですけれども、おかげさまで２０数名のエントリーがあったということで確認をしております。４月にまだ少し時間ありますので、何とか４月から始められるような配置を進めてまいりたいと思っています。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"この人員組織体制を整備するということを教えていただいたのですけれども、担当の先生がいらっしゃって組織運営をしていると、そのように伺いました。品川区での今後、これから進めていく、この不登校支援については、どのような位置づけになるのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"校内別室指導支援員が校内別室の運営というものを任されていくわけですけれども、各学校に今、なるべく行うようにということで周知をしています。そうした支援員と教員が連携をしながら、充実に努めてまいりたいと考えております。","id":"exchange-054"},{"speaker":"新妻委員","kind":"確認","question":"確認をさせていただきました。そして、出席扱いについて改めて確認をします。","respondent":"丸谷教育総合支援センター長","answer":"校内別室を利用された児童・生徒、またメタバース空間に出席をして学習支援等を受けた児童・生徒につきましては、出席扱いとするということで確認をしています。","id":"exchange-055"},{"speaker":"新妻委員","kind":"意見","question":"それぞれの個性に合った学びができるような品川区の先進的な教育をまた推進してほしいと求めました。すみません、時間がなくなってしまいましたので、以上で終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"援助として提供を受けた調査研究資料があると思いますが、こちらはどのように検証、活用しているのでしょうか。以上３点をお聞きします。","respondent":"丸谷教育総合支援センター長","answer":"教科書の調査検討委員会の地域の方等の人選についてですけれども、こちら区教育委員会のほうで人選を行っているところです。都教育委員会の資料は本当に参考程度に活用させていただいているです。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"質問・要望","question":"調査委員選任においては、区民の誰もが納得するような透明化を図ってほしいと求めました。しかし、傍聴に来られた方が分かりにくいとの意見は一理ありますので、何らかの工夫は必要かなと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"他自治体で教科書会社を挙げて採択しているという自治体もありますので、今後その辺りは研究してまいりたいというふうに考えているところです。教科書会社をオープンしているというところで、日が変わってしまいますが…","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"教育基本法第２条に「正義と責任、主体的に社会の形成に参画し、その発展に寄与する態度を養うこと。この教育基本法、こちらにのっとり、我が国の歴史に対する愛情が詰まった教科書をしっかりと選んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"ひがし委員","kind":"確認","question":"年々就学相談の参加者も増えてきており、需要が高まっていることが確認できます。相談体制など、充実を図っていく必要があると考えますが、結果を踏まえた本区における就学相談の今後の展開について伺います。","respondent":"唐澤特別支援教育担当課長","answer":"本区におきましても、新１年生、新７年生を対象に就学相談を実施しております。区の広報やホームページ、または就学前教育の関係課や施設への情報提供や、説明会を実施するなどして周知に努めております。","id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"就学相談については、保護者そして児童のニーズに合わせて引き続き充実するように要望をします。品川区、現状、転学相談というのはどのような形で行っているのか説明を求めました。","respondent":"唐澤特別支援教育担当課長","answer":"転学相談につきましては、一旦就学した先の学校のほうで、やはりいろいろな相談、保護者と学校が協議をして、その結果、転学というような形になりましたら随時転学相談の受付を実施しています。","id":"exchange-061"},{"speaker":"ひがし委員","kind":"意見","question":"それと併せて転学相談というのも就学相談と同じような形で受付をしていたり、申込みの流れ等が記載されていました。転学相談についての記載が見つからず、就学相談せっかくやってくださっているということで、区の見解について説明を求めました。","respondent":"唐澤特別支援教育担当課長","answer":"就学相談、転学相談ともに、区民の方、保護者の方に周知することが重要だと考えておりますので、引き続きその周知については検討研究してまいりたいと考えています。","id":"exchange-062"},{"speaker":"ひがし委員","kind":"質問","question":"例えば、嫌な顔をされたり、自分が休んでしまうことで他人に負担を与えてしまうため休みにくいといった状況があるというふうに伺っております。チームとしての学校体制整備が必要と考えますが、区としてどのような取組をしているのか、また、チーム学校に対する区の見解について伺います。","respondent":"中谷指導課長","answer":"ポイントはやはり１人が抱えるということではなく、学校が一つのチームとして学校経営を進めることが大切であると考えています。こういった事例を共有、推奨するとともに、既に実践している学校の取組の成果をこれからも継続して、把握して、共有をしてまいりたいと考えています。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"品川区、庁舎内に電話録音機、次年度４０台ほど入れるというふうに伺っております。機械採点を導入してほしいというようなお話を伺っておりますので、それぞれ見解について聞かせてほしいと求めました。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"土曜授業の回数についてですが、令和４年度から１４回から８回に減らした経緯があります。今後ですけれども、他自治体のところを見ながら検討していきたいと考えております。 庁内で来年度試行実施ということで、まずはそちらの効果も見ていきたいなと考えています。もう一つ、学校の電話交換機がその録音に対応できるかどうかというのもありますので、そこら辺のほうの調査等も必要と考えています。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"３８７ページ、教材教具費より、学用品の無償化について伺いたいと思います。今回の学用品無償化は義務教育の無償化に向けた自治体独自の対応なのか伺いたいと思います。","respondent":"柏木学務課長","answer":"さらに保護者の負担は増えているということで、保護者の負担軽減を図ることで、子育てしやすい環境を整備する必要があると考えています。しかしながら、各自治体独自の事業で実施することは、こちらのほうは財源も含めて少し限界があるのではないかと考えています。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう一点、本来は義務教育ですから、財源は国が保障すべきだと考えています。国や東京都に対して財源を求めているのか、求めるべきと思いますが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"まずはこちらのほうは先ほど申しましたとおり、目的については近年の物価高騰等を受けての保護者の負担の軽減という形となっています。様々な機会、特別区の教育長会ですとか区長会等を含めまして、そういうことは求めていくことも可能と考えています。","id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"別のほうから伺うと、授業料と教科書以外どこまでと考えているのかも伺いたいと思います。財源についても求めていくことは可能ということでしたが、ぜひ私はやはり求めていただきたいと思うのですけれども、改めていかがか尋ねました。","respondent":"柏木学務課長","answer":"ただ、品川区としては学校給食費の無償化に続いて、今回補助教材の無償化ということで、できる限りの無償化を今進めているところです。品川区１区だけの話ではございませんので、必要があれば求めていくということは、繰り返しになりますが可能ではあります。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"財源については可能だということであれば、ぜひ国や都に求めていただきたいと、ここは要望しておきたいと思います。私はいいと思っているのですけれども、このコメントはそういうことなのか、改めて伺いたいと思います。","respondent":"柏木学務課長","answer":"それと給食に関しては、その調理等にかかる設備、調理に関わる部分というのは無償としています。当然自治体でやれる範囲はありますけれども、給食費と今回の補助教材を無償にするという形で、できる限りのことをしているものです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問・要望","question":"自治体としてできるところの対象を広げていただきたいという点で、それから中学校の修学旅行、これもぜひ無償化してほしいと求めました。この卒業旅行と修学旅行についても教育の一環として、ぜひ無償化してほしいと求めましたが、いかがか尋ねました。","respondent":"柏木学務課長","answer":"まず教育委員会といたしましては今年度から実施している学校給食の無償化と、来年度予定しております補助教材の保護者負担軽減事業。検証を含めながら事業の精度といいますか、そういうのを高めていくということをまずは第一にしっかりやっていきたいと考えています。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"は一歩ということで、ぜひ無償化の対象も広げていただきたいと要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"えのした委員","kind":"質問・要望","question":"連携した新たな仕組みを要望し、ぜひ前向きなご答弁を願い、ご質問いたします。先日、山本委員からもご質問ございましたが、まずは地域部活動についてお伺いいたします。","respondent":"中谷指導課長","answer":"会場の確保がかなえば、８０名程度を受け入れられるような規模で実施してまいりたいと思います。ホッケー部につきましては１０月に体験会を行いまして、１２月から２月の期間で日曜日と木曜日に開催で、全１６回を予定しています。","id":"exchange-071"},{"speaker":"えのした委員","kind":"質問","question":"この部活動の期間や時期なのですけれども、これは５月からダンス部が始まりますが、７月には終了とこれは１学期だけなのですね。地域の保護者の方にも伺いましたが、なぜ継続して２学期、理由があればお知らせください。","respondent":"中谷指導課長","answer":"その背景といたしまして、こういった実施形態というのをまずは実証事業の中でやってみようということでご提案をいただいたことがあります。令和７年度まではこのような形態で進めまして、またそのあと効果を検証して見直してまいりたいと考えています。","id":"exchange-072"},{"speaker":"えのした委員","kind":"質問・要望","question":"そこでお伺いしますが、現状、既に学校側から希望する部活動は挙がっていますでしょうか。人気の多い種目など、選択理由も分かればお知らせください。","respondent":"中谷指導課長","answer":"運動部では、硬式テニス部や卓球部などの球技系、陸上部が複数の学校から出ております。文化部では、吹奏楽部やクッキング部などとなっております。","id":"exchange-073"},{"speaker":"えのした委員","kind":"質問・要望","question":"演劇なども含めまして、そういった団体もあるのでしょうか。全ての種目に指導員がつけられるような取組を要望しますが、区のご見解をお知らせください。","respondent":"中谷指導課長、丸谷教育総合支援センター長","answer":"今現在協議会のほうでご協力いただけるような方に関して、ディスカッションという形で協議をさせていただいているところです。そういった協議の延長線上として、学校と結びついていただくというようなことができればと考えています。 部活動支援につきましても、様々な部活動に配置できるような考えです。","id":"exchange-074"},{"speaker":"えのした委員","kind":"確認","question":"確認がとれました。部活動指導員のほうのお話が出ましたけれども、私はこれは文教委員会の際にも質問いたしましたが、区のご見解をお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"任用に当たっては、競技等の専門性だけではなく、生徒への指導が適切に行える人物かどうかを面接によって確認をしております。年度当初に部活動顧問や部活動指導員を対象とした部活動指導者講習を行っておりまして、指導者としての資質の向上を図っているところです。","id":"exchange-075"},{"speaker":"えのした委員","kind":"確認","question":"面接もあるとのことで確認が取れました。こういった面も重要だと考えておりますので、そういった取組をしっかりとしていただけると安心に存じます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"つる委員","kind":"質問","question":"３７１ページ、教育振興基本計画策定経費と、３８２ページの図書館費に関連して伺っていきたいと思います。冒頭、そもそも「きょういく」とは、また教師とは何か尋ねました。","respondent":"宮尾庶務課長","answer":"教育基本法と関連の法律等に規定されたこと、それらの目的を事務局としてしっかりと遂行していく、履行していくということだと考えています。","id":"exchange-077"},{"speaker":"つる委員","kind":"提案","question":"教師は、子どもが自らの力で知識を構成することのサポーターであるという形で教育に臨まれていた校長先生がいらっしゃったということも伺いました。既存の指導要領なども含めて、品川区の公教育の体制について、今現在どのようにお考えであるかを説明を求めました。","respondent":"宮尾庶務課長","answer":"令和６年度に策定を予定しております教育振興基本計画、これまで品川区が取り組んでまいりました各種の教育施策、これからの区の教育施策の進むべき方向性をお見せしたいと考えているところです。","id":"exchange-078"},{"speaker":"つる委員","kind":"質問・要望","question":"１人の子どもが「何だ、字かよ」と言って、教室は笑いに包まれたというエピソードを伺ったのです。どういうときに調べるのですかと言ったら、その発している言葉がどうなのかとチェックして、するためにやっていますと。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちが今はインターネットでたやすく調べられる時代ではありますけれども、辞書を引く意味というのもあると考えております。いろいろな言葉があるのだなというところで身につけていくというような授業が、通常の国語の授業での辞書の活用です。","id":"exchange-079"},{"speaker":"つる委員","kind":"質問","question":"そういった中で先日１１月２９日の行財政改革特別委員会の資料も拝見させていただきましたけれども、すごくスタイリッシュな感じであったりしました。整備、これをお願いしたいと思うのですが、こうした図書館の整備計画などについてのお考えがあれば説明を求めました。","respondent":"吉田品川図書館長","answer":"そのため、大体歩いて１０分から１５分ぐらいのところに、規模は大小ありますけれども図書館の整備を進めてきたところです。今、大きいものはございませんけれども、現在図書館の流れとしてはそういうようなことを求められているところもあるかと考えています。","id":"exchange-080"},{"speaker":"つる委員","kind":"質問・要望","question":"私たちも議員としては区民の心の代弁者として質問させていただきました。それが無限の価値となるような質疑だったというような形にしていきたいと思いますので、引き続き研究ではなくて検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"３７７ページの教育総合支援センター運営費で、３７２ページ、３７１ページの学用品の援助費について少しお伺いします。中塚委員の質問の続きみたいになってしまうのですけれども、ちょっとその辺をまずお伺いしたいので、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"修学旅行、移動教室ともに教育課程内で行われる行事です。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その中で、この２つは保護者というか私費で行われているのか、公費で行われているのか、その辺の内訳を説明を求めました。","respondent":"柏木学務課長","answer":"本区におきましては移動教室、これは６年生も７年生もですが、移動教室については基本、公費で実施をしています。修学旅行につきましては私費で実施をしています。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは両方とも教育課程なのですけれども、この違いというのはどうして表れているのか尋ねました。","respondent":"柏木学務課長","answer":"ただ、こちらは移動教室も修学旅行も、移動教室について公費で負担しなくてはならないものではございません。自治体によっては、移動教室を私費で実施している自治体もあります。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"母子家庭は５０％以上が相対的貧困と言われている中で、これは無償化を目指していくべきなのだろうと思いますので、その辺は強く要望します。それと併せてなのですが、学校の教員の自己負担、その修学旅行や移動教室の自己負担というのはどのようになっているのか尋ねました。","respondent":"柏木学務課長","answer":"教員の自己負担につきましては、基本、食事代と、あともし現地で何か飲物を買った場合ですとか何かお土産を買うという部分は、教員の自費負担となっています。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはり教員も生徒も含めて自己負担なく修学旅行なり移動教室が実施されるということを願っておりますので、これも要望しておきます。教員の負担軽減という意味で、重要性が高まっていると思うのですが、区としての受け止めはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"スクールカウンセラー、スクールソーシャルワーカーにつきまして、子どもたちのニーズ、保護者のニーズも高まっているという認識です。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"では同じ見解で非常に安心しました。そういったところで、現在のスクールカウンセラーとスクールソーシャルワーカーの配置というのはどのようになっているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"合計５４名の配置となっております。会計年度任用職員として６名を区で任用しておりまして、四日フルタイムで勤務しており、要請に応じて学校に派遣をしている形態を取っております。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"スクールカウンセラーはどうしても学校の中で収まってしまうけれども、スクールソーシャルワーカーは非常に大事になってくると思います。四回ということなのですけれども、さらなる増員をぜひお願いしたいのですけれども、そういったご予定のほうはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"スクールソーシャルワーカーの役割、福祉につなげるということで非常に大きな役割になっております。この人数の拡充につきましては、実際の動きと併せて検討していきたいと考えております。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先月か今月初め、東京都のほうでスクールカウンセラーが２５０名一斉に雇い止めに遭ったというようなかなりショッキングなニュースがありました。非常に子どもにとってもよくないですし、こういった問題は起きてはいけないとは考えているのですけれども、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"いわゆる東京都のような雇い止めと言われるような年限の期間というのは決めておりませんので、毎年毎年応募していただいて任用を続けているです。継続希望のスクールソーシャルワーカーにつきましては、その勤務実態に応じて、新規の方とも不公平のないように任用の手続…","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"やはり安定して会計年度、会計年度任用職員ではないような形をぜひ正規ということも前向きに考えていただきたいと、こちらも要望します。その中で、特別支援学校は、こちらは対象になっておりますか尋ねました。","respondent":"柏木学務課長","answer":"来年度の実施予定です、補助教材の負担軽減事業につきましては、品川区立の学校が対象となっています。特別支援学校は、現在のところ対象とはなってございません。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"３８１ページの教科書採択事務について伺います。その理由と拡充内容を伺います。","respondent":"吉田品川図書館長","answer":"今まで年間７３５時間契約していたところを、その５校については８８２時間、１４７時間増加するということの変更です。この増やした理由につきましては、昨今の小学校の学級数増を鑑みた特例的なところで、試験的なところと認識しております。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、さらなる拡充を求めたいと思います。この所管評価と最終評価の違いが生まれている理由を伺います。","respondent":"吉田品川図書館長","answer":"最後に評価のところに、所管としましては運営支援スタッフを活用した事業、今後拡大していきたいというところで評価したところです。学校支援スタッフの配置につきましては各学校それぞれの適切な人数が必要であるというふうに評価を受けたところで、変更したところです。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問","question":"違いが生まれている理由を伺ったのですけれども、そうすると特に違いはなく、拡充していくべきだということでしょうか。伺います。","respondent":"吉田品川図書館長","answer":"例えばボランティアであったり図書委員であったりだとか、これまでもそういう内部的な運営をしてきたところです。そういうところを全体的に鑑みまして、今後よりよい方向で検討していければというところで考えております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、先ほど右肩上がりということで答弁がありましたけれども、この実際貸出冊数の実績を伺いたいと思います。そして、この運営支援スタッフ、学校司書を配置することで貸出冊数が増えていくと、増やすことができると思うのですけれども、いかがか尋ねました。","respondent":"柏木学務課長、吉田品川図書館長","answer":"令和２年度が９５万冊、令和３年度が１０４万６,０００冊。令和４年度ですが、こちらは１０３万３,０００冊ということで、大体年度にもよりますけれども、大体増えてきているという状況です。 この貸出数につきましても、実際に現状この十数年間、司書の人数としては増えていないところです。図書委員の努力だったり、実際の司書の努力もあると思いますけれども、その全体の中で増えてきたものと理解しております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問","question":"司書の方に聞きますと、やはり司書がいると子どもの目の輝きが変わってくるということでお話をされていました。やはりこの図書館の活用を進めていくためにも、学校司書の配置を週５日にすべきだと思いますけれども、いかがか尋ねました。","respondent":"吉田品川図書館長","answer":"それは多分１年、２年、それなりの長い期間がかかるかもしれません。そういうのを踏まえまして検討してまいりたいと思います。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"教員にも聞く機会を保障していただきたいと思うのですけれども、教員の声は反映されているということなのですけれども、いかがでしょうか。教員の方もしっかり意見を出せるようにということでやっておりましたので、そうしたやり方をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"今年、やはり採択に向けた手続・スケジュールを考えたときに、それを反映させるというのは難しいスケジュール感かなと捉えております。教科書の見本本を学校に置くということ自体が、今、そういう仕組みになってございませんので、ご提案のところは難しいかなです。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問","question":"そこはしっかり反映できるようなスケジュールで組んでいくということが必要だと思うのですけれども、いかがでしょうか。教員の意見を保障するというところでは、今そういう仕組みになっていないというのはどういった変更があったのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"採択のスケジュールはこれから組んでいきますけれども、十分な区民の意見をその場に反映させるということは現時点では難しいと捉えているところです。その研究会の中で十分検討資料を作っていく中で、初任の方でも使いやすい、そういった観点からも調査を進めているところです。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"教員についてはぜひ意見を出す場は保障してほしいと求めました。実際やっているわけですから、改めてその改善を求めたいと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"実際に教科書を使用するのは児童・生徒ですので、専門性のある教員が調査研究を行って、教育委員会でしっかりと採択するということが大切であると現時点では考えております。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民の意見を聞いているわけですから、それはしっかり反映できるようにしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、今回の来年度予算案を合わせると、品川区の取組は多様化してきている、すばらしいと感じています。一、二年生に対して、特に教科学習以外の学習の工夫はどのように行っていますか尋ねました。","respondent":"中谷指導課長","answer":"児童が考えたことを認める言葉をかけるだけでなくて、どうしてですかというような疑問形で投げかけることで思考力が高まっています。絵で表現したり、発達段階に応じたとても充実した取組ではないかと考えていますので、こういった取組を広げていきたいと考えています。","id":"exchange-100"},{"speaker":"せお委員","kind":"質問","question":"そのような保護者が登校渋りで困ったときに、どこに相談すればよろしいでしょうか。何か今現在取り組んでいらっしゃることとかありましたら、説明を求めました。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"魅力のある給食にするため、毎年栄養士に集まっていただいて献立等の検討をしています。いただいた意見をそういう場には伝えて、より魅力のある給食にしていきたいと考えています。 お子さんが学校に行きたくないというようなときに、保護者がどう声かけてあけたらいいか、大変苦慮するところだと思います。はＨＥＡＲＴＳにご相談いただいても対応いたしますので、ぜひ窓口にご相談いただければと考えております。","id":"exchange-101"},{"speaker":"せお委員","kind":"質問・要望","question":"次に、項目は学校環境整備事業となるのでしょうか。学校でのプレイパーク、今後検討していただきたいと思っていますが、見解を説明を求めました。","respondent":"森学校施設担当課長","answer":"屋上の有効利用ということで、ご意見いただきました。屋上緑化であったりとか、かなり設置してありますので、改築校についてはなかなか屋上を利用するのは困難かと考えています。","id":"exchange-102"},{"speaker":"せお委員","kind":"質問・要望","question":"とにかく学校を楽しめるというか、過ごしやすくなる環境をぜひ充実を図っていただきたいと要望いたします。この２点については、どのように現在取り組んでいますでしょうか、説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"個人面談等の機を捉えながら、保護者には学校での過ごし方というのを伝えているところです。学校公開は年に複数回ありますので、家庭での様子と学校での様子の違いですとか、そういったところを保護者にご覧いただいているところではあります。","id":"exchange-103"},{"speaker":"せお委員","kind":"質問・要望","question":"これは要望です。最後に、この特別支援教育費のところでお聞きしたいのですけれども、どのような方針が下りてきているのかというのを教えてほしいと求めました。","respondent":"唐澤特別支援教育担当課長","answer":"東京都のほうですけれども、これまでと同様として、多様な学びの場における児童・生徒の障害の状況に応じた支援体制の充実を図っていくというような形で、次年度の予算事業についても概要ですけれども連絡が来ているところです。","id":"exchange-104"},{"speaker":"せお委員","kind":"質問・要望","question":"今度都立学校には特別支援学校を併設させてという取組もやるというのを伺っているのですけれども、ちょっと何か東京都のほうの方針が見えてこなくて。要望ですが、何か方向性などを東京都が示していただけると大変ありがたいと思っていますので、ぜひ意見交換などをお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"石田（し）委員","kind":"質問","question":"それと、時間があれば、これもちょっとページが分からないですが、主権者教育についてお伺いします。","respondent":"桑村副区長","answer":"今まさに区長部局に置くことによって一種の刺激を与えているというのか、どうするのかお互いに考えるきっかけをつくっているのだと思います。なかなか答えは出ないのだと思いますけれども、令和６年度、あるいはご批判をいただければと思っています。","id":"exchange-106"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"今、家庭ではそうやって考えていろいろやっていても、できたらここは学校給食にも完全国産化だということでやっていただきたいなと思います。そういったいろいろな意味でぜひこの完全国産化についてやっていただきたいと思うのですが、区のご見解を説明を求めました。","respondent":"柏木学務課長","answer":"できる限り国産の食材ということで、今実施をしてございまして、完全国産化をするにあたって、やはり幾つか課題があります。１日約２万４,０００食ありますので、あと地方との連携もありますが、ちょっと完全と言われると少し難しいかなという答弁になりますので。","id":"exchange-107"},{"speaker":"石田（し）委員","kind":"意見","question":"でもこれは、これも含めて私は国が本来やるべきことだと思っていますが、もう区がまず先頭に立ってやっていただいて、東京都も今少し動き出しました。以上で時間がなくなりましたので終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"学校支援費９,１８０万円余の中のいじめ防止対策費からですけれども、予算的には８,５７０万円余強の予算が組まれています。本音をお願いいたしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"もうここ２０年、３０年ぐらいの話でございまして、現在まで継続しています。そういった被害者に寄り添った対応ができるように、我々教育委員会、学校現場としては努めていきたいと考えているところです。","id":"exchange-109"},{"speaker":"木村委員","kind":"質問・要望","question":"それが本当になくなるのか、なくなることができるのかどうか。これをイエスかノーかでお答えください。","respondent":"丸谷教育総合支援センター長","answer":"不可能だと考えておりますが、いじめが発生した際に早期対応することで、全てのいじめにおいてやって取り組んでいかなければいけないと考えているところです。","id":"exchange-110"},{"speaker":"木村委員","kind":"意見","question":"なぜこのいじめ問題というものが起きるのか。それに対して説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"いじめ根絶協議会についてですが、平成２５年度に設立、設置をしています。学校において子どもの生命・安全が損なわれる事件・事故、子どもたちの安全・安心をしっかり守っていくという趣旨で設立をしていったものです。","id":"exchange-111"},{"speaker":"木村委員","kind":"質問","question":"具体的にお聞きしますけれども、いじめた側に対しての注意というかそういうものと、あと、いじめられた側というのはどういうフォローをしているのか。それが分かれば説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"そういったところは教員がしっかりと子どもと向き合って、今、行った行為が相手を傷つけている行為だということを丁寧に説明した上で。そういったことのことが今後起こらないように、相手の気持ちを考えて行動するような促し・指導を教員は行っているところです。","id":"exchange-112"},{"speaker":"木村委員","kind":"意見","question":"そういうフォローをしてくれていると思うのですけれども、それがどのような効果を生んでいるのか、そういうことを調べたことがありますか。何か本当にそういうところに釘を刺す、そういう効果的なものが何かあるのかどうか、そういうことをお考えになってるかどうかも説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"効果的な指導というものにつきましては、次年度、いじめ予防プログラムを実施していきます。全区立学校でいじめ予防プログラムを実施して、子どもたちが安心して学校に通えるような環境づくりを行ってまいります。","id":"exchange-113"},{"speaker":"木村委員","kind":"質問","question":"はっきりお聞きしますけれども、実際にいじめというものはなくなっているのか、少なくなっているのかどうか。このことをはっきりとお答えください。","respondent":"丸谷教育総合支援センター長","answer":"子どもたちがまずいじめとはどういうものなのかということをしっかり認識する必要があると考えておりまして、小さないじめは必ず起こるものです。それが重大化しないように、今後いじめ予防プログラムを通して努めていきたいと考えております。","id":"exchange-114"},{"speaker":"木村委員","kind":"質問・要望","question":"そういうふうにして努力をされているということは本当にこちらもありがたく思うところであります。本当に徹底して子どもに対してフォローしてあげていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３９５ページ、源氏前小学校校舎等改築、それから３７９ページのブラインドサッカー体験教室、この２点についてお伺いしたいと思います。初めにまずお伺いしたいのは、全クラス１年から６年生まで２クラスということで１２クラスを使っているのですけれども、計画というのか尋ねました。","respondent":"柏木学務課長、森学校施設担当課長","answer":"源氏前小学校の推計になりますけれども、毎年大体７０人から８０人ぐらいの就学人口がいるという形で今後推移していくという推計になっております。今の源氏前小学校の入学率等で算出しますと… 新旧どちらかは必ず使えるように計画をしておりまして、体育館での授業、それから休み時間での活動は可能なように検討しております。それと、ボルダリングウォール等を設置させていただいて…","id":"exchange-116"},{"speaker":"塚本委員","kind":"質問","question":"今いろいろなご配慮いただけるということで伺いましたけれども、小学校の足かけ６年というと、ぜひ配慮のほうをよくよくお願いしたいと思います。このラーニングコモンズ、ＳＴＥＡＭコモンズ、どういった目的なのか、また具体的な活用はどのようにされるのかお伺いしたいと思います。","respondent":"森学校施設担当課長","answer":"２点ご質問いただきました。５つの領域を対象とした理数教育に創造性教育を加えた教育理念、理科室と音楽室、新たな学びが生まれるような配慮をして設定しています。","id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"今年度までは、多様性理解、そして多文化共生推進事業と銘打たれたものの一環としての実施というふうに変わってきております。多文化共生推進というふうに銘打って行っていくこの新たなスタートというようなことも言えるかもしれませんが、その考えについてお伺いをいたします。","respondent":"中谷指導課長","answer":"今までしながわ学校２０２０レガシー事業として継続してまいりましたが、令和７年度のデフリンピック東京開催を契機に。ブラインドサッカーについては継続実施をするとともに、パラスポーツの体験授業であったり、各種施設団体との交流もやっていきたいと考えています。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"時間があれば３７７ページ、地域の歴史・文化学習についてお伺いします。昨年決算特別委員会でもちょっと質問したのですが、なかなか思いが伝わらなかったので改めて伺いますが、報告がなされました。","respondent":"丸谷教育総合支援センター長","answer":"当時いじめの重大事態としての認定がなされておらず対応をしてきたというところ、その辺りは真摯に受け止めております。区長部局のいじめ問題調査委員会を立ち上げて、この教育委員会の在り方について調査をしていただいたというような流れと捉えております。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問","question":"何でしょうか、それを踏まえて新年度、さらに同じような趣旨のものがこの区長部局にも予算化されています。私は絶対に受け止めてはいけないと思うのですが、その辺どのように受け止めているのか、改めてお伺いをしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いじめが起こった際には、学校がまず一義的には早期対応することで解決を図っていくものです。教育委員会からも支援をしていくというふうに捉えておりまして、教育委員会としては、学校がとにかく解決を図る。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ教育というのは国家１００年の大計で、時代がどういう変化があろうとも、それに基づいた品川の教育がなされるべきだと考えています。ただ一方で、やはり教育委員会としての主体性というか指導力といいますかリーダーシップというものが求められてくると思います。","respondent":"宮尾庶務課長","answer":"これまでの区のプラン２１ですとか教育ルネサンス、今お話のあったように教育施策を総合的、それから体系的に計画をしていくです。当然にこの計画ができた後、この計画に基づいて教育施策を教育委員会一体となって推進をしていくという考えです。","id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"給食の内容とかも献立も含めて、無償化でどのような時代であろうとその品質は保っていくという、そういう視点での取組をぜひお願いしたいと思います。時間がありませんので、要望だけ伝えします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-122"},{"speaker":"こしば委員","kind":"質問","question":"私からは、３７７ページ、市民科・各教科充実経費について伺います。本格実施から、２年後には２０年を迎える中で、これからもこの「市民科」の名称を続けていくのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"この社会の形成者ということで、区民ではなくて広く一般的な意味として、市民という言葉を用いて名づけたというふうに認識しております。今後についてもこの市民科という名称を、ここまで浸透してきていますので、しっかりと市民科という形で実践を進めていきたいと考えておりま…","id":"exchange-123"},{"speaker":"こしば委員","kind":"質問","question":"お聞きしますが、２００４年当時からこの２０年間、市民科の導入によってどのような変化があったのか。市民科の目的は達成されているのかどうか、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"なかなか市民科を９年間受けた子どもたちが今どのような社会生活を送っているのか、品川区といたしましては、またよりよい品川区をつくっていく。そういった人材を築き上げていきたいと考えております。","id":"exchange-124"},{"speaker":"こしば委員","kind":"質問","question":"子どもたちは対面での交流が難しくなり、楽しい食事時間も黙食を続けるなど、そういう中での市民科教育の課題はどのようなものだったのでしょうか。課題に対して市民科教育はどのように変わってきたのか、教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"そのような中で市民科の授業もしっかりとやりながら、その制限のある中ですけれども、その中でできる限りのことはやってきたと考えております。今年度、学校では様々な取組が再開していまして、また複数年かけて子どもたちをしっかりと育てていきたいと考えております。","id":"exchange-125"},{"speaker":"こしば委員","kind":"質問・要望","question":"その中で、集団や社会の中での個はモラルある行動や言葉が求められます。町ぐるみとなった教育を通じて道徳を展開してもらいたい、そのように考えますが、区教育委員会の考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"各校年に一回以上実施しておりまして、地域の方にも市民科の授業を見ていただき、授業を見終えた後には協議の時間も設けております。大人がもう一体となって協議をしている場ですので、こういった取組を大事にしながら子どもたちの教育の充実を図っていきたいと考えております。","id":"exchange-126"},{"speaker":"こしば委員","kind":"質問・要望","question":"時間があと３０秒となりましたけれども、課外活動、これをやはりさらに時間を取って継続的に取り組んでいただきたいと考えています。実学のさらなる拡充に向けて、教育委員会のお考えを教えていただきたいところですが、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-127"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１２月に区長とＰＴＡの懇談会か何かがあって、その方が言ったかどうかはちょっと別として、そういう話がありました。だって、今だって週１回行って、こういう人がいたら少し気にしてみてくださいと待ったりできているわけではないか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"しっかり学級担任が子どもたちに目を向けるということが大切だと考えておりますし、日々の健康観察をアプリで行うような予算もあります。そういったものを通しながら、子どもたちの変化についても気づいていけるように取り組んでまいります。","id":"exchange-128"},{"speaker":"石田（秀）委員","kind":"意見","question":"今言った予防も知っています。人のこともあるから、これは区長部局がぽんとやらないとこれは多分無理だと思っているから、区長部局に答えてほしいと言っているということですとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"スクールカウンセラーは、学校の状況を見ながら必要があれば予算のほうを要望していきたいと考えております。","id":"exchange-129"},{"speaker":"松永委員","kind":"質問","question":"私からは、３７５ページの帰国児童・生徒等支援費、１,３６４万９,０００円について伺いたいと思います。そして、本区においてどのような教育支援をされ、派遣講師についてでありますが、外国人の方がされているのでしょうか、併せて伺いたいと思います。","respondent":"丸谷教育総合支援センター長、柏木学務課長","answer":"現在、ＩＷＣというＮＰＯ団体に委託をしておりまして、実施をしています。講師は日本人が行っております。 外国籍の児童・生徒数ですが、学務課で把握している小・中学生合わせまして約７４０名、そのうち品川区立の学校に通っている方は３７０名と把握しています。","id":"exchange-130"},{"speaker":"松永委員","kind":"質問","question":"そうした中で、教材費について伺いたいのですが、本年度１０万円計上されております。外国の方が転入届を出された際に、お子さんがいらっしゃる場合に、こうした事業がありますという紹介はされているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"教材費についてですけれども、児童・生徒が使用するワークシートの印刷代ですとか、視聴覚資料の準備というところで予算計上しているものです。まず学校で校長が面接を行いますので、日本語の習得状況を見ながら、こちらの日本語教室をご案内しています。","id":"exchange-131"},{"speaker":"松永委員","kind":"質問・要望","question":"初級では３７０回、中級が１５０回ですが、どうなのでしょうか。初級を受けたら、普通は大体中級を受けるという可能性があるとは思うのですけれども、なぜこのような差が生まれているのかお知らせください。","respondent":"丸谷教育総合支援センター長","answer":"一定程度習得を行いますと、もう学校で授業についていけるというお子さんも、中には出てきます。受験にも対応できるような形での指導を行っているところでございまして、中級は受講していないために、このような差が生まれているものです。","id":"exchange-132"},{"speaker":"松永委員","kind":"質問","question":"もしそうであれば、１回に当たり何時間の受講が可能なのでしょうか、併せて伺います。そして、２５回というのは１年間の回数なのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"１回ということですので、特に時間制限というのは設けておりません。減額の理由ですけれども、実績に合わせまして、十分足りるということでの判断でこのような結果となっております。","id":"exchange-133"},{"speaker":"松永委員","kind":"質問","question":"外国人の方で品川区に転入される方も結構増えてきておりますので、そうしたところの対応はどのようにされていくのでしょうか、お知らせください。","respondent":"丸谷教育総合支援センター長","answer":"山中小学校で９８名の児童・生徒が指導を受けていますけれども、山中小以外の教室を増やして、指導の充実を図るように考えております。現在八潮地区、具体的には八潮学園の中の空き教室を利用して、日本語指導のエリアを増やしていくという考えです。","id":"exchange-134"},{"speaker":"松永委員","kind":"提案","question":"そうした場所で、移動が難しいということで諦めている方もいらっしゃるのではないかと思います。例えばスクールバスなどを提案させていただきたいのですけれども、この２点、伺いたいと思いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"移動についてのバスの手配等を、行う考えは今はないのですけれども、タブレットを活用したオンラインでの日本語指導というものを、既に令和２年度から実施しておりまして、移動の難しい方はオンラインでの受講もできることになっております。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"その学校に対しての対応をどう考えられますでしょうか。いろいろな関係機関の連携というものを考えていってほしいと思うのですが、区長の権限を強めるということに対してのご意見を伺いたいと思います。","respondent":"柏木学務課長、宮尾庶務課長、唐澤特別支援教育担当課長、丸谷教育総合支援センター長、森学校施設担当課長","answer":"中学校・後期課程の生徒数のピークは令和２２年度に推計がされております。就学人口の増加と３５人学級の導入に伴いまして… これまでもプラン２１ですとか、品川教育ルネサンスといった独自の教育改革を進めること、先進的な取組によって教育施策を推進してまいりました。… 今後も就学相談の際に、そうした情報というのは保護者の方と共有しながら対応していければと考えています。… 条例が改正になるという見込みですけれども、いじめの発見・認知といったものは学校が…","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"保護者のほうが、普通学級がいいとか、いろいろな要望があるのです。なので、そこをやろうとするときには、本当に専門的な知識が、これからかなり求められると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-137"},{"speaker":"若林委員","kind":"質問・要望","question":"年度内に終わるのかということの確認と、その結果、ペグ等が見つかったのかどうかという確認もします。１期とか２期とか３期という表示があるので、その「期」とはどういうことなのかの確認をします。","respondent":"森学校施設担当課長","answer":"２２校中、残り６校まで進めておりますので、今年度中には終わる予定です。大体３期か４期ぐらいで終わる予定にはなっておりまして、何期目なのかというのを表すために、何期と表現をしています。","id":"exchange-138"},{"speaker":"若林委員","kind":"確認","question":"時間がないので確認だけですが、どうしても拡幅をしないと工事ができないという事例がありまして、そこだけ確認をさせてください。","respondent":"森学校施設担当課長","answer":"道路の幅員については、特に定めてはいないのですけれども、道路が狭いと工事の期間がとても延びるというのがあります。何ｍ以上だとやるとか、やらないとか、そういうのはないのですけれども、道路が狭隘ですと工事期間が延びて、影響が大きいとは考えてあります。","id":"exchange-139"},{"speaker":"若林委員","kind":"確認","question":"狭くても工事は可能だということを確認させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-140"},{"speaker":"西村委員","kind":"提案","question":"３７９ページ、不登校対策事業費全般より、校内別室指導支援事業や、メタバース、ポータルサイトについて伺います。メタバースで親支援に取り組めないか伺いたいと思いますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"親向けの空間というのを常時設置することは難しいのですけれども、例えば講演会ですとか、そういったものはできるかなと検討しているところです。子どもたちが自分のアバターを自由に変更できるような仕様にもなっておりますので、服装の色を変えたり…","id":"exchange-141"},{"speaker":"西村委員","kind":"質問・要望","question":"不登校に子どもがなっていない親御さんも入れるものかどうか伺いたいと思いますけれども、親としてもヒントを得ることができると思っています。最後に、このサイトなのですけれども、子ども自身もいろいろな情報を知ることができるように、キッズページの開設も求めます。","respondent":"丸谷教育総合支援センター長","answer":"ポータルサイトについてですけれども、児童・生徒の皆さんへということで、子どもたちが読むページというのも設ける予定です。１人１台タブレットの中にもリンクを貼ることも検討しておりますので、子どもたちがそこに入れるような工夫もしてまいります。","id":"exchange-142"},{"speaker":"西村委員","kind":"質問","question":"親が忙しくて見られなくても、子どものほうが情報をキャッチアップしているということは私自身もよくありますので、ぜひともお願いしたいと思います。質問は変わりますけれども、コロナが明けましてから、オンライン授業を実施している学校があるのか伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒への支援ということですけれども、担任が家庭を訪問しながら支援に当たるということは、今でも行ってあります。子どもたちの状況に合わせて先生から提案をして、了承を得られれば、お互いの了解の下に実施しているケースもあります。","id":"exchange-143"},{"speaker":"西村委員","kind":"質問・要望","question":"学校側から伺うと、再開のご検討をいただきたいのと、連携を検討してほしいと求めました。区のご見解とお考えを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"１人１台端末、不登校支援や、十分活用するように求めてまいります。","id":"exchange-144"},{"speaker":"西村委員","kind":"質問","question":"最後に、遅刻をするお子さんに対して教室まで保護者の付添いが必要なのは、区内全校で同じでしょうか。校門まで来たら対応するなど、今後、校内別室指導員がこのような場合にも柔軟に対応することはできるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"遅刻をする児童・生徒への対応についてです。学校によって考え方が違うと思いますが、職員室までであったり、各校で取り組んでいるところだと考えております。","id":"exchange-145"},{"speaker":"西村委員","kind":"意見","question":"学校によって、もしかしたら差があるかもしれませんので、校門まででいいということであれば、改めて、いろいろな学校でそのような柔軟な対応ができるようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"ただ、鈴ケ森小学校は仮設校舎を造るので、体育館が大きいのではないのですが、その点についてはいかがでしょうか。教室の見込みをしっかりと余裕を持って、転用可能な教室という形で対応すると思うのですが、その点についていかがか尋ねました。","respondent":"森学校施設担当課長","answer":"工事工程を組んで工事を進めていきたい、そのことか可能かどうか含めて、実施設計を行っていきたいと考えています。設計の段階での教室の見込みなのですけれども、鈴ケ森小学校は区の南端のほうにありまして、余裕教室を多めに設計して計画しているような状況です。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問","question":"では次、３８３ページ、図書館運営費です。図書館の持つまちづくりの視点における図書館の役割、まちづくり、まちの活性化に果たす図書館の役割というのはどのようなものか尋ねました。","respondent":"吉田品川図書館長","answer":"つながりという面では、図書館と映画館であったり、図書館と水族館の立地条件を活かした連携であったりはこの間も進めてまいりました。地域の文化とか、地域資料などを通じた連携などを図っている事例もあるようなので、これまで以上に地域と共にできることを検討してまいります。","id":"exchange-148"},{"speaker":"高橋（し）委員","kind":"提案","question":"大崎のこども図書室は、小規模ながら大変人気があると伺っています。教育委員会として、ここの部分に子ども図書室を入れたいということは、どこかで主張できるというか、提案したりすることが可能なのか尋ねました。","respondent":"吉田品川図書館長","answer":"新庁舎におけるそういうスペースについてですけれども、区の施設、特に新しい施設については、いろいろな要望が各課からあると思います。そういうのをつけて、全体の総量を調整するなど、総合的な調整を図った上で判断されるものと考えております。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"今は企画課、財政課の方のご答弁のような気がして、教育委員会の図書館を担当している方として、こんなすばらしい図書館の活力あるいは能力というか、パワーがあるということを主張していただくと大変ありがたいのですが、もう一回そこのところをお願いします。","respondent":"吉田品川図書館長","answer":"確かにいろいろな意味で、最近は利用人数等も増えているところです。全体の調整の中では安心・安全が優先されたり、優先される事業もいろいろあると思いますので、全体を含めまして検討していければと考えています。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"あるいはまちづくり部のところで、かなりまちづくり部が主導権を握って、それで教育関係のところとペアを組んで設置していると伺っています。財政のほうではしごを外したのかとここでは見えてしまうのですが、その点について、どのような事情があったのか尋ねました。","respondent":"中谷指導課長","answer":"ですので、段階的にやるということを考えまして、２部活程度ということで進めて、各学校そのような規模で進めてまいりたいと思っています。様々あると思いますので、聴いて、丁寧に対応しながら進めてまいりたいと考えています。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、２部活とありましたけれども、３部活、４部活と希望が出てきたら、柔軟に対応してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-152"},{"speaker":"松本委員","kind":"質問","question":"私からは３７５ページ、平和に関する指導資料作成費、３７３ページ、修学旅行費、いじめ防止対策費について伺います。児童・生徒が関わるような非核平和都市宣言４０周年記念事業があるのか、そのようなものがあれば、お答えほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"教育委員会で予定している４０周年に合わせたイベントというものは、検討というか、予定はないのですけれども、毎年、広島平和使節派遣ということで行わせていただいていますが、そういったところで充実したものを続けていきたいと考えております。","id":"exchange-153"},{"speaker":"松本委員","kind":"質問・要望","question":"その事業を通して平和の尊さや大切さに対する認識を深めていくことを目的にということで、中学生は１５名派遣されているということだと思います。来年度４０周年ということもありますので、ぜひ今後検討してほしいと求めましたが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"中学生１５名が毎年広島に伺いまして、貴重な体験をしています。たまたま今、品川区立学校では京都・奈良が多くありますけれども、広島も一つの候補地にはなってくると考えております。","id":"exchange-154"},{"speaker":"松本委員","kind":"質問・要望","question":"次に、いじめ防止対策費について伺います。その上で、中身を拝見して、少し確認していきたいところもあるのですけれども、重大事態の対応フローも記載されています。","respondent":"丸谷教育総合支援センター長","answer":"学校で作成した様式３、こちらも区の対策委員会に渡して、それを踏まえながら調査を進めます。教員へのヒアリングも行いまして、そうしたものを含めて総合的に調査結果を出していくという流れになってあります。","id":"exchange-155"},{"speaker":"松本委員","kind":"確認","question":"そうすると、議会へも区様式４による報告があるということでいいのかというところを確認いたします。調査結果の公表とありますので、ホームページ上にも区様式４による公表が行われるという理解でよろしいでしょうか、お願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"品川区いじめ対策委員会の調査結果についてですけれども、様式４をかがみ文のような形で作成して、区長への報告を上げる形になっております。特に公表版につきましては、プライバシーのところを隠す作業もありますので…","id":"exchange-156"},{"speaker":"松本委員","kind":"質問","question":"現在、区のホームページ上には令和５年度のいじめによる重大事態の発生報告として、１０件が載っているということです。そのうち４件は調査終了と書かれていて、もうなされたという理解でよろしいでしょうか、お願いします。","respondent":"丸谷教育総合支援センター長","answer":"調査結果が出ましたら、速やかに保護者にはお送りし、区長報告も併せて行うような形になっておりまして、記載の４件につきましては、その手続を進めているところです。","id":"exchange-157"},{"speaker":"松本委員","kind":"質問・要望","question":"どうしても長く時間がかかり過ぎると、議論できないというところがありますので、できるだけここは迅速に行ってほしいと求めました。以上、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"私は３７５ページ、いじめ防止対策費についてお聞きしたいと思います。教育委員会制度は、首長から一定の独立性を持った機関が負うべきであり、今回の区長部局の対応についてどのようなご見解をお持ちか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"いじめへの対応につきましては、先ほども答弁させていただきましたけれども、一義的には学校、教育委員会が対応するものです。今回新しく窓口もできました区長部局とも連携をするケースも出てくるということでございまして、教育委員会が行っていくものと考えています。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"こういう場合は本当に迅速な対応が必要だと思いますが、これについて、教育委員会のご見解をお聞かせください。子どもたちの対応について説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"今、立っておりまして、今年度は気を引き締めて取り組んでいるところです。警察への相談につきましては、事案が立て続けに起こることで相談を行っていまして、それでもなお解決できなかった事案と考えております。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"これはどういうことですか。どういうわけか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"やはり監視カメラの設置ということになりますと、様々プライバシーの問題ですとか、保護者・生徒への理解というものも必要になってきます。当時はそういうことも考えながら、こういったカメラの設置であるとか、そういったカメラの設置についても検討していきたいと考えておりま…","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"学校ではないですか。でも、現実は違うではないか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そういった意味では、保護者、本人のお考え、要望に寄り添うことができなかったと考えております。カメラを設置するにしても、そういうことも当時検討されておりまして、あしたからできる対策は何なのかということで検討した結果。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、そんなことはできないではないですか。げた箱をずっと誰かが張っているのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"授業を妨害してしまう児童・生徒への対応についてですけれども、これまでも行ってまいりました。ただ、その児童・生徒を継続して授業に戻さないといった別室授業というのは適していないと考えておりまして、そういった声にしっかり耳を傾けながら。","id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"私が悪かったのです、一緒に皆さんと、これからは仲よくやって授業を受けますという世界ではないではないですか。当面落ち着くまでは別室で授業をして、ほかのお子さんに迷惑がかからないように対処するべきだと私は思いますが、もう一度説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"もちろん、落ち着いた授業を行うために、妨害する児童・生徒を別室で指導するということは大切だと考えております。そういったところを丁寧にケアしていく、そして授業に戻していく、そのプロセスは大事にしていきたいと考えています。","id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"どうすれば学校生活はよくなるのですか。その対策というのはお考えなのか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"荒れた後の対応を繰り返すのではなくて、そうならないような学校づくり、学校風土を醸成していくことが大事だと考えております。そういったことを今後しっかりと取り組んでいきたいと考えております。","id":"exchange-165"},{"speaker":"須貝委員","kind":"質問","question":"こんなことで本当にいい子どもたちを立派な社会に押していけるのですか。羽ばたかすようにできるのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-166"},{"speaker":"鈴木委員","kind":"質問","question":"私からは、３７２ページの教育指導費から、教員の働き方改革について伺いたいと思います。国の対策も含めて何が必要と考えるのか、伺いたいと思います。","respondent":"中谷指導課長","answer":"減らさないという取組につきましては、東京都がこれから作成をしていきます若手教員等とのコミュニケーションの手引、こちらが作成される予定です。教員の悩みに対応できるように、しっかり手引を基に活用し、実践できるようにしてまいりたいと思います。","id":"exchange-167"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、病休を取られている方に対しての補充ができていない欠員、それから産休・育休の補充ができていない人数も教えてほしいと求めました。これをぜひ増やしていただきたいと思うのですが、これを働き方改革のためにも増やしていただきたいと思うのですけれども、この点もいかがか尋ねました。","respondent":"中谷指導課長","answer":"病気休職、退職、産育休代替等の欠員は、義務教育学校を含めて小学校で２０名、中学校で３名、計２３名となっております。まず３０人を満たすためにという目標とともに、行く行くは各学校に１人配置できるようなシミュレーションで増員をしてまいりたいと考えています。","id":"exchange-168"},{"speaker":"大倉委員","kind":"質問・要望","question":"ページ３７９ページ、また小１プロブレムの解消の視点から、効果についてどのように捉えているか伺います。非常にいいのかなと思っているのですが、改めてその取組について、お考えを伺わせてください。","respondent":"中谷指導課長、吉田品川図書館長、丸谷教育総合支援センター長、森学校施設担当課長","answer":"５年度の２年間にわたりまして、八潮南保育園や八潮学園との連携・接続の取組を研究しまして、１２月に研究発表を行いました。次年度… 今後そのような機会がありましたら検討していくとともに、また、静かにしてくださいというところで中心にやってきたところも文化としています。… 弁護士のような専門性の高い講師による授業です。今年度も、弁護士をお呼びした授業は３校で実施しているという実績がありますので… 改築校におきましては、校歴室であったりとか…","id":"exchange-169"},{"speaker":"大倉委員","kind":"質問・要望","question":"市民科でしょうか、予算もつけながら実施をしてほしいと求めましたが、いかがでしょうか。タブレットについて伺いたいと思うのですが、ＧＩＧＡスクール構想の中で進んできて、一定の期間が過ぎてリースが切れるというところだと思います。","respondent":"丸谷教育総合支援センター長、柏木学務課長、中谷指導課長","answer":"地域の歴史文化学習ということで実践しているものがございまして、こちらは謝礼として、１回３,０００円の商品券をお渡ししているものです。… 令和２年度に最初に導入いたしまして、令和８年３月末で、今ある機器はリースアップするという状況です。ＩＣＴ支援員が… 連携の頻度というところを上げていく必要があるかなと考えています。そのためにも、研修会から顔の見える関係をというところで…","id":"exchange-170"},{"speaker":"大倉委員","kind":"意見","question":"リースが令和８年ということになると、今後どうしていくかというところでは、このままタブレットでいくのかなというところは理解しました。この子が少しいつもより体調が悪そうとかと分かれば、いろいろな人の目に触れると思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-171"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは３９５ページ、学校施設建設費、城南第二小学校、３７３ページ、修学旅行費について伺ってまいります。地元の皆さんから要望があって、学校側からの要望もあって、議会からも要望させていただきました。","respondent":"森学校施設担当課長","answer":"北側の道路の学校敷地側の４０ｃｍほど、ペイントをし直し、児童が歩きやすいように道路を改修しています。そのほか、教育委員会といたしましても、交通誘導員を北側に現在配置しておりまして、児童の通行の安全を確保しています。","id":"exchange-172"},{"speaker":"あくつ委員","kind":"確認","question":"今おっしゃったように、２倍ぐらい歩道部分を広げていただいて、車が突っ込めないような形に設置をしていただきました。もう１点加えまして、通学路の安全をご確認いただいたということですが、どのような確認をされたのか説明を求めました。","respondent":"森学校施設担当課長","answer":"教育委員会から道路課に情報提供して、確認をしていただきました。道路課で確認していただいたところ、安全対策を取るところは特にはないと聞いてあります。","id":"exchange-173"},{"speaker":"あくつ委員","kind":"提案","question":"２０１８年からベーシックサービス論を提唱されている、区内で直接数回、またオンラインでも数回にわたってお話を伺いました。先ほども、まずは来年度からの事業について検証していくというご答弁がありましたが、そのことについて伺いますとの意見を述べました。","respondent":"柏木学務課長","answer":"初めに、修学旅行費の平均ですが、中学校の平均でいきますと、１人当たり約６万円弱です。今後の修学旅行費の無償化の検討ですが、その上で修学旅行の無償化について検討する必要があれば、財源も含めて検討したいと考えています。","id":"exchange-174"},{"speaker":"あくつ委員","kind":"質問","question":"４週８休とか働き方改革適用になると思うのですけれども、品川区においてはこの４月の以前から、本規制が適用されるのかというところを伺います。受注者である事業者の申出があった場合、発注者である自治体が柔軟な対応を取る必要があると思いますが、発注者である教育委員会のご見解を伺います。","respondent":"森学校施設担当課長","answer":"今後につきましては、４週８休ができるように、様々対応を取っていきたいと考えております。丁寧に協議を重ねながら、そういうことがないように、区としてできることで対応していきたいと考えています。","id":"exchange-175"},{"speaker":"あくつ委員","kind":"確認","question":"国からの通知があったかどうかというのを確認させてください。","respondent":"森学校施設担当課長","answer":"国からもそのような通達が出ておりますので、それを踏まえまして、しっかり考えてまいります。","id":"exchange-176"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３７５ページ、いじめ防止対策費についてお伺いします。その原因というのは何と考えているのか、お知らせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"いじめの認知件数、出現率の増加の原因ですけれども、いじめそのものが増えているとは捉えておりませんで、各学校がいじめを見逃さず、適切に認知して対応している結果だと捉えております。","id":"exchange-177"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次に、プレス向け発表の資料では、根本的ないじめの未然防止に努めて、いじめを許さない学校風土を醸成と記されております。学校風土に関する調査費が計上されていると思うのですけれども、現段階で調査から分かったことがあったら教えてほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"今年度まで実施をしてまいったのは、義務教育学校７年生を対象に、その後の指導に活かしてきたところです。担任の実感と同じ傾向の結果となる場合もあれば、調査によって把握できることもあり、有効にこれまで活用してまいりました。","id":"exchange-178"},{"speaker":"高橋（伸）委員","kind":"確認","question":"そうしますと、来年度も、対象は７年生とおっしゃっていましたか、同じような内容でいくのかどうかというのを確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"来年度につきましては、学校風土調査ということで実施をしてまいります。学級に注目するのではなく、学校全体に注目をしていくものでして、これは１年生から９年生、全ての学年で年２回実施するものです。","id":"exchange-179"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望で収めさせてもらいます。そこで、来年度に向けて、品川の教育について、改めて来年度の教育についてお伺いしたいと思います。","respondent":"伊崎教育長","answer":"教育は家庭が第一義的に行い、学校がチームで、子どもたちを中心に据えて進めていきたいと考えております。ほかの関係機関や専門機関との連携を取りながら、一人一人の可能性を引き出すことのできる品川区の教育を進めていきたいと考えております。","id":"exchange-180"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6697#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":128194,"voices":409}},{"id":"r06-20240321-3","meetingId":"r06-c-budget","date":"2024年3月21日","dateIso":"2024-03-21","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時２０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を110件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"「Tokyo Tokyo Point（仮称）」について、東京都から都内自治体に対して何らかの情報は通知されているのでしょうか。このアプリを通じて区民が受ける利益は何かを教えてほしいと求めました。","respondent":"久保田企画部長、溝口防災まちづくり部長、阿部健康推進部長","answer":"現在、東京都において事業の仕組みを検討しているということであり、区への通知等は現時点では届いておりません。… 私からは、しなみちレポートの利用状況についてご説明します。令和３年度から施行いたしまして、令和４年度から、公園における陳情も併せて… 私からは、健康ポイント事業の令和５年度の実施状況についてお答え申し上げます。今年度ご参加いただいた方は改めて新しいアプリを入れて登録いただいたと…","id":"exchange-001"},{"speaker":"こしば委員","kind":"質問・要望","question":"でしなみちレポートは、相応の利益としてインセンティブを贈与する取組を検討いただきたいと考えますが、本区のお考えを教えてください。先ほど話しました「Tokyo Tokyo Point（仮称）」に、区民の利便性向上につながってくると考えますが、お考えを説明を求めました。","respondent":"久保田企画部長","answer":"地域活性化に資するデータ活用等も視野に入れて開発に取り組んでいく旨の答弁が東京都であったということを確認しています。その意味では、しなみちレポートや健康ポイントなど、区のオリジナルアプリと連携できる可能性はあると考えているところです。","id":"exchange-002"},{"speaker":"こしば委員","kind":"質問・要望","question":"その上で、ぜひ品川区の独自の要望を上げてもらいたいと考えますが、お考えをお願いいたします。これまでも、品川区独自のデジタル地域通貨を求める声もありました。","respondent":"久保田企画部長","answer":"東京都の予算特別委員会の中で、区市町村に対して来年度早期に連携や活用の方向性を含めた説明会を開催する、また。東京都やＧｏｖＴｅｃｈ東京の動向を注視しつつ、区民の利便性の向上や有効性等を勘案しながら、引き続き検討していきたいと考えているところです。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"続きまして、２番目、童謡・唱歌を通じた心の教育についてお伺いいたします。音楽の授業はもとより、様々な場面で童謡や唱歌が歌われる機会をつくり出していただきたいと考えますが、併せてお考えを説明を求めました。","respondent":"米田教育次長","answer":"愛着を持つことや、自然や四季の美しさを感じ取ること、国の文化や日本語の美しさを味わうことなどがあると認識しております。現在も生活科の学習で歌や手遊び、昔遊びを行う中や、体育科での伝承遊びの中で、音楽に触れた活動を実施しております。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問・要望","question":"そのきっかけづくりとして、区主催のリカレント教育を設けて、童謡を大人になってから学ぶ機会をつくるのも検討してみてはいかがでしょうか。併せてお考えを説明を求めました。","respondent":"廣田文化スポーツ振興部長","answer":"認知症の予防などに有効という見解もございまして、童謡に触れることは一定の効果が見込まれると言われていると認識しています。生涯学習等の講座の設定につきましては、今後、区民のニーズ等を確認しながら、その可能性については研究してまいります。","id":"exchange-005"},{"speaker":"こしば委員","kind":"質問","question":"例えば、学校行事、地域行事、地域のパトロールにも童謡を繰り返し流していく取組は、これまでにありましたでしょうか。なければ、ぜひ検討をお願いしたいと思いますが、お考えを説明を求めました。","respondent":"米田教育次長","answer":"市民科で実施している、そうした歌での交流活動を充実していくことも、共に学ぶ機会として重要なことであると認識しております。教育活動を効果的に実施していく上で、アプローチ方法は様々あるものと考えます。","id":"exchange-006"},{"speaker":"こしば委員","kind":"質問・要望","question":"そういう方のご意見もしっかりと傾聴する必要があると思いますが、どのようにアンケートを取っていくのでしょうか。そういう状況下でどのようにドッグラン設置に向けて進めていくのか、お伺いいたします。","respondent":"溝口防災まちづくり部長","answer":"公園利用者や周辺にお住まいの方の中には、ドッグランについて様々なご意見を持っているという認識を持っているところです。令和６年度に予算計上しておりますドッグラン設置検証では、利用者の方の声、ドッグランの設置に向けて検討していきたいと考えているところです。","id":"exchange-007"},{"speaker":"こしば委員","kind":"質問","question":"ご答弁のとおり、具体的に現在で区内のどの公園をドッグラン仮設の場所にしようと検討されているのか、教えてください。その公園以外の設置について、今後の展開についても併せて説明を求めました。","respondent":"溝口防災まちづくり部長","answer":"様々なご利用者、または近隣の方からのご意見等もありますので、そういったものを勘案しながら、設置に向けて検討していきたいと考えています。まずは現在、令和６年度から具体的に実施を進める取組を継続して実施して、今後の展開について検討していきたいと考えているところで…","id":"exchange-008"},{"speaker":"こしば委員","kind":"質問","question":"そのようなドッグランとなるために、区は、どのようなことが必要であって、またどのような点が重要であると考えますでしょうか。お伺いいたします。","respondent":"溝口防災まちづくり部長","answer":"は近隣の方から様々なご意見をお伺いしながら進めていくとともに、区の考えといったものもしっかり伝えていく必要があると考えているところです。設置だけでなく、マナー向上に向けた取組といったものを併せてやっていくことが重要と考えているところです。","id":"exchange-009"},{"speaker":"こしば委員","kind":"質問","question":"４つ目は、品川区シビックプライドについて伺います。ただ、最近では品川区歌をお聞きする機会はほとんどないのですが、そもそも品川区歌の意義は何か尋ねました。","respondent":"久保田企画部長","answer":"「品川区民の歌」は、委員からお話がありましたように、「品川音頭」と同じく昭和５３年に制定されたものであります。「品川区民の歌」が区民の方々に広く伝わっていないということは私どもも認識していますけれども、区民まつり等で広く親しまれており。","id":"exchange-010"},{"speaker":"こしば委員","kind":"質問","question":"今の区歌をこれからも続けていくのか、展開されていくのでしょうか。品川区の言わば公式の歌として展開することで、品川区の新たな誇りが生まれてくることを期待いたしますが、併せてお考えを説明を求めました。","respondent":"久保田企画部長","answer":"検討していく展開の中では、区民の歌の活用ということも、区民とのワークショップ等を通じて検討していきたいと考えているところです。こうした取組を進めていきまして、区民のシビックプライドの醸成に努めていきたいと考えているところです。","id":"exchange-011"},{"speaker":"こしば委員","kind":"質問","question":"その１つの選択肢として考えていただきたく、質問をさせていただきました。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"西村委員","kind":"質問・要望","question":"デフリンピック２０２５に向けて伺います。昨年１０月に行われたアイルしながわでの「デフスポーツ＆アートフェア」に私も伺いましたが、障害を持っている方たちへの理解について。","respondent":"廣田文化スポーツ振興部長","answer":"子どもたちとデフアスリートとの交流や、じかにデフスポーツに触れ合う機会としたいと考えて実施するものです。開催に当たりましては、集客が見込める文化イベントと同時に実施いたしまして、効果的に実施したいと考えております。","id":"exchange-013"},{"speaker":"西村委員","kind":"質問","question":"自治体連携をどのようにお考えでしょうか。子どもたちの交流、文化交流、観光地としてのおもてなし企画など、品川区らしい区への呼び込みをぜひ展開されたいと思いますが、ご見解を伺います。","respondent":"廣田文化スポーツ振興部長","answer":"デフリンピックの認知度１００％を目指すということはもちろんのことではありますけれども、認知度の向上に努めていきたいと考えております。スケジュール等について、今後も東京都や近隣自治体等から情報収集を行いまして…","id":"exchange-014"},{"speaker":"西村委員","kind":"質問・要望","question":"観光施策は、これまでの実績もありますので、品川区らしい施策を要望させてほしいと求めました。見解と取組を伺います。","respondent":"米田教育次長","answer":"一方で、学校を取り巻く環境が複雑化・多様化し、求められる役割が拡大していると認識しております。次年度はこうしたよりよい学校風土づくりにも努めてまいります。","id":"exchange-015"},{"speaker":"西村委員","kind":"質問・要望","question":"とはいえ、これほどに先生という職業が求められるのは、教育が人間を育てる基盤として重要だからであります。今、子育て中の親たちがどのようなことに悩んでいるのか、子ども家庭支援センターに届く声、相談内容としてどのような声が届いているかを伺います。","respondent":"柏原子ども未来部長","answer":"令和４年度に１１７件ございましたけれども、令和５年度は既に今、１５１件と、かなり増加傾向です。令和５年度は現在においてもう１１８件になってございまして、年度末に向けてはさらに多くなってくるだろうというところを見込んでいるものです。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"次年度の取組と、区の見解をお聞かせほしいと求めました。新しく始まるこの講座の目的と狙いをお伺いします。","respondent":"柏原子ども未来部長","answer":"子ども家庭支援センターで相談支援をしている家庭向けのプログラムは、つい、全６回のプログラムを実施する予定です。こちらは、きゅりあんなどの会場で実施する予定ですけれども、保育園などにも出張講座というのも検討しています。","id":"exchange-017"},{"speaker":"西村委員","kind":"質問・要望","question":"この講座の案内は、ぜひ不登校児童・生徒の保護者にも伝えて、様々に周知に取り組んでいただきたいと要望いたします。子ども家庭支援センターから保護者に連絡が行くようなアウトリーチの支援ができないか、親が自分の悩みを相談できる体制の整備を求めます。","respondent":"米田教育次長","answer":"ただ１つ同じ課題はなく、個々の課題の状況を整理・把握して対応に努めていく必要があり、家庭との連携は必要不可欠であると考えております。子ども家庭支援センターとの連携につきましても、個々の事例を勘案しながら検討してまいります。","id":"exchange-018"},{"speaker":"西村委員","kind":"質問・要望","question":"品川区立で自立を促す場所、都会にいてしんどくなってしまったのであれば、自然の中で過ごす機会を提供できないでしょうか。現在、登校が難しい児童・生徒や希望する家庭に対して検討してみるのはいかがか尋ねました。","respondent":"米田教育次長","answer":"子どもや保護者が考える、その実行については、保護者や本人の意向によって実施されるものであると認識しております。第６学年・第７学年で、それぞれ日光・磐梯での移動教室を実施しており、体験学習を実施したりしているところです。","id":"exchange-019"},{"speaker":"西村委員","kind":"質問・要望","question":"職員の働き方、区が住民に対して負っている役割を全うするための重要な基盤であることを改めてご認識いただきたいと思い、お伺いいたします。ハラスメントがあったとの訴えは何件ぐらい届いているのか、伺えればと思います。","respondent":"堀越総務部長","answer":"民間がこれも月当たり１人当たり１５.２時間になっていますので、区としてはやはり少し少ないという状況かと、全体状況としては思ってあります。調査して対応したものが６件で、いずれも相談対応をして、解決に向けて対応したものです。","id":"exchange-020"},{"speaker":"西村委員","kind":"質問・要望","question":"全庁的にアンケートを取ったと伺っておりますが、アンケートでどういう課のご意見が多かったのか、お話しいただける範囲でお願いしたいと思います。これは非常に重要なことであり、ガイドラインなどの策定を求めますが、いかがか尋ねました。","respondent":"堀越総務部長","answer":"いろいろなハラスメント対応や、コンプライアンス担当や法律的な対応も含めまして、区としての対策を検討していきたいと思ってあります。その中で、改めてガイドライン等の対応についても検討していきたいと考えているところです。","id":"exchange-021"},{"speaker":"西村委員","kind":"質問・要望","question":"最後に、これまでの歴史も踏まえまして、お伺いしたいと思います。これまでどういう思いでやってこられたのか、職員や品川区役所であるべきだと思っておられるのか、最後にお聞かせほしいと求めました。","respondent":"桑村副区長","answer":"１つは、何ですか、活性化するようなまちなのだと思います。それが、ぜひ実現して、すばらしい子育て施策、あるいはバランスのよい施策につながっていけばいいと思っているところです。","id":"exchange-022"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで、予算額についてお聞きし、今後の事業継続において、財源も含めて、区のお考えを伺います。０歳から２歳の第２子の保育費無償化と、０歳児おむつ宅配、学用品の無償化は、財源と今後の継続についての区のお考えを伺います。","respondent":"米田教育次長、柏原子ども未来部長、久保田企画部長","answer":"こちらの概要については、学校給食を実施している各区市町村が、その費用の２分の１を都が支援する事業となります。本区の学校給食無償化事業については… 令和５年１月から今年の１月まで、都区双方の部長級による検討会が３回ほど、協議の場として開催されてあります。… 最後に学用品の無償化につきましては、全て一般財源により事業を実施する予定です。事業実施に際しましては…","id":"exchange-023"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、居住支援法人と区との連携・協力を進めること、また居住支援法人が、より多く区内において指定されるよう、区の積極的な取組を要望します。見解を伺います。","respondent":"久保田企画部長、中村都市環境部長","answer":"人口を推計している最終年の令和４２年まで一貫して増加を続け、高齢者の人口は１４万５,０００人になる推計です。それから推計いたしますと、令和４２年時点で約５万６,０００人になり… 得意、ひとり親世帯の支援が得意だったりといった特徴や得意分野がありますので、それらを活かした効果的な連携と協力について検討してまいります。今後、居住支援法人としての可能性のある法人について…","id":"exchange-024"},{"speaker":"新妻委員","kind":"確認","question":"死亡等による退去まで、言うなれば高齢者丸ごと支援体制を構築する必要があると思いますが、いかがでしょうか。それぞれ伺います。","respondent":"中村都市環境部長、今井福祉部長","answer":"区としまして、法人等が入居中のサポートを行う賃貸住宅の促進は非常に大切だと考えております。経済力や一定の条件も必要だとは思いますけれども、今後、居住サポート住宅の認定に向けてしっかりと検討してまいります。 さらに組織改正に伴い、本年４月より住宅課に居住支援担当を新たに設置するなど、支援体制の拡充を図ってまいります。今後も区が主体となって、民間法人等とさらなる連携を図りながら、総合的・包括的な居住支援体制を構築してまいりま…","id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"自分らしく暮らしていくために必要な取組との問いでは、１位が子ども、２位が高齢者との結果となりました。高齢者の住宅の確保と支援を中心とした、区議会公明党は力強く要望いたしますが、見解を伺います。","respondent":"新井副区長","answer":"付させていただきました介護職員、介護の担い手に関する独自の処遇改善手当もそうですし、あるいは認知症の伴走型支援事業も２３区では初。ご指摘いただきました高齢者の住まいの支援、子育て施策の政策とともに、引き続き力強く打ち出してまいりたいと考えているところです。","id":"exchange-026"},{"speaker":"新妻委員","kind":"質問","question":"そして、現在、ケアマネジャーの研修や意見交換の場はどのように行われているのでしょうか。今後予定されていることを伺います。","respondent":"今井福祉部長","answer":"都道府県が実施主体となって、実務に就いた後も継続的に研修の機会を提供できますよう、今回の作成に至ったものと認識しております。研修の質の平準化を図るため、国として研修実施の指導者用のガイドラインを作成して、これを私ども品川区でも活かしてまいりたいと考えておりま…","id":"exchange-027"},{"speaker":"新妻委員","kind":"質問","question":"高齢者が、住み慣れた地域・我が家で暮らすなど、全ての要介護・要支援者が満足度の高いサービスを受けられる整備が重要であると考えます。そのための品川区版ケアマネジャーガイドラインの策定を含めた、ケアマネジャーの負担軽減や質の向上において、具体的な取組を伺います。","respondent":"今井福祉部長","answer":"ＩｏＴを活用したケアマネジメント向上支援事業を踏まえ、令和６年度は、ケアプラン自己点検ソフトを導入・活用していく予定です。令和６年度は、国が進めるＳＩＰ事業に向けた調査・検討も併せて行ってまいります。","id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"新年度の八潮まちづくり検討予算案は５７５万６,０００円、款別審査で委託費と確認いたしましたが、改めて詳細をお聞きします。継続的な開催で、八潮地域の特性を活かした八潮のまちづくりが進むよう要望いたしますが、今後の会議の予定を伺います。","respondent":"川島地域振興部長","answer":"熱供給システムの有効活用の可能性について探るため、東京熱供給株式会社とも連携して検討していきたいと考えております。庁内会議については、来年度は庁内検討会議を継続的に開催するとともに、八潮地区の特性を踏まえたまちづくりのコンセプト検討を進めてまいります。","id":"exchange-029"},{"speaker":"新妻委員","kind":"提案","question":"システムキッチンなどの整備、施設の出入口にベンチの設置などを提案いたしますが、見解を伺います。併せて想定容量をお聞かせいただき、設置することでどのような効果があるのか、伺いますとの意見を述べました。","respondent":"柏原子ども未来部長、川島地域振興部長、久保田企画部長","answer":"区における在宅子育て支援の新たな拠点としたいと考えてございまして、今お話しいただきました、積極的に取り組んでまいりたいと考えています。… 冒頭にご説明しました八潮まちづくりのコンセプト検討の中で、八潮地区の皆様のみならず、その使い分け等も含めて検討を進めてまいります。なお… 設置の効果といたしましては２つありまして、環境面では年間のＣＯ２削減量として、約３万平米の森林のＣＯ２吸収量とほぼ同じと想定しています。防災面で…","id":"exchange-030"},{"speaker":"新妻委員","kind":"質問・要望","question":"八潮地区内で環境への配慮が大きく前進し、ゼロカーボンシティしながわの実現へ向けて大きく寄与されます。区の指導の下、区と地域が一体となって、これからの八潮地区のまちづくり検討が進みますよう要望いたしまして、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"こんの副委員長","kind":"提案","question":"初めに、防災・減災対策のさらなる強化を求め、質問いたします。これまでの取組への評価と、新年度に予定されている事業、在宅避難の促進策として耐震改修費用助成の増額を提案しますとの意見を述べました。","respondent":"中村都市環境部長","answer":"令和６年度ですけれども、これまで２分の１でしたけれども、さらなる制度の周知を行いながら耐震化を進めていきたいと考えております。今後、工事費の状況や区民ニーズ等も踏まえ、しっかり検討していきたいと考えております。","id":"exchange-032"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"年度途中、事業予算が足りなくなった場合は補正を組むなど、積極的な事業展開を図ることを要望いたします。それぞれお答えください。","respondent":"中村都市環境部長","answer":"令和４年度と令和５年度、４００万円と増額してきておりましたけれども、また令和６年度は予算として１,３００万円増額したいと考えております。さらなる予算措置につきましては、予算の執行状況を確認しながら、区民のニーズや要望に応えられますように…","id":"exchange-033"},{"speaker":"こんの副委員長","kind":"質問","question":"そこでお聞きします。下水道管の耐震化の現状と課題について、プールの水を運搬する際の負担軽減策について、それぞれお答えください。","respondent":"溝口防災まちづくり部長、滝澤災害対策担当部長、米田教育次長","answer":"品川区においても一部、事業を受託して、事業を実施し、進めてきているところです。追加や変更された施設につきましても、その都度追加し… プールの水を一時的に地上の水槽にくみ出した後、バケツを使って必要な場所まで運搬するなどの方法を検討してまいりたいと考えています。今後も… 学校敷地内の排水管の耐震化ですが、現在、全ての学校において１系統以上の耐震化は完了しております。耐震化された便器数が学校ごとにばらつきがあり…","id":"exchange-034"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"既に改築された学校には設置されていると認識していますが、今後、改築される２０校においても、エレベーターの設置を要望いたします。エレベーター設置の現状と未改築校への設置のお考え、改築は可能な限り計画を早め、エレベーター設置校の拡充を要望します。","respondent":"米田教育次長","answer":"蓄電池、受水槽など設置することを行いまして、防災機能の強化に努めているところです。財政状況等も勘案しながら、今後については検討してまいりたいと考えています。","id":"exchange-035"},{"speaker":"こんの副委員長","kind":"質問","question":"障害福祉についてお尋ねします。展開する超短時間雇用促進事業について、目的と企業とのマッチング体制など今後の具体的な展開について、それぞれお答えください。","respondent":"今井福祉部長","answer":"令和６年度から超短時間雇用専任のコーディネーターを就労支援センターへ配置し、企業と障害のある人をつなぎ、サポートする体制を構築いたします。さらに、地域自立支援協議会就労支援部会やハローワーク等との連携を強化し、障害のある人の多様な働き方の実現を図ってまいりま…","id":"exchange-036"},{"speaker":"こんの副委員長","kind":"提案","question":"様々な障害や疾患のある方々を包摂できる社会の実現のため、誰一人取り残さないインクルーシブな雇用と労働の場であってほしいと思います。マッチング機能の充実を図るため、業務支援室に専任のコーディネーター配置を提案しますとの意見を述べました。","respondent":"堀越総務部長","answer":"業務支援室に集約する以外にも、各所属で直接配置ということも検討していきたいと考えています。今、障害者部門での雇用の事業と連携して行うようなマッチングも活用しながら、超短時間就労の場の拡充を図っていきたいと考えているところです。","id":"exchange-037"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"供給が追いついていない状況にあり、今後、早期健診の導入とともに支援体制の拡充が求められます。現在の支援体制の現状と課題について、可能な限り需要に対応できるよう、療育支援施設の拡充を要望します。","respondent":"今井福祉部長","answer":"児童発達支援センターは１か所ですが、小山台住宅跡地の２か所、合わせて３か所を区内で整備していく予定です。児童発達支援事業所は現在、児童発達支援が３年間で１００人以上の増、いずれもニーズ量は増加するものと見込んでおります。","id":"exchange-038"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"国が推進する５歳児健診の目的や経緯について、５歳児健診への見解と導入のお考えをお聞きするとともに、健診後のフォローアップ体制を求めます。それぞれお答えください。","respondent":"阿部品川区保健所長","answer":"２００５年４月に発達障害者支援法が施行されまして、この頃から５歳児健診の実施について専門家等からご意見が出たりしまして検討されてきたもの。出産後から就学前までの切れ目のない健康診査の実施体制を整備するということは…","id":"exchange-039"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"最後に、若者の支援対策についてお尋ねします。官民連携体制の在り方や運営など、今後の若者の支援対策の方向性について、それぞれお答えください。","respondent":"今井福祉部長","answer":"今年度実施した６つの支援団体へのヒアリングでは、区との連携を進める中で、支援する側の課題認識を伺うことができました。現在、既存の支援サービス利用者の中で孤独・孤立を感じ、生きづらさを抱えている対象者の方へのアプローチについて検討を進めてまいります。","id":"exchange-040"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"１人で抱え込み、インターネットで情報を入手できても不正確な情報もあり、気軽に相談できる環境づくりが求められます。若者の体や性に関する悩みについての現状と課題の認識、若者支援の必要性についてのご見解、いつでも気軽に相談できる体制や場の整備を要望します。","respondent":"柏原子ども未来部長","answer":"そうした面におきましては、若者に対しての支援が十分ではないという部分がございまして、課題もあるものと認識しています。何か不安を感じたときに気軽に簡単に相談できる仕組みは必要なものと考えてございまして、今後、検討を進めてまいりたいと考えています。","id":"exchange-041"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"例えば保健師など専門家による相談体制、また相談についてはＳＮＳやオンラインなども可能とする体制、こうしたことを要望したいと思います。これについてのご所見を伺いたいと思います。","respondent":"柏原子ども未来部長","answer":"検討に当たっての幾つか具体的なご提案を頂いたところです。ご提案内容も含めまして、他自治体の事例なども参考しながら、今後、検討を進めてまいりたいと考えています。","id":"exchange-042"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"若者支援とともに、ほかにも要望しました内容につきましても、どうぞ進めていただきますよう、よろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"山本委員","kind":"確認","question":"区内経済の活性化と物価高対策について伺います。ポイント還元の利用者が区民か区民でないかが確認できるのかどうか、確認できる場合は、事業者ごとにお教えください。","respondent":"川島地域振興部長","answer":"区民生活の下支えとともに区内経済の活性化を図ることを目的として、６月より開始予定としているものです。ＰａｙＰａｙ、楽天ペイの４者ということで、令和４年の秋に実施した事業と同様です。","id":"exchange-044"},{"speaker":"山本委員","kind":"質問・要望","question":"後ほどの話につながりますが、より有効で効果的な手段を検討していくことを要望いたします。利用店舗について、商品券と比較してお教えください。","respondent":"川島地域振興部長","answer":"それから、利用店舗数につきましては、本年６月の実施時の利用店舗数が８,０００店舗の見込みです。一方、プレミアム付区内共通商品券の利用対象店舗数は、品川区商店街連合会加盟店の約２,０００店舗です。","id":"exchange-045"},{"speaker":"山本委員","kind":"提案","question":"一般質問でもご提案し、具体的にデジタル地域通貨へのステップとしての導入をご提案いたしましたが、来年度。区のご意見を伺いますとの意見を述べました。","respondent":"川島地域振興部長","answer":"現在、東京都がスキームを検討している段階であり、具体的な制度設計やシステム構成というのはまだ示されていないような段階です。引き続き、東京都の施策の動向を注視しながら、今後の事業の実施方法、実施手法等を検討してまいりたいと考えています。","id":"exchange-046"},{"speaker":"山本委員","kind":"提案","question":"産業経済費で提案させていただいた東京ポイントの活用について、同志が増えたことを大変うれしく思い、改めて本件を進めるべきと考えています。昨年の一般質問のご答弁の際に説明を頂きましたが、「しなみちレポート」にもっと投稿を頂きたいとの考えはないか尋ねました。","respondent":"久保田企画部長","answer":"対象となる方々への直接的な働きかけなど、様々な方法により、多くの方に参加していただけるよう取り組んでいるところであります。東京都からこの事業の詳細な説明はありませんが、他の自治体での事例などを見ますと、事業の目的や特性に応じて検証する必要があると考えておりま…","id":"exchange-047"},{"speaker":"山本委員","kind":"質問・要望","question":"区から都へ、プロアクティブに動いていくことが重要だと考えますが、区のお考えを伺います。そのためには、区で活用したい施策を早めに考えていくことが必要であると考えますが、区の見解を伺います。","respondent":"久保田企画部長","answer":"来年度早期に区市町村に対して説明会を開催するなどの答弁がありましたので、こうした説明会等の機会を捉えまして、東京都の制度の詳細を把握し。他区の動向等を注視しつつ、区にとっての有効性やメリットを見極めながら、引き続き検討していきたいと考えております。","id":"exchange-048"},{"speaker":"山本委員","kind":"質問","question":"現場の各課にアイデアを募集し、さらに幅広い活用を促すのはいかがでしょうか。区のご見解を伺います。","respondent":"久保田企画部長","answer":"「Tokyo Tokyo Point（仮称）」の検討に当たりましては、各部課と連携しながら進めていきたいと考えているところであります。まだ具体的な都の方策が決まっておりませんので、区としましても現時点では…","id":"exchange-049"},{"speaker":"山本委員","kind":"質問・要望","question":"この１年で大きく動くと考えます。地域のデジタル化と、ポイントサービスを使った行政施策の効果最大化への取組を前に進めていただくことを要望し、私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"吉田副委員長","kind":"質問","question":"６、行われるとしたらどのような研修でしょうか。７、決裁する立場にとっては、ケーススタディー、事例検討のような研修も必要と考えますが、それは行われているのか尋ねました。","respondent":"堀越総務部長","answer":"先ほども少し申し上げましたが、係長１年目の職員を対象として、必要な文書事務等の基本的事項の習得を実施しているというものです。各職場でのいろいろな対応の課長を中心とした取組、ケースに応じた事務処理などに取り組んでおり、そのような形で研修を行っているところです。","id":"exchange-051"},{"speaker":"吉田副委員長","kind":"質問","question":"今起きている事態を把握された上でのご答弁でしょうか。その２点を伺います。","respondent":"堀越総務部長","answer":"今ご説明させていただきました。公務員としての基礎的な知識や、今行っていることに加えて様々検討しながら、強化も図っていきたいと思っているところです。","id":"exchange-052"},{"speaker":"吉田副委員長","kind":"質問","question":"基本的な研修は全て行われているということですが、ではなぜ今、私の周辺で起きているような、適切でない行政文書の発出が複数回あるのでしょうか。それにもかかわらず、生活者ネットワークの議員が簡単に指摘できるレベルのミスがどうして起こるのか伺います。","respondent":"堀越総務部長","answer":"今ご指摘いただきましたけれども、その部分につきまして、研修で徹底しているという部分があります。今お話しした、個別の事例についてもしっかり対応していくというのは考え方として持っておりますので、そのように対応していきたいと考えています。","id":"exchange-053"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"人事考課というのでしょうか、研修と併せて考えていただきたいと思うのですけれども、いかがでしょうか。研修の足りないところや、それから研修でできないのであればどういうことが必要か、もしお考えがあればその点についても伺いたいと思います。","respondent":"堀越総務部長","answer":"様々な課題として今日受け止めさせていただいて、研修の計画の中にも活かしていきたい、検討させていただきたいと思ってあります。その後の適切な対応、しっかり対応している職員が評価されるように、適切な対応をしていきたいと考えています。","id":"exchange-054"},{"speaker":"吉田副委員長","kind":"質問","question":"そういう文書の発出があるのはなぜでしょうかというのと、さっきも言いましたけれども本当に不思議なのは、複数の方の目を通っているはずなのです。少し何か気の緩みといいますか、そういうものがあるのではないかと思いますが、その点についてのご見解を伺いたいと思います。","respondent":"堀越総務部長","answer":"１００％完璧であると今こちらでお答えしているわけではなくて、様々検討をしていかなければならないと思っていますので、考え方としてはそのような考え方を持っているということで答弁させていただきたいと思います。","id":"exchange-055"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ミスのことと、それからミスが起きたということと、そのミスの修正を、そちらがミスしたのですけれども、こちらに求められているわけです。その点については、もう研修の段階ではないということか尋ねました。","respondent":"堀越総務部長","answer":"法令上の対応もそうですし、それと、そういった部分でのご説明をしっかりと丁寧にするということが必要だと思っています。それはしっかりと適切に、ある意味、厳格に厳正に対応していくという考えはしっかり持っております。","id":"exchange-056"},{"speaker":"吉田副委員長","kind":"質問","question":"今回の事例も、そういうことも研修の中に取り入れながら、さらに検証を深めていくという見解でよろしいでしょうか。接遇に関してもそういうことが起きておりますので、その点についても見解を伺います。","respondent":"堀越総務部長","answer":"そこのところも含めて、基本的には文書をしっかり読み込んで対応していくのが我々の役割ですので、しっかりそれに努めていきたいと考えています。チームとして対応するところが必要だと思いますので…","id":"exchange-057"},{"speaker":"吉田副委員長","kind":"質問","question":"それは研修の問題ではないとしたら、何か要因が考えられるか、ぜひ伺いたいと思います。これは本当に大変なことだと思います。","respondent":"堀越総務部長","answer":"それは厳に慎まなければならないことですので、先ほどお話ししたようなケーススタディー的なものも含めて対応していきたいと思ってあります。しっかり対応していかなくてはいけないという部分はありますので、それについてはしっかり対応して…","id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"に研修ということで伺いましたが、もしかしたら、私も質問をしながら研修だけでは解決できないかと考えています。その点については、ぜひご協力いただきたいのですけれども、その点についてご見解を伺います。","respondent":"堀越総務部長","answer":"所管でも説明はさせていただいているとは思います。個別の案件についてのお答えはなかなか難しいですので、区として対応していくということを、それはしっかりと対応させていただきたいと考えています。","id":"exchange-059"},{"speaker":"吉田副委員長","kind":"質問","question":"この後もこの問題について個別に対応していただけると考えてよろしいでしょうか。そのような区としての対応を、今後このケースについても適用していただけるかどうか、伺いたいと思います。","respondent":"堀越総務部長","answer":"今ここで確定的なお答えはなかなか難しいですが、区としての対応は、それに沿って対応していく。職場だけではなく、例えば法規部門やその他の部門の対応も含めて必要であれば、それは必要に応じて対応します。","id":"exchange-060"},{"speaker":"吉田副委員長","kind":"確認","question":"改めてその辺について、今後も皆さん全庁的に、所管の方だけでなく対話に乗っていただけると理解してよろしいでしょうか。しつこいようですが、最後にその確認だけ頂きたいと思います。","respondent":"堀越総務部長","answer":"繰り返しの答弁になって恐縮ですが、区として基本的な考え方につきましてはしっかりとして、窓口で対応する。それはしっかりとやっていきたいと思ってあります。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"公助が果たすべき役割は何でしょうか。伺います。","respondent":"滝澤災害対策担当部長","answer":"第２編、風水害など、様々な災害に対応できる平素の公助の施策を具体化しているところであります。これらの公助の役割を的確に実施すべく、区としてその体制整備に努めてまいります。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問","question":"今のご答弁ですと、今までのように、自助・共助を自己責任にしようというような答弁であったように思われます。先ほど公助は２％だったということですけれども、なかなか実際に命を助けるというところでは難しいところがあると思うのですが、いかがか尋ねました。","respondent":"滝澤災害対策担当部長","answer":"交通ネットワークやライフラインの強靱化対策などを実施することの重要性や、防災・減災の項目を立てて具体化した内容が、まさに公助の役割と考えています。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"不燃化特区で一番効果を上げている地区名と、どれだけ効果が上がっているのかを伺います。木造住宅の耐震化促進や、不燃化特区の助成制度を区内全域に拡大することを求めますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"そして、その中で建物の除却・建て替え等の助成支援を、今、行っているところです。相対的危険度が高い対象地域において重点的な取組を進めていくといった考えです。","id":"exchange-064"},{"speaker":"のだて委員","kind":"質問","question":"１１.６％も効果が上がっているということで、それならば、なぜ拡大しないのか。拡大すべきだと思いますが、改めて伺いたいと思います。","respondent":"中村都市環境部長","answer":"現在、耐震診断の助成については区内全域で実施しています。令和６年度予算の中では１０分の１０の助成として、こういったところで予算の承認をお願いできればと考えています。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問・要望","question":"上下水道の耐震化の進捗率、耐震化を進めていく上での課題、上下水道の耐震化を１００％にする計画があるのか。それぞれ伺います。","respondent":"溝口防災まちづくり部長","answer":"財源も含め、管理する東京都において、適切かつ計画的に進められているものと認識しています。具体的に１００％という形の計画はございませんが、対象施設や地区を重点化するなど、着実に耐震化について進められていると認識しています。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民の生活を守るために、一般会計から公費を投入し、促進することが求められています。東京都に上下水道の耐震化１００％の計画を立てること、それぞれ東京都に求めてほしいと求めましたが、いかがか尋ねました。","respondent":"溝口防災まちづくり部長","answer":"その際、下水道の管渠の被害率につきましては２８.７％から６.４％に、それぞれ改善してきているところです。引き続き、区といたしましては情報収集に努めるとともに、必要に応じて適切な対応といったものを行っていきたいと考えているところです。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"災害用トイレが足りているとなぜ言えるのか、発災４日目以降はどうなるのか、伺います。避難所と既存公園に、下水道直結型マンホールトイレを増やしてほしいと求めましたが、いかがか尋ねました。","respondent":"滝澤災害対策担当部長、米田教育次長、溝口防災まちづくり部長","answer":"国や都からの物資支援に効果的に対応すべく、トイレの排せつ物を含めた災害廃棄物の処理も実施できる体制を整えているところです。… 最近の改築校ではマンホールトイレの機能向上を図るべく、近くに水栓柱や防災井戸を設置し、便槽を下水道管に直結させて整備しているところです。… 私からは、既存公園に下水道直結型のマンホールトイレの設置についてお答えします。マンホールトイレ設置に当たっては…","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"だからこそ、下水道直結型マンホールトイレが大きな効果を発揮すると思いますが、いかがでしょうか。ぜひ増設していっていただきたいと思うのですが、いかがでしょう。","respondent":"米田教育次長、滝澤災害対策担当部長","answer":"学校ですけれども、品川区地域防災計画に基づく区民避難所としての機能を充実させる必要があると認識しているところです。引き続き、改築校を中心に整備を行ってまいります。 ４日目以降のトイレの充足についてですけれども、その後、くし形に進路を切り開くという非常に困難なオペレーションを実施しています。優先順位をつけて、しっかりと開設して…","id":"exchange-069"},{"speaker":"のだて委員","kind":"質問・要望","question":"ホテルの活用など進めていただいて、環境改善に努めて災害関連死をなくしていただきたいと、これも強く要望しておきたいと思います。国・自治体がその責任を果たすことを求めて、私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ジェンダー平等推進条例、それから介護の人材確保、地域包括支援センターの設置を求めて質問したいと思います。共産党が代表質問で求めたユースクリニックについて、区は検討すると答弁しましたが、ユースクリニックとは何か。","respondent":"堀越総務部長、柏原子ども未来部長","answer":"それから、Ｑ＆Ａなどもつくりまして、正確な条例の趣旨が伝わるように努めてまいりたいとあります。それから計画的な施策の推進などについても、これから取り組みまして、各施策に条例の考え方を活かしていきたいと考えているところで… いわゆるクリニックというところを銘打った、男性・女性ともに身近で気軽に相談ができる場といったものが必要ではないかという認識でいるところです。検討内容、相談体制はどういったものがいいのかというのを…","id":"exchange-071"},{"speaker":"鈴木委員","kind":"質問・要望","question":"特に、リプロダクティブ・ヘルス・ライツの具体化、その一つであるユースクリニック品川版を早急に具体化するよう求めて次の質問に移ります。国民健康保険と後期高齢者医療保険の保険料は、どちらも過去最大の値上げ額となるのか確認させてください。","respondent":"阿部健康推進部長、今井福祉部長","answer":"令和６年度は１１万１５６円、値上げ額は５,３１４円で、こちらは令和７年度には１１万２,５３５円となる見込みです。額だけを比較いたしますと、これまでの最高額ということになってあります。 第九期ということで２０２４年、予算で計上しています標準額の保険料については６,５００円でございまして、値上げ額は４００円となっております。その前の年が、値上げ額、増額が５００円でございまして…","id":"exchange-072"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国民健康保険制度が危機的状況だと、この中では述べていますが、５項目の見直しを要望しています。区民に関わる１から３項目までを読み上げて、ご説明ほしいと求めました。","respondent":"阿部健康推進部長","answer":"１人当たり医療費増による保険料増は、国民健康保険財政基盤の更なる強化及び国庫負担割合の引上げを実施することにより、制度の維持を図ること。３、軽減対象が現行の未就学児までという制限を撤廃すること、及び公費による軽減割合の拡大を実施すること。","id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は経年的に、改めてどれだけ国民健康保険料が値上げされ続けてきたのか、具体的に伺いたいと思います。年収３００万円と５００万円について、それぞれお答えほしいと求めました。","respondent":"阿部健康推進部長","answer":"年収３００万円と５００万円の場合の、２００９年度と２０１４年度、２０２４年度の保険料についてお答えいたします。比較では、２００９年度との比較では３３万４,８００円の増で約２.２倍、２０１４年度とでは１４万５,０２７円の増で約２.８倍の増です。","id":"exchange-074"},{"speaker":"鈴木委員","kind":"質問","question":"改めて、この保険料が妥当なのか、負担が重いとは考えないのか、伺いたいと思います。しかも所得の少ない人の国民健康保険が、加入保険によってその２倍もの差があるというのは是正が必要だと思うのですが、いかがか尋ねました。","respondent":"阿部健康推進部長","answer":"これまでご答弁しましたとおり、区としては、この保険料をお願いしています。根本的な問題につきましては、先ほど申し述べました構造的な課題というものがありますので、こちらの解決が非常に重要であると考えているところです。","id":"exchange-075"},{"speaker":"鈴木委員","kind":"質問・要望","question":"国民健康保険料の負担が重いというのは、全国知事会も市長会も区長会も、国費を１兆円入れるべきだ、国費を増やせと求めているではないですか。それなのに、負担が重いとは区は言えないというのはなぜなのか、改めて伺いたいと思います。","respondent":"阿部健康推進部長","answer":"その実現のための短期的・中期的な項目といたしまして、国民健康保険財政基盤の強化や、低所得者の負担軽減など、５つを要望しています。引き続き、東京都、国に対して要望してまいります。","id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これを戻して引き下げることを求めたいと思いますが、いかがでしょうか。それから、区としてすぐにできる、１８歳以下の子どもの国民健康保険料は無料化を求めます。","respondent":"阿部健康推進部長","answer":"子どもの保険料免除は国民健康保険制度のことであり、国・都に対して引き続き要望してまいります。これらの方に対して保険料無料化に必要な予算は約２億円と試算していますけれども、既に５割、約１億５,０００万円必要と試算しています。","id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この事態を区としてどう捉え、改善のために何ができると考えるか、伺います。人材登録・紹介の仕組みを区が行うとした場合、課題が何か、伺いたいと思います。","respondent":"今井福祉部長","answer":"このため、区におきましても介護福祉専門学校の運営支援などによる人材確保と定着支援のため、都とは別に独自の居住支援などの事業に取組を。今、こちらにも既に区内の事業者８０事業者ぐらいが登録している現状ですので、その状況を確認していきたいと考えています。","id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それから、ぜひ地域に設置してほしいと求めましたが、いかがでしょうか。どんな活動をしているのか、ホームページでかなり詳しく紹介されている、例えば世田谷区の状況など、ご覧になられているか伺いたいと思います。","respondent":"今井福祉部長","answer":"地域包括支援センターの仕事といたしまして、地域支援の総合相談、地域包括支援センター運営協議会などを実施し。それぞれの地域包括支援センターの運営協議会の中で、サブセンターなどと、地域包括支援センターの役割を十分果たしているという現状です。","id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問","question":"私は在宅介護支援センターにどれだけ配置されているかということで伺ったので、その数をお答えください。","respondent":"今井福祉部長","answer":"在宅介護支援センターにおける設置につきましては、今、手元に資料としては、全体の数値、保健師５人、社会福祉士２３人というのが、地域包括支援センター全体の数字ということでお答えします。","id":"exchange-080"},{"speaker":"鈴木委員","kind":"質問・要望","question":"実際は在宅介護支援センターでやっているわけですから、それを答えてくださいというのが私の質問でした。保健師や、そして社会福祉士をしっかりと配置していただいて、地域の質の向上のためにもぜひ進めていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-081"},{"speaker":"筒井委員","kind":"質問・要望","question":"事務事業評価について伺います。そこで、今回の事務事業評価による無駄削減の判断基準と評価の方法を改めてお教えください。","respondent":"久保田企画部長","answer":"事務事業評価についてですけれども、初めに評価の考え方等についてお答えいたします。有効性や効率性等の観点から、可能な限り定量的な数値実績に基づきまして、客観的に評価を行ったものであります。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問・要望","question":"区民向けに毎年度の事務事業評価のポイントを分かりやすく簡潔に説明する区民説明会を行うべきと考えますが、いかがでしょうか。所管である政策推進担当課などの人員増強、体制の強化を行うべきと考えますが、いかがか尋ねました。","respondent":"久保田企画部長","answer":"次に、住民説明会の開催についてですが、現在のところ、開催の予定はありません。人員体制の強化についてですが、現状の人員においてより効率的に実施できるよう、職員の負担軽減を図っていきたいと考えているところです。","id":"exchange-083"},{"speaker":"筒井委員","kind":"質問・要望","question":"なぜウェルビーイングという言葉に引かれたのか、使おうと思ったのかということも含めて、区政全般のことを簡潔に説明できる機会だと考えております。逆に負担ではなく、ぜひ説明会という形を取ってほしいと求めましたけれども、その辺りも一言ご答弁をよろしくお願い申し上げます。","respondent":"久保田企画部長","answer":"区民への説明につきましては、私どもは区ホームページ等で行っているところです。例えばプレス発表で区長が直接ご説明をする機会、この１年間、述べてこられたというところもあります。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問・要望","question":"そこで、まず本区での官製談合防止の現状の対策はどうなっておりますでしょうか。本区も新庁舎等の大規模建設が控えていることに鑑み、より一層の官製談合防止の取組強化に当たるべきと考えますが、いかがか尋ねました。","respondent":"堀越総務部長","answer":"それから、今、例に出されましたような団体はないと認識しておりますが、引き続き、防止に努めてまいります。職員の守秘義務等の倫理意識の向上、研修、それから契約情報の適正な管理などをしっかりと引き続き徹底してまいりたいと考えているところです。","id":"exchange-085"},{"speaker":"筒井委員","kind":"質問・要望","question":"新庁舎の建設費用は約５６０億円とされておりますが、起債をした上で、なお幾ら分ぐらい不足していると見込んでおりますでしょうか。この不足分を補うために、現庁舎跡地の活用というのは収益性の高い施設建設におのずから絞り込まれると考えますが、いかがか尋ねました。","respondent":"遠藤財政課長、多並広町事業担当部長","answer":"そうしますと、７５％という形になりますので、約３３８億円というのが起債の額になります。先ほどの３３８億円を加えますと、建設費の４５０億円を超える形になりますので、現状の推計では不足は生じないという形になっております。 庁舎跡地等活用検討委員会で区民ニーズの把握に努めているところであり、具体の施設に絞り込むなどしながら検討を進めているものではございません。今後も検討の進捗に合わせて、対話型市場調査など行いながら…","id":"exchange-086"},{"speaker":"筒井委員","kind":"質問・要望","question":"比較して約３年近くのタイムラグは、大井町駅周辺地域のにぎわいづくりなどに悪影響が出ないかと危惧しておりますが、ご見解はいかがでしょうか。大井町駅周辺地域まちづくり全体や広町地区以外の地区の再開発に対する影響は、いかがお考えか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"大井町駅周辺まちづくり方針では、まちづくりの機運の高まりに合わせて段階的なまちづくりを進めていくこととしております。区の中心核として業務商業機能が充実し、楽しく安全に暮らすことができるまちとなるように、地域の方々と段階的にまちづくりを進めてまいります。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問・要望","question":"東京都の品川駅・田町駅周辺まちづくりガイドライン２０２０と、これは具体的にどのようなものなのでしょうか。すなわち有機的に人と人がつながる人的交流、にぎわいづくりが必要かと思いますが、いかがか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"ベイエリア全域を対象とした「東京ベイｅＳＧまちづくり戦略２０２２」、広域連携を図りながらまちづくりを進めるものと認識しております。民間開発と連携し、開発の動向により、にぎわいの観点も含めて検討されていくものと認識しております。","id":"exchange-088"},{"speaker":"筒井委員","kind":"質問・要望","question":"もう少し重要な拠点として格上げして扱っていただくよう、都に要望していただきたいのですが、いかがでしょうか。水辺拠点としての天王洲運河、天王洲アイル地域との連携も必要かと思いますが、いかがお考えか尋ねました。","respondent":"有江都市整備推進担当部長","answer":"区としましては引き続き、地元の再開発準備組合や都や関係者との意見交換を適宜行い、情報共有を図り、連携を図ってまいりたいと考えています。地域の再開発準備組合などと検討を進めておりまして、地域の皆様や関係機関と連携し、まちづくりを進めてまいります。","id":"exchange-089"},{"speaker":"筒井委員","kind":"質問","question":"既に乗換えできる駅があり、新駅誘致はこうした地域活性化効果がある地域でないと意味があまりないと考えますが、いかがでしょうか。新駅誘致の考え方を伺います。","respondent":"中村都市環境部長","answer":"新駅の場所や設置そのものについても確定した情報はありませんけれども、今後、区としまして。そんな中で取組状況につきまして、適時適切に議会にも今後また説明・報告させていただきたいと考えております。","id":"exchange-090"},{"speaker":"筒井委員","kind":"質問","question":"どうもありがとうあります。以上で私の質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-091"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、新しい新井副区長、今回の予算の特徴、そして力を入れたこと、それとお子さんの子育ての支援と高齢者の支援のバランスを改めてお伺いします。でも、２３区から選出している東京都議会議員とは、そういうお話をきちんとしているのか尋ねました。","respondent":"桑村副区長、新井副区長","answer":"つまり本当に役割分担の変更なのかというのが、一番の財調割合を変えるときの議論になっているところであります。当然、役割分担の変更があるはずだという主張をしているわけですけれども… 既にこの間の委員会の中でご説明申し上げてきたところではありますが、やはり一番大きなところとしては、予算の考え方ですね。ＥＢＰＭの視点から実証的な数字に基づいて、区民の皆様…","id":"exchange-092"},{"speaker":"藤原委員","kind":"提案","question":"いろいろ要望や提案などあると思うのですけれども、執行部としてどういうふうに、行政に執行していってくれるのかという思い。議員が各それぞれ、いろいろな要望、提案、質問をしていくわけですから、その辺の思いを教えていただきたいのが１点との意見を述べました。","respondent":"森澤区長","answer":"今後、執行、様々施策を展開していきたいと考えています。そして２点目、品川区を、職員と共につくってまいりたいと考えています。","id":"exchange-093"},{"speaker":"藤原委員","kind":"質問・要望","question":"これでふわっと終わりたいのですけれども、最後に私ですから、介護についてお伺いします。この改善も、ぜひこれからしていってほしいと求めましたが、いかがか尋ねました。","respondent":"今井福祉部長","answer":"分かりやすく事業者様に活用していただけるように、国や都、そして区の制度については説明させていただきたいと考えています。国からも周知されておりますので、様々な現場でもできる改善例も含めて、事業者様の声を聞きながら対応していきたいと考えています。","id":"exchange-094"},{"speaker":"せらく委員","kind":"確認","question":"そこで、ホームページ上に公開されている令和６年４月からの入園状況（指数）を確認しました。今回の令和６年度４月入園の１歳児クラスの応募において、１次募集、２次募集、それぞれ不承諾数とその割合を伺います。","respondent":"柏原子ども未来部長","answer":"区では２年連続で待機児童対策の結果、令和６年度においても、現時点においては待機児童ゼロを見込んでいるところです。最終結果について現在、集計中でございまして、手元に数字がないといった状況です。","id":"exchange-095"},{"speaker":"せらく委員","kind":"質問","question":"この緊急１歳児受入れ事業費補助金を使うなどして、１歳児の受入れについて、現行の２園から拡大するなどの検討はしたことがありますでしょうか。伺います。","respondent":"柏原子ども未来部長","answer":"都の緊急１歳児受入事業補助金の事業ですけれども、その検討状況というところでございましたが、その活用の検討というのは行ってございません。令和６年度におきましても、引き続き、空きのある保育園を活用した定期保育利用事業を引き続き実施してまいりたいです。","id":"exchange-096"},{"speaker":"せらく委員","kind":"提案","question":"款別審査で伺ったところ、すまいるスクール登録者の４割ぐらいが、このＢ登録とＣ登録ということです。２人以上の子育てで、対象範囲を広げてはという提案について、いかがか尋ねました。","respondent":"柏原子ども未来部長","answer":"１例を申し上げますと、結果的にそういった状況から、上のお子さんも退園せざるを得ないといった事態になりかねないというところでございました。この兄弟加点について、加点の要件を広げていくといったところがありますと…","id":"exchange-097"},{"speaker":"せらく委員","kind":"提案","question":"小学校３年生まで兄弟の加点を対象としていることを調べましたので、２３区ではなかなか園児を対象としている、ご提案させていただきました。巡回支援でも併せて確認していると伺いましたが、指導検査、巡回支援は事前に連絡をして行っているのか尋ねました。","respondent":"柏原子ども未来部長","answer":"指導検査の実施は年１回、事前通告の上、職員が訪問して検査を行うというところになってあります。指導検査や巡回支援の中で、年に五、六回は行っているという状況になってあります。","id":"exchange-098"},{"speaker":"せらく委員","kind":"質問・要望","question":"つる委員が委員会で質問をされていたのを確認しておりまして、一部の学校では早めにお預かりしている事例があると、議事録から確認いたしました。ニーズの部分では、保育園に登園する時間が８時より前の園児はどれぐらいいるか、事前に現状について伺っておりましたが、いかがか尋ねました。","respondent":"米田教育次長、柏原子ども未来部長","answer":"朝のスポーツ健康タイムを始業前の７時５０分から８時１０分まで毎日実施しており、大学生が有償ボランティアで子どもたちと一緒に活動しております。このような工夫をしている学校もあるということを現状認識しているところです。 これは区立保育園のみの数字ですけれども、令和６年２月の１か月の間で一度でも８時前に登園などした児童数の実数ですが、１,０９９人。在園児が４,０４２人おりますので、およそ４分の１がその数というところになります。","id":"exchange-099"},{"speaker":"せらく委員","kind":"質問・要望","question":"年齢制限なく支援をしていってほしいと求めましたが、思いを伺えればと思います。見解を伺います。","respondent":"柏原子ども未来部長","answer":"参加者の自己肯定感の向上や、将来の夢や目標につながる体験の趣旨で実施しているものですけれども、今後も支援を続けていきたいと考えています。区内ＮＰＯとの連携等も、児童センターでの講座内容も様々考えられますので…","id":"exchange-100"},{"speaker":"せらく委員","kind":"質問","question":"併せて、メタバース空間の利用対象を伺います。高校生や大学生は対象に含まれていますか尋ねました。","respondent":"米田教育次長","answer":"先行実施している８自治体の事例では、児童・生徒がトラブルに遭ったという報告はなく、問題なく実施できていると認識しております。今回、教育委員会が実施するメタバース空間を活用した不登校支援については、高校生や大学生は含まれてはおりません。","id":"exchange-101"},{"speaker":"せらく委員","kind":"質問","question":"子ども若者フリースペースに行けない人、人と会えない場合や昼夜逆転という場合には、どのようなコミュニティやつながりがありますでしょうか。ひきこもりの子ども・若者へのオンライン支援について、子ども未来部のご見解をお願いいたします。","respondent":"柏原子ども未来部長","answer":"今、委員にご指摘いただきました、オンラインでのつながりの部分ですけれども、そういったアプローチにつきましては重要な手法だと認識しています。なかなか現在、教育委員会で実施しているメタバースを活用した事業といったことの連携や…","id":"exchange-102"},{"speaker":"せらく委員","kind":"質問","question":"今、分かる範囲で、１年度のワンルーム集合住宅と２ＬＤＫ以上の集合住宅の戸数をそれぞれ伺います。持ち主がいる場合は持ち主で制度の紹介をしたり、不動産会社への紹介も可能だと思いますが、ご見解を伺います。","respondent":"中村都市環境部長","answer":"様々な情報や、また、今ご紹介いただきました東京子どもすくすく住宅認定制度といったものの積極的な紹介に努めていきたいと考えております。その働きかけの際に、こういった東京子どもすくすく住宅認定制度の紹介、またその活用について促してまいります。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"修正案に盛り込んだ事業は２２事業で、予算の使い方を暮らし・福祉優先に切り替えれば、多くの区民要望を実現することができます。ご審査、。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"},{"speaker":"高橋（伸）委員","kind":"提案","question":"私たちの要望の多くが反映された予算案、商店街支援など、委員会質疑を行いました。予算審査で各議員が行った提案・提言が十分に事業執行に反映され、さらなる区民福祉の向上が図られることを望み、意見表明としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"議会質問や緊急要望を通じ、福祉や教育など、人間として必要なサービスを誰もが享受できるベーシックなサービスの実現に努めてきました。本委員会での会派からの意見・要望を真摯に受け止められ、今後の区政へ活かされるよう要望し、意見表明とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"大倉委員","kind":"提案","question":"当会派からの政策要望を取り入れ、変化の激しい時代のニーズを捉え、柔軟に対応した積極予算としたことを評価いたします。今後も、今回の予算特別委員会において当会派所属議員が質問の中で指摘・提案した各項目を真摯に受け止め、予算を執行することを要望いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"},{"speaker":"安藤委員","kind":"提案","question":"日本共産党は品川区に対し、今回の前進面をさらに進めて、２３区最低の福祉の改善へ転換することを求めます。各種がん検診の無料化、各種提案をこれからの施策に活かしていただきますようお願い申し上げまして、日本共産党品川区議団の態度表明を終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-108"},{"speaker":"須貝委員","kind":"質問・要望","question":"社会の急速な変化により学校教育は様々な問題が起きているので、教育委員会は区長と共に子どもたちを守っていただきたい。最後に、悲惨なウクライナ侵攻や中東紛争などを人類は止めるべきです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"松本委員","kind":"提案","question":"なぜ、１つには、森澤区長が組織・団体支援を受けていないということが挙げられるのではないかと思います。区におかれましては、当会派各委員の質疑の中で指摘・提案した点について検討され、予算執行や今後の施策に反映していただくよう要望しとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6699#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":116182,"voices":261}},{"id":"r06-20240326-10","meetingId":"r06-cm03","date":"2024年3月26日","dateIso":"2024-03-26","committee":"議会運営委員会","time":"午前１０時３０分～午後 ０時１３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"令和６年第１回定例会","agenda":"令和６年第１回定例会","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと人権擁護委員なのですが、区長がこちらの方を推薦する理由をもう少し伺いたいと思います。どんなお仕事をしておられたのか、職歴と推薦との関わりなどがあるのかなどを含めて伺います。","respondent":"森澤区長","answer":"１点目の副区長ですけれども、次期副区長として選任同意いただければというところですが、というふうに考えております。女性の人権や子どもの人権、学校における人権教室等で力を発揮していただけるのではないかというふうに考えているところであります。","id":"exchange-001"}]},{"id":"topic-02","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"西村委員","kind":"質問","question":"ご説明、ありがとうあります。そのスケジュール感を伺っておきたいと思うのですが、その他中高生の目にも触れること、やはりふさわしくないなというふうに思っております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"山本委員","kind":"確認","question":"１点目が、広報会議内で、及びそのまま掲載してほしいということであればその理由をどういうふうにコメントされていらっしゃるのかということです。何かご検討されていらっしゃるのかどうか、これは大丈夫ですよとか、そういったところについてお考えがあるのかどうかちょっと確認させてください。","respondent":"大澤区議会事務局長、せお議員","answer":"事務的なところで、私のほうからお答えします。原稿の締切りですけれども、４月の上旬が最終稿ですので、できましたら今週中には原稿は固めていきたいというふうに考えているところです。 やなぎさわ議員の対応というところですけれども、やなぎさわ議員とは接触できなかったということもあります。今回区議会はどう考えているのかというところを示すためにも、皆さん一致している、私はそういう理解です。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"やなぎさわ議員から出てきている事実の確認の仕方が、必ずしも客観性を持っているものではないというところです。それは正確かどうか、今の段階では確認ができないということと、自粛を求めるという広報会議の考えに賛同します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"こんの委員","kind":"確認","question":"せおリーダーからのご説明も伺って、やはり事実が確認できないということ、生徒の溝を深めてしまう危険性もはらんでいるという感じもいたします。そうあるべきではないというふうに思いますので、大変に慎重にしなければいけないと思いますので、これはぜひ削除をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちも予算特別委員会で、会派としての質問で学校名を出しているものなので、そこが出ることは事実なのではないかというふうに思っているのです。もう学校名は出さないでくださいということが必要だったのではないかなというふうに思うので、どうなのかなというところがちょっとあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"須貝委員","kind":"確認","question":"事実確認をきちんとやったなら、どうなのかなという微妙なところはあるのですが、今回は学校名を出しましたよね。出していいのかどうかということもあるけれども、いろいろな影響を考えると、広報会議の見解が正しいのではないかというふうに私は思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"安藤委員","kind":"提案","question":"そこら辺の提案がちょっと分からなかったので、教えていただきたいというか、ちょっと具体的にお話しいただけますか尋ねました。","respondent":"せお議員","answer":"広報会議の正副においても、監視カメラを防犯カメラにしたとしても、この文章全体が事実かどうか分からないので、もう全文削除したいというところから、広報会議の委員の皆様にご相談したところでありますので、まずその前提で進めています。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"その部分を全部削除という提案というか、その相談ということなのですか。あるいは、そういった形でできる限りやなぎさわ議員が行った質問を削除しない方向で、最後までぎりぎり努力をしていただければと私は思っていますとの意見を述べました。","respondent":"あくつ副議長、せお議員","answer":"今多分共通認識として、私は見ましたけれども、実際どういうことをおっしゃっているのか。読み上げてもらえれば… 質問が、品川翔英高校（小野学園）で、録画機能が備わっている監視カメラが更衣室などに設置された。子どもへの人権侵犯について… 今のお話だと、録画機能が備わっている監視カメラが更衣室などに設置されたという断定の文章になっているということでよろしいでしょうか。","id":"exchange-009"},{"speaker":"安藤委員","kind":"提案","question":"〔資料配付〕 右上に日本共産党品川区議団提案となっておりますけれども、３月８日には第１次案というのを各会派、検討をお願いしました。改めて案文を読み上げて、提案させてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"こしば委員","kind":"提案","question":"その報道の内容についても、新聞赤旗の折り込みで声明を出した内容を伝えただけであって、事実の確認を踏まえたものではないと認識しております。事実のみを記述すべきではないかというところで、検討しまして、提案させていただきましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"こしば委員","kind":"意見","question":"こういった指摘を踏まえた上で、改めてこの文言が必ずしも、本来の事実に沿っているとは私には思えないので、そこは修正するのが本来必要な判断ではないかと思いまして、あえて指摘をさせていただいた次第ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"安藤委員","kind":"意見","question":"１つだけ、表現を変えるのはやぶさかではないので、もっと事実に即した書き方ができないかというご指摘だと受け止めました。新聞社の責任でちゃんと取材もして、報道されているということなので、そんなに問題ではないのかなとは思っていますとの意見を述べました。","respondent":"あくつ副議長","answer":"いやしくも１人の議員に対して、その身分を、まずこれをまとめていただいた共産党と須貝委員の努力とご尽力には敬意を表したいと僕は思うのです。そういった意味で、先ほどこしば委員がおっしゃったのはそういう意味だと思いますので、受け止めていただければと思います。","id":"exchange-013"},{"speaker":"須貝委員","kind":"確認","question":"本人に直に確認しているのですから、それを何で今になって、事実と違うのではないのですかとか、疑わしいとか、そういうことは言ってほしくない。事実ということを議長も確認しているわけですから、区民が見ているのですから、明確に態度表明をきちっとやるべきではないか尋ねました。","respondent":"あくつ副議長","answer":"別に否定するものではありませんということであって、須貝委員のご尽力、ご努力には敬意を表しますということを申し上げました。早く、早くというだけでは物事は進まないと思います。","id":"exchange-014"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"案文もそうですし、発言をしっかり聞いてご確認されたほうがいいと思いますが、それこそ２月に事実確認しましたということがここにも書いてある。そこからスタートしましたというふうに書いたほうがいいのではないですかというお話をしているだけで、中塚氏が行為をしていない、そこは訂正します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"３段落目からですか、２月８日の本人の意見聴取での、我々がその被害者から直接聞いたかのようにも読み取れてしまうところがあるのです。そこはあくまで日本共産党品川区議団からの話として伺っているということ、ご検討いただければ、お願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"西村委員","kind":"質問・要望","question":"２点気になっておりまして、議会の対応の過程を簡潔に、もう少し丁寧に記述していただいてはいかがかというふうに思います。事実確認のために日本共産党品川区議団の皆さんと中塚議員双方に説明を求める声が上がって、聴取・質疑を行ったこと、また。","respondent":"あくつ副議長","answer":"どうしても２次被害を防ぐという意味で、多分我々議会運営委員会としての考えだと思うので、そこについてもぜひ記載があればと思っています。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"以上の理由により、中塚議員自身がセクハラ行為の責任を自覚し、自らの意思で辞職するように求めるということではないかと考えます。いかがか尋ねました。","respondent":"あくつ副議長、大澤区議会事務局長","answer":"私もそのとおりだと思うのですけれども、ジェンダー条例はまだ成立していない、明日成立の見込みだと思うのですけれども、それを根拠にすることが、事務局としては、何か問題がある感じがありますか、それはこちらの判断でいいのか。 総務委員会で討論していたという事実がありますので、そこの部分は特に問題ないと考えています。","id":"exchange-018"},{"speaker":"せりざわ委員","kind":"確認","question":"確認されていると思うので、聞かれた場合に議会としてどういうふうに確認を取ったのですかというときに、提出された方も確認を取っていないですというのでいいのでしょうかという確認。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤委員","kind":"意見","question":"議会運営委員会、辞職勧告決議を出すに当たって必要な追加資料というか、材料ということで提供したつもりではあります。聞き取ったことはもちろん事実ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"せりざわ委員","kind":"確認","question":"そのとおりだと思うのです。区民の方からその方々にどういう形で確認を取ったのですかと問合せがあったときに、いや、議会としていいのでしょうかというお話です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"須貝委員","kind":"確認","question":"中塚議員とお会いしたときに、本人にこれは事実ですかとちゃんと確認して、本人がそのとおりですというふうに明確におっしゃった。我々もそれでは引き下がりますという話ですけれども、本人が明確に認めたということが、そもそも今回文面になっていると思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"せりざわ委員","kind":"確認","question":"ただ、被害者の心情とか、被害者がやめてほしいと言っているというところは、どうやって確認したのでしょうか。それを確認されていないのであれば、大丈夫なのですかという確認を今しているところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"もうそのとおりですと、そういう批判を一切本人がされないのだったら、それ以上我々もやりようがないではないですか。信じないはまたあれで、あくまで本人がそう証言されているなら、それを事実として私は受け止めました。","respondent":"あくつ副議長","answer":"そこのところで我々が言えるとするならば、内容について我々は確認できないけれども、彼がセクハラの事実を認めた。被害者の心情を考えると、申し訳ないですけれども、受け止めていただきたいということです。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"だけれども、聞けないではないですか。私は痴漢を受けました、こういうことをされました、こうなのです、区議会として相手に対する思いやり、配慮というのは最大限すべきではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"確認","question":"今後にも関わることですから、オール議会という形で進める案件だと思っていると、２月１９日の議会運営委員会で議長にもおっしゃっていただきました。そこら辺、ちょっとご意見をいただけたら、確認させていただけたらなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"せりざわ委員","kind":"意見","question":"当たり前ですけれども、書面を見ないとやれる、やれないはさすがに言えないです。これから中身を変えるというふうにおっしゃっている中で、賛成しますという話は、我々としてはなかなかできないということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"それは安藤委員に骨を折ってもらって、それもできるだけ早く打合せをして、皆さんの賛同を得られるような文面に仕上げていただきたいと私は思います。今回遅れたことに関しては申し訳なかったというのは、反省しています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6653#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":30155,"voices":115}},{"id":"r06-20240415-10","meetingId":"r06-cm04","date":"2024年4月15日","dateIso":"2024-04-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"西村委員","kind":"提案","question":"防災訓練の在り方や、ペット同行避難、地域防災をご提案させていただきました。環境対策は、プラスチックの削減や、カーボンニュートラルの実現に向けてということで、改めてご提案していますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"こんの委員","kind":"提案","question":"行財政改革特別委員会、災害対策特別委員会、ＳＤＧｓ推進特別委員会、そして、地域共生社会特別委員会という４つの提案をしています。なお、これまで例年２つで来ておりますので、その中でという形になるのだろうと思いますが、一応、４つの提案をしていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"それから、今回新たに入れていただきたいと思っているのが「ＳＤＧｓに関すること」です。今年度、様々な角度でＳＤＧｓに関するテーマを取り扱っていくということがふさわしいのではないかと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"人権、教育など、様々な分野にわたるジェンダー平等推進施策をさらに推進していくために設置する必要があるのではないかということで提案しました。４つ全てが必要だという立場で提案しているわけですが、全員参加が必要な４つ…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"したがって、特別委員会を設置する必要はないのではないか。我が会派としては、特別委員会を設置することには反対で、各常任委員会でしっかり議論するべき重要なことではないかと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"西村委員","kind":"提案","question":"私どもからご提案させていただいた２つではありますが、あまり多過ぎず、しっかり密に議論するためにも２つでいいのではないかと考えています。ＳＤＧｓとなると、私どもからの提案で申し訳ないのですが…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"こんの委員","kind":"提案","question":"ご提案があったお話で、行財政改革、あるいは災害・環境といったところはまとめられるのかなという思いがいたします。今、ご提案のあった行財政改革特別委員会、災害・環境対策特別委員会というまとめ方でもよろしいのかなと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"山本委員","kind":"質問・要望","question":"災害・環境対策に対して、行財政改革との関連性もあるかなと思いますので、どちらかの中でしっかり議論していただきたいというのが要望としています。名称のところは特にこだわりません。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"安藤委員","kind":"提案","question":"例えば、議員も４０人いるわけですから、必要なものにはちゃんと設置していくべきと思っています。ぜひ３つはどうかなというのを、皆様のご意見をほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"皆様のご意見をいただいた上で、３つはどうですかと投げかけているので、１回目はそうでしたけれども、２回目の意見を出してもらったほうがいいのではないかなと思うのですが、その上でまとめていただきたいということが１つです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"山本委員","kind":"意見","question":"委員会の数ですけれども、繰り返しになりますが、２つがふさわしいのかなというところがあります。なので、私どもの会派は２つでいいと考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"せりざわ委員","kind":"提案","question":"１つがいいのか、２つがいいのではないかというご提案をしておりますので、そこから特段意見の変更はありませんとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"こんの委員","kind":"提案","question":"公明党からも４本提案はしましたけれども、ほかの会派からもそうした提案の項目も出ていますので、そうした整理ができると２本でよろしいのかなと思いましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"１点だけ。意見だけ言わせてくださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"１点、コメントさせていただきたいのですけれども、ぜひ調査事項の中に織り込んでいただきたいです。併せて調査事項については、別途、この２つの委員会の中で改めてご調整をいただきたいと思ってあります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"提案","question":"それと、避難生活という公明党の提案はすごくいいと思います。これも非常にいい提案ではないかと思いますので、ぜひ特別委員会で議論していただいてもいいのではないかなというご意見を伝えしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"こんの委員","kind":"提案","question":"もう一つが、災害・環境対策特別委員会では、今、５つ挙げていただいたのでしょうか。環境に関することなので、「環境に関すること」と大きく２つにして、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"山本委員","kind":"提案","question":"「デジタル化に関すること」ということで、多くテーマが扱えるような形にしてはいかがかというのが、ご提案の１つです。特に災害・環境対策の中に入れるのがよいかとは思いますが、調査事項で複数の会派から明確にご提案がありますので、入れていただきたいですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"こんの委員","kind":"確認","question":"１点だけ確認です。それは、ここではやらないのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"こんの委員","kind":"提案","question":"では、調査事項までということで、その細かい内容については、ご提案があって、そこで調整していくという理解でいいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"１３人の決め方は、工夫があってもいいのではないかと思うのです。具体的に言うと、今のルールありきで行かなくてもいいのではないかという思いがあるのですけれども、いかがか尋ねました。","respondent":"大澤区議会事務局長","answer":"これまで、人数割は、会派の比例配分で決めておりました。","id":"exchange-021"}]},{"id":"topic-02","title":"その他の(1)議長からの報告","agenda":"その他の(1)議長からの報告","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"ここなのかと思ったのですけれども、前回、区議会だよりの件で、議会運営委員会に相談と議論があったと思うのです。最終的に議長一任のような感じになったことがどうなったのかとの意見を述べました。","respondent":"渡辺議長","answer":"そして、当該議員にも、私から直接お伝えして、ご理解をいただきました。ご協力ありがとうあります。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"須貝委員とも内容を確認しながら作成しました。その点についても、ぜひご検討をお願いしたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問・要望","question":"各会派から事実確認のため中塚亮議員に説明を求める意見が出され、会派・無所属議員の代表による聴取及び質疑を行った」となっているのです。ここで議会として中塚亮議員からの説明を求めたということだけではなくて、質疑を行った」としていただくと、入れていただけるとよいかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"趣旨としては、より議会運営委員会での対応を丁寧に強調してほしいということだと思います。今、塚本委員に提案していただいた案文を参考にして、さらに反映できたらと思っていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"少し待ってください。〔「説明を聴取し、質疑を行った」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"須貝委員","kind":"提案","question":"私も提案者になりますが、もし提案者になっていただける方がいましたら、お願いしてみたらどうでしょうか。早急に動いてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759442?Template=document&Id=6655#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":17977,"voices":90}},{"id":"r06-20240416-6","meetingId":"r06-cm04","date":"2024年4月16日","dateIso":"2024-04-16","committee":"区民委員会","time":"午後 １時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"令和５年度、町会・自治会課題解決支援事業報告書","agenda":"令和５年度、町会・自治会課題解決支援事業報告書","exchanges":[{"speaker":"せらく委員","kind":"質問","question":"令和６年度の実施予定についてお聞きしたいのですけれども、（１）の伴走型支援プログラム、５町会というのはもう決まっているのか尋ねました。","respondent":"宮澤地域活動課長","answer":"今、この報告書の内容を各地区各町会・自治会に説明しておりまして、併せて令和６年度の支援を求めている町会・自治会を募集しているので、今は決まっていなくて、募集中という形です。","id":"exchange-001"},{"speaker":"せらく委員","kind":"質問","question":"ご説明しながら募集をしている形ということで、あと、５町会よりも増えた場合はどのような対応を検討されているか説明を求めました。","respondent":"宮澤地域活動課長","answer":"もし応募が５町会を超えた場合の対応ですけれども、令和４年度からこの事業を行っておりまして、その間に支援させていただいた町会から改めてまた。それでもまた、町会数が大きく超えた場合に関しては、抽せんをするなど検討したいと考えています。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"それから、横のつながりを形成するための交流会の開催というのは、いずれもよい取組であると私は考えております。それで、区としてこれをやってみての評価、それからやった上での課題というのがあれば、お聞かせほしいと求めました。","respondent":"宮澤地域活動課長","answer":"それをいかに進めていくかということで、こういったコンサルタントを入れて伴走型支援ということでも取り組んでいるところですけれども、やはり。その中でもご意見があったのが、第１回目のほうのイベントの新しい実施方法というところなのですけれども、お話がありました。","id":"exchange-003"},{"speaker":"山本委員","kind":"質問・要望","question":"２０１ある中でご参加いただいているというのが１割程度、１割に満たないところでいうと、そういった取組をお願いしたいというところです。１点、令和６年度の実施予定、どのような経緯だったのかというのを教えてほしいと求めました。","respondent":"宮澤地域活動課長","answer":"交流会の部分につきましてなのですけれども、各町会・自治会に説明をするというところが一つ、ちょっと事業内容として変化を加えたところです。今年度もぜひやっていただきたいというお声もいただいていますので、そこに関しては時期を見て取り組み…","id":"exchange-004"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ、繰り返しになりますけれども、全体への、その他の町会・自治会への広がりへのアクションを取っていただきたいということで、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"提案","question":"その中で一つ提案も含めてなのですけれども、どういう感覚を持たれているのかななどというお話もできるので、非常にありがたい。これ何回か私も提案しているのですけれど、提案というか、この３点まとめてお伺いしますとの意見を述べました。","respondent":"宮澤地域活動課長","answer":"その中のアンケートの回答というのも、やはりその回答の中には、両面でやっていく必要があるのだろうなと感じているところです。３点目の、そういった成功事例をちょっと集めさせていただきまして、覚書のひな形となるようなものも手引の中に入れていきたいなと考えております。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"意見","question":"そういう成功事例、誘いやすいようなものを載せていただけるということでしたので、楽しみにしておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問","question":"今回この１年間で終わってしまいますけれども、あとは１７ページも見てなのですけども、詳細な分析がもし分かれば教えてください。最後に、例えば防災とかほかの課とどのように連携して、こうした手引に反映させていくのかというところも説明を求めました。","respondent":"宮澤地域活動課長","answer":"それを含めて、今年度また、今後どういうふうにしていくかというのは、これからちょっと検討していくというふうに伺っているところです。特に多く聞く声だというところで、まず、手引の作成ということを考えているところです。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"昨年度のアフターフォローを含めて、フォロー体制をしっかりお願いできればなと思いますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"八潮の担当課長、お見えになっているけれども、八潮というのはこういう自治会とかいうとちょっと特別な位置づけにされてしまうのですか。八潮も品川区の一つの自治会ですから、これからでいいですから、考えていくのか。","respondent":"宮澤地域活動課長、今井八潮まちづくり担当課長","answer":"今回の支援の中でもそうなのですけれども、特に、どういう活動をしているのかというのをきちんと説明できるようにしていきたいというふうに。抱えている悩み、課題というところにしっかりと寄り添って、対応していきたいと考えておりま… 代表するような方々にも参加していただいて、オール八潮で今後の八潮のまちづくりに向けて検討するといった取組を進めしています。今年度については、八潮のコンセプト検討の委託というものを予算としてつけさせていただいておりまして…","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"もう１回、やはり担当としては考えていかなければいけないと思うところも、少しあったのです。ですから、住んでいる方たちもそうだし、その辺というのはしっかりもみ込んでやっていくことが大事だと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"えのした委員","kind":"質問","question":"そのときに何かいい取組が見つからなくても、その後どうですかと一言声かけてあげるだけでもまた、これはちょっと私の感想も含めてなのですけれども。何ですか今後、今年度３年目になるので、その辺どういうふうにお考えかお聞かせ願えますか尋ねました。","respondent":"宮澤地域活動課長","answer":"この課題解決支援事業に関しましては、各町会・自治会にご説明することで、それぞれで新たに始めるきっかけになればというところでやっております。手引化しやすいところでありますので、そういったところも作成して横展開していきたいなと考えております。","id":"exchange-012"},{"speaker":"えのした委員","kind":"質問","question":"こういう条例があるのですよというお話をすると町会に入ってもらいやすいなんていうお話も伺ったことがありまして、建った後に幾ら待っていても。重要というか、そこからでないとやはり町会との関係性が結んでいけないかと思っているのですけど、その辺をいかがお考えか尋ねました。","respondent":"宮澤地域活動課長","answer":"やはり建築段階から関係性を持って、覚書を結んで、加入に成功したという事例もあります。様々、やはり町会ごとに抱えている、今回の手引というのはなるべくそういう類型に沿った形でのものにしていきたいと考えております。","id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"１つだけいいですか、調べると出てくるのです、「Ｉｎｓｔａｇｒａｍはじめました」というチラシなどが。この品川の町会・自治会の個別の紹介ページの中にＳＮＳのアカウントを追加したらどうかなというふうに思ったのですけれども、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"Ｉｎｓｔａｇｒａｍを進めていくというふうになっていて、これから情報発信をしていく、まだ発信されている情報というのがないというところです。町会・自治会連合会のホームページもありますので、そういったところも活用しながら、広く周知していければというふうなところです。","id":"exchange-014"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"山本委員","kind":"質問・要望","question":"時間のない中恐れ入れますが、ちょっと気になったので、ぜひこういったことがないように、再発防止はしっかりやっていただきたいというのが思いなのですけども、９件あった、その誤交付されたものについてはどのようになったのか、教えてほしいと求めました。","respondent":"築山戸籍住民課長","answer":"こちらはすぐに、ご本人と連絡、電話番号が分かる方についてはすぐに電話で確認をしまして、差し替えの対応をさせていただきました。その方につきましては、速達で正しいものを送付させていただきまして、郵送で差し替えの対応をさせていただいたところです。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/332921?Template=document&Id=6663#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":16459,"voices":60}},{"id":"r06-20240416-7","meetingId":"r06-cm04","date":"2024年4月16日","dateIso":"2024-04-16","committee":"厚生委員会","time":"午後 １時００分～午後 ４時５４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"令和６年陳情第２０号、重度障害者が入居できるグループホームの運営支援を区に求める陳情","agenda":"令和６年陳情第２０号、重度障害者が入居できるグループホームの運営支援を区に求める陳情","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"先ほど、８７名の応募があったとお聞きしましたが、こちらの区内区外のそれぞれの人数がもし分かりましたら、お知らせください。配置のところで、常勤１０人ということでしたが、どういった方で、資格等がもしあれば、資格職の方など、詳細を教えていただけると助かります。","respondent":"松山障害者支援課長","answer":"それから３点目ですが、配置される職員の資格者数ということですが、先ほど申しました１０人の方のうち７人が有資格者です。介護福祉士、あるいは社会福祉士を保有されているということで報告をいただいております。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"確認","question":"ほとんど品川区の区内の方ということで確認いたしました。４以上の方が多くなるのかなと思いますが、区分の４から６の方が多いのかなと思いますが、その辺はいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"当然ながら、支援区分が高い方を優先しておりますので、Ａの方は４、５、６が非常に多いということになっております。例えば訪問看護を入れるなどの可能性もありますし、今、区立の中でもそのように対応しているグループホームもあります。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点を伺いたいのですけれども、５とか６という、その点を伺いたいと思います。この陳情のところの港区は空床型の短期入所は医療的ケアのある方の受入れを求めていますということで書かれているのですけれども、その点も伺います。","respondent":"松山障害者支援課長","answer":"支援区分が高い方、支援区分の高い人から当たってくださいと、ご案内をしてくださいというふうに指定管理者には申し上げております。２つ目の港区の医療的ケアの方の受入れが実際にあるかということなのですが、今のところ、受入れは行っていないということを確認しております。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今の、ここに心配されているような重度の方が入れないということにはならないのが今回の出石だということで確認させていただいていいのですよね。その中で実際に支援区分５とか６の方は、実際は入られていないのか、その点も教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"あるいは、どういう個別支援が必要なのかということを実際に聞き取った上での対応が可能かどうかということが指定管理者の判断によるものです。個別対応になるものです。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問・要望","question":"グループホームで申し込んだ８７人の方とは関係なく、その確認をお願いしたいのと、港区は５人なのですよね。なぜ港区などよりも介護報酬が多いという見込みになるのか、そこら辺のところが分かったら教えていただきたいのと、どう考えられているのか尋ねました。","respondent":"松山障害者支援課長","answer":"港区の場合は、令和３年度の実績が陳情に記載されておりますので、もう既に安定的に運営をされているものと考えます。この運営収支につきましても、区分４の方を中心に考えた運営収支ということになっておりますので、きちんと運営を支援しているという状況です。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"事業者とのやり取りで、これでやりくりできますよという、そういうことでの指定管理料として決まったというふうなことで捉えていいですか。もう１つ、Ａの区分は何点くらいになるのか、Ｂの区分が何点くらいになるのかということも教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"生活支援員、４対１以上というものがありましたけれども、６対１ということでグループホームの基準では出されております。Ｂ区分の方につきましては８点、Ｃ区分の方につきましては７点以下ということです。","id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問","question":"もう１つ伺いたいのが、どれぐらい待機者がいらっしゃるかということで伺ったときには、何人ぐらいの方が申し込まれたのかも伺いたいと思います。","respondent":"松山障害者支援課長","answer":"区内外の施設、グループホームからのご要望があった方については、２２人の方のご要望がありました。その方を合わせると、大体見込みとしては５０人、その方々がプラスされた人数が申し込みいただいたということで把握しています。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２２人の方が、やはり本来であれば、区内にあれば入りたかったということで、品川区に戻ってきたいという方なのだなと、改めてこの人数を考えると、やはりこれからももっとグループホームを、こういう希望に沿った形で、ぜひともつくっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"ひがし委員","kind":"確認","question":"障害支援区分の点数は４から６が合わせて全部２点になっていまして、最初に優先的に区分６の方の重症度が重い方々から面談とかをしているということだったら、この点数の決め方はどういうふうに決めたのかというところをまずは確認させてください。","respondent":"松山障害者支援課長","answer":"Ａの方にも、Ｂの方にも、４から６の方は非常に多いです。区としましては、審査会の委員の方々にもご了承いただきながら、そのように決めさせていただきました。","id":"exchange-009"},{"speaker":"ひがし委員","kind":"確認","question":"区としては、やはり区分が高い６から先にやっていただくというふうにお願いをしているということの認識で合っていますでしょうかという点と、あとは。その最初の決定権は区にあるのかというところも確認をさせてください。","respondent":"松山障害者支援課長","answer":"区分の高い方から入れていきたいという区の認識についてです。その認識の下、指定管理者にはご案内を、まず最優先にしてくださいというお願いをしています。","id":"exchange-010"},{"speaker":"ひがし委員","kind":"確認","question":"推薦の決定は区が最終的にしたということで確認ができたのですけれども、決定権がどこにあるのかという質問だったと思うのでその点について、お答えほしいと求めました。","respondent":"松山障害者支援課長","answer":"最終的には、指定管理者とご本人との契約に基づいて、双方合意の上で契約をするということになります。共同生活援助サービスを利用していただくような決定はできるのですが、どこにというのは、ご本人と運営事業者との契約ということになります。","id":"exchange-011"},{"speaker":"ひがし委員","kind":"確認","question":"Ａの点数が２８人というふうにいらっしゃって、面談等をしながら決めていくべきではあると思うのですけれども、何か言える場はあるのかというところを再度確認させていただいてもよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"何かあれば、指定管理のモニタリング等を通じまして、また、初年度ですので、密に指定管理者と連携をとりながら協議していければと考えています。今後も情報連携をきちんととりながら…","id":"exchange-012"},{"speaker":"ひがし委員","kind":"質問・要望","question":"なので、せっかくつくった整備を利用できるように、人員の配置も含めて取り組んでいただきたいというふうに思っております。その点について、港区と比べて、ここについても改めてもう１回説明をいただいてもよろしいか尋ねました。","respondent":"松山障害者支援課長","answer":"支援区分が高い、障害福祉サービスの報酬を指定管理者の収入とすることで、インセンティブを付与しているような仕組みとしております。経営努力をしながら収入を増やしていくということで、安定したグループホームの運営につなげていくということが目的となっております。","id":"exchange-013"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そのサービスは、そういうところで障害区分が高い方を入れると、指定管理者のほうにも金額として多く入るというところも確認ができたと考えています。もっとサービスを何か入れてほしいというようなお声かけがあったときには、追加で予算等も検討してほしいと求めましたので、以上とします。","respondent":"松山障害者支援課長","answer":"指定管理料についてです。指定管理料については、また検討していくということで、来年度に向けて考えたいと思います。","id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"４から６の方が２８人で、区分Ａということになるので、１６人で入れる方は、ほとんどが４以上の方ということで考えていいのか。そうすると、４から６が中心というか、基本的に４以上になるのではないかということで考えていいのか尋ねました。","respondent":"松山障害者支援課長","answer":"区分６が７人ということで、それ以下の方が８人いらっしゃるという状態ですので、Ａ区分の方にまずは面接をしていただいている最中です。それが難しければ、Ｂ区分の方に当たっていただくという状況にあります。","id":"exchange-015"},{"speaker":"筒井委員","kind":"確認","question":"重度の方も含めて受け入れるという体制だということの確認と、このチラシにその旨が書かれておりますけれども、その点の確認をしたいと思います。","respondent":"松山障害者支援課長","answer":"ただ、共同生活が可能な方といいましても、ここは指定管理者がどのように支援をしていくかというところがキーになるかと思ってあります。いずれにしましても、中重度の方を受け入れるグループホームに代わりはございません。","id":"exchange-016"},{"speaker":"筒井委員","kind":"確認","question":"重度障害者も利用はできるということが確認とれました。その確認をしたいと思います。","respondent":"松山障害者支援課長","answer":"報酬については指定管理者の収入になるということは、きちんと説明をしていますし、その上での運営収支計画を提出いただいている。それで、協議の上で決めているものです。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"今回の約４,２００万円は、きちんと指定管理者の方に入るということなのですけれども、そうした前提の下、今回、陳情者が言われている重度の障害者が利用するには不十分な人員体制と書いてありますけれども、人員体制については、これ、区としては十分だと考えておられるのか尋ねました。","respondent":"松山障害者支援課長","answer":"１０人のうち７人ということで、資格の必要のない方々ですけれども、世話人の方にも資格がある方を配置しているです。やはり支援が必要だということであれば、区としても、そのように依頼をしています。","id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"確認","question":"先ほどの筒井委員の質問の続きなのですが、区としては、手を挙げる事業者が増えるというような認識で行っているということでよろしいでしょうか。それを説明を求めました。","respondent":"松山障害者支援課長","answer":"やはり指定管理者の経営努力や創意工夫によって歳入が得られる、収入が得られるということは、手を挙げる事業者が多くなるというふうな認識ではおります。","id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"確認","question":"何か質問とか、こういうふうにしたほうがいいのではないかとか、そういう問合せは特に説明会の段階ではなかったのでしょうか。確認です。","respondent":"松山障害者支援課長","answer":"委員よりお問い合わせのあったご質問のようなものは、区には特にございませんでした。","id":"exchange-020"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これは要望になるかもしれませんけれども、人件費がかさむからとか、ぜひこの辺はしっかりと伴走してほしいと思います。これからどうなるのだろうと、区民の方にとっても必要とされているものなので、これもしっかり二人三脚でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこは確認をさせていただきましたので、初年度ですから、約２,７００万円という金額です。６の方々を受け入れたときに、決めていっていただきたい、どういうふうに区としては考えていらっしゃいますか尋ねました。","respondent":"松山障害者支援課長","answer":"あるいは、どういう支援が必要なのか、区としての支援がどういったものが必要なのかをきちんと相談しながら一緒に考えていきたいと考えています。やはり初年度をベースにして、きちんと指定管理者と協議しながら予算を要求するということをさせていただければと考えております。","id":"exchange-022"},{"speaker":"こんの委員","kind":"質問・要望","question":"柔軟に考えてくださるという理解をさせていただきました。そのお考えで、どうか指定管理者の事業者とよく協議をして進めてほしいと求めましたので、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"こしば副委員長","kind":"質問","question":"結論を出すで、不採択でお願いします。答弁をお聞きしまして、今回の陳情の趣旨の例えば１つであります指定管理料についても、不採択とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"指定管理料の考え方も柔軟にといったところも確認がとれましたし、人員配置、それから利用者の選定の考え方等々も確認をさせていただきましたので。そこを柔軟に考えて協議をしてくださるということも確認できましたので、残念ですが、沿いがたいと結論にします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"ひがし委員","kind":"質問・要望","question":"柔軟に検討してくださるということが確認できましたし、今回の陳情には沿いがたい、不採択とします。確認しましたように、区としても十分に引き続き支援をしていただけるように、こちらについては改めて強く要望をします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今、ご説明を伺って、重度の方が入所できるというふうなところは分かりました。ぜひとも体制をとってほしいと求めましたし、またショートステイのほうも、今後に向けても検討していっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"グループホームの趣旨の範囲内でしっかり重度障害者も利用できるような体制が整えられているということで、不採択です。しっかりこの運営体制が維持できるように、品川区も伴走をして、しっかりとこの事業が維持できるようにしっかりと見ていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"おぎの委員","kind":"質問・要望","question":"何よりも、事業者の熱意と、この中重度の方をとにかく想定しているということで、非常に期待をしております。やりやすいように協議をして、しっかり区としてもバックアップしていただきたいと思いまして、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"やなぎさわ委員","kind":"意見","question":"様々、理事者の方からのご回答で、しっかりと区としても考えてやられているなということも承知いたしました。この陳情の提出者の方も、こういった区民の方の声、趣旨採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"}]},{"id":"topic-02","title":"「第４期品川区地域福祉計画（素案）」に係るパブリックコメントの実施結果","agenda":"「第４期品川区地域福祉計画（素案）」に係るパブリックコメントの実施結果","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"令和４年分のものまで見つかったのですけれども、令和５年もされているのでしょうかということと、すごく幅広いではないですか。これはどういう形でＰＤＣＡサイクルをまとめられて、どういうメンバーでされているのか、その点を伺いたいと思います。","respondent":"東野福祉計画課長","answer":"メンバー的には、庁内の関係部署、子どもから高齢者、生活福祉、障害者、そういったところが網羅されているものです。こちらは福祉は広い分野ですので、そういった所管の取組について、年間の取組を確認していくという形をとってあります。","id":"exchange-031"},{"speaker":"鈴木委員","kind":"質問・要望","question":"年に１回というのは、ここの中にもどこかにあったか、公開はされているのですか。推進委員会、そこのところがよく分からなかったので、もう少し詳しく教えてほしいと求めました。","respondent":"東野福祉計画課長","answer":"地域福祉計画の６ページに記載がございまして、企業ですとか、そういったところで構成されている会議体があります。令和５年度の１サイクルが３月までということになりますので、これから１サイクルのところの活動状況についての確認を行ってまいります。","id":"exchange-032"},{"speaker":"鈴木委員","kind":"質問","question":"令和４年度までは、その年度内にやっていたと思うのですけれども、令和５年度分はまだされていないというなのでしょうか。どういうものをどう前進させていこうということになるのか、そこら辺のところがよく見えないので、もう少し教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"先ほどお話ししましたように、いろいろな団体の方からご発言をいただいて、それを今ある計画にどう生かしていくかというところで検討しております。その検討をどう生かしたかについても、併せて推進委員会の中で確認を行っていく、そういうやり方をしております。","id":"exchange-033"},{"speaker":"鈴木委員","kind":"意見","question":"ぜひ傍聴して実態を見せていただけたらなと思っていますので、今度、いつ頃やるのかということもお聞かせいただけたらと思います。２１年から準備を開始して、なぜこんなに移行準備に３年も４年もかかるのか、課題は何かあるのか改めてお聞かせいただけたらと思いますとの意見を述べました。","respondent":"東野福祉計画課長","answer":"令和７年度の本格実施に向けて、現在、動いているという状況です。まだできていない部分がございまして、今年度は事例を挙げながら内部での検討を進めて、重層的支援体制整備事業を完成させていこうです。","id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問・要望","question":"Ｎｏ.３１だ、Ｎｏ.３１で、どのようなアウトリーチがもう既にどれぐらいまでできているのかということを伺えたらなと思います。それからもう１つ、これはいつまでにどのようなメンバーで設置するのか、それも説明を求めました。","respondent":"東野福祉計画課長","answer":"その支援をどうしていくかという部分を、大体１か月に１回、話合いをしております。区では、昨年度からいち早く取組を始めておりまして、地域協議会の設立に向けまして、令和６年度の設立を予定しております。","id":"exchange-035"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ここで要望することではないかもしれないのですけれども、本編だと４９ページですけれども、これしか出てこないのです。区民の人にも、ぜひこの写真の差し替えはされたほうがいいのではないかなというふうに思いますので、ぜひこれはご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"},{"speaker":"こんの委員","kind":"質問・要望","question":"Ｎｏ.２９に１点だけあったのですけれども、ご要望については、事業を進める中で検討してまいりますとご回答。居住に関する支援の仕組みというこの２点なのですけれども、どんなふうに進めようとされているのか、その確認をさせてほしいと求めました。","respondent":"東野福祉計画課長","answer":"具体的な課題、それから、今後の進む方向性というところで、今ここに掲載できるボリュームのものを載せてあります。委員がおっしゃったようなことについて、どうかという部分を取り上げて、住宅課とも連携をとりながら進めてまいりたいと思います。","id":"exchange-037"},{"speaker":"こんの委員","kind":"提案","question":"ここで全てを表現するのは、住まいの確保は非常に大事なところで、これからひとり暮らし高齢者がますます増えるというような報道も見聞きしました。福祉計画課からも、そうした提案をしていただきながら進めてほしいと求めましたが、何かございましたらとの意見を述べました。","respondent":"東野福祉計画課長","answer":"委員のご提案のところにつきましては、区全体の中、住宅課とも連携をとりながら、よりお困りの高齢者、また、ほかにも困っている方にとって、どういう施策が展開できるかを考えてまいりたいと思います。","id":"exchange-038"},{"speaker":"おぎの委員","kind":"質問","question":"ご意見をお聞きできたので、清掃してほしい」という部分で、区では把握していらっしゃるのか尋ねました。","respondent":"東野福祉計画課長","answer":"民生委員ともつながりがありまして、民生委員協議会などでも、そういった孤立死のことがあります。区として、どのような体制がとれるか、孤独・孤立対策についても取組を始めているところですので、そことまた併せ持って考えていければと思います。","id":"exchange-039"},{"speaker":"おぎの委員","kind":"質問・要望","question":"先ほどもお話があったように、こういった事案の把握も含めて、ひとり暮らしの高齢者の方が安心して過ごせる環境をつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問・要望","question":"パブリックコメントＮｏ.２２の、品川区地域福祉計画の４３ページの６）災害時助け合いのしくみの充実の点から質問させてほしいと求めました。進捗として数字が、もし今分かるのであれば、その点も含めて教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"令和３年度から実施いたしまして、令和５年度の集計がまだできていないのですけれども、５２７人の作成が済んでいます。それ以外については、障害者支援課、防災課と一緒にお手紙を同封いたしまして、希望を募るという対応も行っております。","id":"exchange-041"},{"speaker":"ひがし委員","kind":"質問・要望","question":"やはり早急に進めていくべきだというふうに思いますので、改めて丁寧に進めていって、なるべく早く皆様が安心できるような体制の整備を進めていただくように要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"こんの委員","kind":"確認","question":"先ほどの質問の中で、後段の部分を除いての話ではなかったのですけれども、確認です。その辺を確認させてください。","respondent":"東野福祉計画課長","answer":"社会福祉協議会につきましても、あんしん居住サポートのところに、終活相談の担当を置いて、これから広く進めていくということで伺っております。区として何か連携をしてできることは整えていければと思っています。","id":"exchange-043"},{"speaker":"こんの委員","kind":"質問・要望","question":"おひとり暮らしの方の抱えている課題というところを捉えて、この辺も検討というか、進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"}]},{"id":"topic-03","title":"「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施結果","agenda":"「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施結果","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"このパブリックコメントとはまた別にヒアリングはヒアリングでまとめられているものがあるのか、その点を伺いたいと思います。この１１ページのＮｏ.５３のところに、職員に同席してほしいということで書かれているのですけれども、捉え方をお願いしたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"内容につきましては、障害福祉計画等策定委員会で行っておりまして、その中で３月１８日に行われました第４回のところで説明しております。ただ、今申し上げたようなところで…","id":"exchange-045"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その資料を、団体の方々がどういうことで要望されているかということが分かりますので、その点についても伺いたいと思います。どういうものなのか、その中身に関しての修正というところがあれば、その点についても伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"文言の表記のところで、表現のところで分かりにくい表現について、ご指摘をいただいたというようなところでの対応になってあります。「移動支援児（者）養成研修が移動支援従業者養成研修ではないか」ですとか、調査の結果で、そういったところのご意見をいただいたような状況で…","id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それはすごく修正しましたというので、いっぱい書かれているところがあるので、それはいいのです。それがあったらお聞かせいただきたいという、それとも、こういうふうに変えましたというふうなものがあれば教えてほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"８件中の７件ほどについては、訂正、それから表現のご指摘というような状況であったところが結果というようなところです。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問","question":"中身のことで少し伺いたいのですけれども、実績が見込み量を大幅に上回る場合もありますという、そういう回答がすごくたくさんあるのです。必要なサービスの供給量をしっかりと確保するために、見込み量との整合性をどう考えるのか、その点を伺いたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"計画としましては、見込み量の算出の方法ということで、推移を見ながら今後のサービス利用の見込み量について推計させていただいたところです。今後、サービス見込み量の推移をどういうふうに計算していくかというようなところについては…","id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう計画に変更するというところも含めて、サービスが足りなくて使えないということは今でもあるわけですから、いかがでしょうかということです。３０年で閉鎖するか、または３０年たったら土地代を払って続けるかみたいなことになってしまうのか、教えてほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"有償貸付であれば最大５０年間というようなところで、今回、無償貸付として３０年間での対応をさせていただいているということ。３０年で無償貸付けとしては、事業を続ける場合については… ３０年は無償貸付ということで間違いない、更新等を含めてご相談というところで間違いございません。","id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問","question":"でも、そういうふうに書いてあるわけではないですか、これは。違うのか。","respondent":"佐藤障害者施策推進課長","answer":"ご意見に対して直接答えたような形なので、貸付期間経過後の部分等については、詳しくお書きしていない部分はあります。貸付期間経過後に関しては、今申し上げたとおりです。","id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"はい、分かりました。多分これはそういうことが心配で質問されたのではないかと思うので、そういう丁寧な書き方にぜひしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私からは、１点だけ、こちらは小学校のインクルーシブ教育に関するものだと思います。まずは区内小学校全校へ特別支援学級を設置することで就学時に障害児が就学先を選択できる環境整備を求めます」ということで、どういった状況なのか。","respondent":"松山障害者支援課長","answer":"今お尋ねの特別支援学校のインクルーシブに関してのご質問ですが、このことにつきましては、教育委員会の所管となっておりますので、この場では回答は差し控えします。","id":"exchange-052"},{"speaker":"おぎの委員","kind":"質問","question":"そうですね。この後、学校現場との調整とかも方向性をお聞きしようかと思っていたのですが、また改めてそちらのほうに聞いてみたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"こんの委員","kind":"確認","question":"区としてはどういうふうに捉えていらっしゃるかというところを確認したいのですけれども、事業所では、どのように捉えていらっしゃいますでしょうか。３件ほどパブリックコメントのご意見もありますけれども、その辺、現場の課題は、区としてはどういうふうに捉えていらっしゃいますか。","respondent":"松山障害者支援課長","answer":"ご質問いただいたのは、コロナ禍の影響も実は非常に多くございまして、コロナ禍の中で相談を受けるというのはかなり厳しかったという課題があります。現場の課題を踏まえまして、今後…","id":"exchange-054"},{"speaker":"こんの委員","kind":"質問・要望","question":"１２ページのＮｏ.６４なのですけれども、同じ文章が２つ入ってしまっているので、ここは１つですよね。第４章と第３章の関係というふうにつながるのが、第２段落目のほうも同じ文書が入っているので、誤記載かなと思いますが、すみません。","respondent":"佐藤障害者施策推進課長","answer":"そうですね、ほかに質問が２つ並んでしまっております。失礼いたしました。","id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"改めてパブリックコメントの多さを見て、説明会が必要ではないかというふうに思ったのですけれども、いかがでしょうか。説明会をぜひ、そういうふうに方針に変えてほしいというふうに思っているのですが、その点も伺いたいと思います。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"それは令和５年度の利用をしている事業所はおりませんで、令和４年度に１事業所が利用している状況です。新たなグループホームが増えましたので、きちんと全部グループホームに改めて周知をしまして、またご意見等を協議していく予定で… 説明会等に関するご意見です。全体、こういった計画に対するパブリックコメント等の実施方法については、現時点では説明会の実施は考えていないところです。","id":"exchange-056"},{"speaker":"鈴木委員","kind":"質問・要望","question":"助成されて回るようになっていくといいなと思ったのですけれども、そこら辺の課題は、どういうことなのか伺えたらと思います。ずっと求めても、ぜひ方針の転換をしていただきたいということで、要望をさせてほしいと求めました。","respondent":"松山障害者支援課長","answer":"ご相談がある際に、運営費助成についてはご案内しているところなのです。やはり令和６年度、改めて周知を行いまして、どうやったらご活用いただけるのかと一緒に考えていければと考えています。","id":"exchange-057"},{"speaker":"ひがし委員","kind":"確認","question":"改めて確認したいのですけれども、ヒアリングに参加していない方々は、パブリックコメントでご意見を寄せてくださっているということでいいのかというところをご答弁ほしいと求めました。","respondent":"佐藤障害者施策推進課長","answer":"今回、こちらに書かせていただいているのは、パブリックコメントとして、それを団体のお名前でいただいたというような形になりますので、先ほど申し上げた団体のヒアリングの内容をこちらに反映しているということではございません。","id":"exchange-058"},{"speaker":"ひがし委員","kind":"質問・要望","question":"委員として確認したいというところと、ここについては、今後ぜひ提示していただけるといいなというふうに思います。そこの説明のところは、ぜひ私もしていただきたいというふうに思いますので、この点については要望とします。","respondent":"佐藤障害者施策推進課長","answer":"計画策定の経過についてのお話かと思います。その前の計画素案とパブリックコメントの実施結果についての報告ですので、当然、次回に向けてプロセスを検討させてただければと思います。","id":"exchange-059"},{"speaker":"ひがし委員","kind":"質問","question":"「質問しても、文面でパブリックコメントに質問することにしましたみたいな趣旨のところが書いてあったりするので、また検討していただければというふうに思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"目標４の福祉施設から一般就労への移行者数も、６０人から７７人と書いてありますけれども、具体的にどうやってやられていくのかなというところをお聞きしたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"委員におっしゃっていただいたとおり、もともと国の基本方針というところがございまして、各項目を定めさせていただいているところではあります。こちらに達成できるようなところで、それぞれの事業等の拡充を新たに図っていくというようなところで考えているところです。","id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"はい、分かりました。現状の３人から、もう１９人以上となったというふうに、そのまま大丈夫なのかということでお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"地域自立支援協議会というところがございまして、そちらの相談支援部会で、区内外の施設にアンケート調査を実施しまして。回答をいただいている方が１９人いらっしゃいましたので、それを踏まえて、１９という数字をここでは掲げしています。","id":"exchange-062"}]},{"id":"topic-04","title":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施結果","agenda":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施結果","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"それ以上の３.４倍以上というところが１７区、教えていただきたいなと思うのですけれども、他区の状況が分かったら教えてほしいと求めました。今回、基準額が６,５００円になりましたけれども、その保険料も２３区でどれくらいの位置なのかということについても教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"１０番目というところで、平均額を計算すると６,４１０円になるので、平均辺りの金額に落ち着いたのかなというところになっております。多段階等につきましては、まだその辺りの集計結果が示されておりませんので、今の段階では他区の状況は分からないというところになっていま…","id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私はぜひ国に求めていただきたいと思うのですけれども、４・５月までは、国が直接出したというふうなことになっていると思うのです。どうしても介護保険料に関わりますので、ぜひ対応してほしいということを求めていただきたいと思うのですが、その点を伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"今回、９５ページのところで書かせていただきました居住支援手当については、一般財源でというところで対応させていただいているところです。今も国は介護報酬で６月からという、補助金で対応を一時的にしていると聞いておりますが…","id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問・要望","question":"求められていると思いますので、区としても、ぜひ求めていただきたいということでお願いしておきたいと思います。残り６.５億円になるという、この基金の状況も２３区の状況が分かったら、教えていただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"１００億円近く持っていたりとか、５０億円ぐらい持っていたりとか、本当に様々でした。１人当たりの基金が、他区の基金等の動向も見ながら、区としても検討していきたいと考えています。","id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"出していないというのは承知しているのですけれども、現場レベルで、品川区のケアマネジャーからこのようなことを聞いたのです。品川区のプラス１万円の手当の対象にならないかもしれないということをお伺いしたのですけれども、お教えいただきたいのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"年数をどの辺にするかとかということを、今、限られた予算の中で検討していっているところです。そういったことをどこか説明会でお話ししたとかということも全くございませんので、今、検討の俎上に上がっているということでご理解ください。","id":"exchange-066"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"これの２ページの、効果があって拡大してほしいというようなご要望があって、ぜひ増やしていっていただきたい。改めて、その辺の予定というか、区のほうでどのようにお考えなのかお聞かせいただければなと思います。","respondent":"樫村高齢者地域支援課長、菅野高齢者福祉課長","answer":"これは機械を使ったトレーニングですので、ご自宅のほうに訪問してということはやってございません。ただ、そういった課題も把握はしておりますので、そういった手だてがないかというところは研究してまいりたいというふうに考えます。 高齢者地域支援課で行っております介護予防事業の１つのメニューとして、例えば、柔道整復師による機能訓練訪問事業もあります。結果、そのような接続的な事業展開もしているので…","id":"exchange-067"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"要望に近い形になってしまうかもしれないのですけれども、最近、通所介護事業所が品川区で１か所閉鎖になるという情報が入ってきたのです。職員の給与が上がっているかどうかということを、きちんと確認をぜひしてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"確かに年に何か所か閉鎖になるとかというお話も聞いております。そうは言っても、そういった事業者の動向など、利用状況については注視してまいりたいと思います。","id":"exchange-068"}]},{"id":"topic-05","title":"しながわ健康プラン２１および品川区がん対策推進計画の策定に向けた「健康に関する意識調査」結果報告","agenda":"しながわ健康プラン２１および品川区がん対策推進計画の策定に向けた「健康に関する意識調査」結果報告","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"今年度に策定委員会を両方、年４回と年３回を開催するということなのですけれども、これは別々の委員会が２つつくられるということなのでしょうか。そして、パブリックコメントを実施するというのは、およそいつぐらいになるのか、その点も伺いたいと思います。","respondent":"若生健康課長","answer":"委員会の考え方ですけれども、現在、この辺りも含めて運営方法について検討中ですけれども、原則として公開していくような形で考えております。それから、パブリックコメントですけれども、こちらは来年の１月を予定しております。","id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点では、早期発見、そこら辺の考え方はどうですかというふうなことを伺いたいと思います。それともう１つ、このＤ評価を改めて継続していただきたいというふうに思っているのですけれども、その考え方についても伺いたいと思います。","respondent":"若生健康課長","answer":"当然、現状では自己負担いただくことは適切なものだというふうには考えておりますが、自己負担を含めまして議論は進めていきたいと考えています。医師会の先生等も入って議論していく予定ですので、有効性を十分に検証しつつ、実施の可否も含めて検討していきたいと考えています。","id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところのご意見を伺うことが必要ではないかと思いますので、ぜひそうしてほしいと求めましたし、ぜひ継続できるような形でご検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"こんの委員","kind":"質問","question":"参考までに伺いたいのですけれども、ある程度、年齢別というものを見ているのかどうなのか。３６％、２０％から３０％が回答率というのが一般的なのですけれども、参考までにお伺いしたいと思います。","respondent":"若生健康課長","answer":"当然、３,０００件を人口比で男女別にそれぞれ割り振って、その辺の年代の偏りがないような形で調査をしているというような格好になっております。３０％台というところが一般的と予想されていましたので、回答いただけるような工夫はしておるのですが…","id":"exchange-072"},{"speaker":"こんの委員","kind":"質問","question":"インセンティブもつけてくださっていたというところは、非常に工夫をされているのだなというふうに分かりました。そのときに区民の方のご意見等々を伺いながら、検診率の向上といったところにつながっていくように、これからの取組を見ていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-073"},{"speaker":"筒井委員","kind":"意見","question":"４月１１日から始まると思うので、しながわ健康プラン２１は、１０年の計画になるのかなと考えています。１０年来の長い計画なので、２名ではなくて、この募集人数２名とした理由について説明を求めました。","respondent":"若生健康課長","answer":"あるいは、それのほかに、健康づくり推進協議会という地域が主体になって健康づくりを行っている区民を中心とした団体の方々を２名入れております。そういったところとの全体のバランスも考えまして、２名程度が適切なのではないかということで所管として判断したところです。","id":"exchange-074"},{"speaker":"筒井委員","kind":"質問・要望","question":"この事業者は、２０２０年の中間見直しのときにもやられた事業者の方だと思うのですけれども、具体的にどのようなことをやられていくのでしょうか。それともかなり深く入って、かなり深いところに突っ込んで作業をやられているのか、具体的にどのようなことをやられていくのかをお知らせください。","respondent":"若生健康課長","answer":"この健康プラン２１は、１０年間ということで、事務局と一緒にやっていくようなイメージで考えております。","id":"exchange-075"},{"speaker":"やなぎさわ委員","kind":"質問","question":"報告書の８６ページのところなのですけれども、お伺いしたいのが、精神的な不安状態に陥りにくいというふうに読み取っていらっしゃるのでしょうか。ご見解を伺います。","respondent":"若生健康課長","answer":"そういった思いがあった上で、クロス集計という形で、この２つの設問を組み合わせてやってみた。例えば、そういう不安が１か月間ないと答えた方の割合が一番多い結果で、そういった数字が実際に結果としてあらわれたです。","id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうなると、やはり区民のメンタルヘルス、心の健康という意味で、運動をするような機会とかを推進していきたいというような方針ということでよろしいか尋ねました。","respondent":"若生健康課長","answer":"この健康づくりと運動、スポーツは、かなり密接に関連していることから、現行の計画でも取り組んでいるところでありますので、委員おっしゃるとおり、そういった視点を重視して進めていくです。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問","question":"上から４つ目の「場所や施設がないから」というものも、そして、ジョギングをすると鬱病リスクが下がるということをおっしゃったと思います。ということで、何か受け止めがあればお願いします。","respondent":"若生健康課長","answer":"これは健康プラン２１の会議に、スポーツ推進課のほうにもご参画いただくような形を想定しておりますので、そういったことを含めて盛り上げていきたいと考えております。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"意見","question":"品川区が一体になって、横断型でぜひ実施してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/814344?Template=document&Id=6661#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":61243,"voices":229}}]);
